const _: () = assert!(
    kernel_semantic_index::KEY_ENCODING_REVISION
        == kernel_semantics::CANONICAL_EQ_KEY_ENCODING_VERSION as u64
);

static NEXT_RUNTIME_ROOT_ID: AtomicU64 = AtomicU64::new(1);

fn saturating_usize_sum(values: impl Iterator<Item = usize>) -> usize {
    values.fold(0_usize, usize::saturating_add)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct RuntimeRootVersion(u64);

impl RuntimeRootVersion {
    #[must_use]
    pub const fn raw(self) -> u64 {
        self.0
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RuntimeRootIdentity {
    root_id: u64,
    version: RuntimeRootVersion,
}

fn allocate_runtime_root_id() -> Result<u64, PhysicalExecutionError> {
    NEXT_RUNTIME_ROOT_ID
        .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |current| {
            current.checked_add(1)
        })
        .map_err(|_| PhysicalExecutionError::RuntimeRootIdentityExhausted)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct LayoutId(pub u128);

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum LayoutFamily {
    LogicalModelRows,
    RowStore,
    Columnar,
    KeyValue,
    AdjacencyList,
    DenseArray,
    Inverted,
    Custom,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct LayoutBinding {
    pub id: LayoutId,
    pub family: LayoutFamily,
}

impl LayoutBinding {
    pub const LOGICAL_MODEL_ROWS: Self = Self {
        id: LayoutId(0),
        family: LayoutFamily::LogicalModelRows,
    };

    /// Deterministic correctness-first physical representation used when a
    /// runtime root is rebuilt from semantic authority after recovery.
    pub const RECOVERY_ROW_STORE: Self = Self {
        id: LayoutId(1),
        family: LayoutFamily::RowStore,
    };
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct I64IndexBinding {
    pub relation: SemanticId,
    pub layout: LayoutBinding,
    pub key_column: usize,
    pub equivalence: SemanticId,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct SemanticIndexKeyPart {
    pub column: usize,
    pub equivalence: SemanticId,
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct SemanticIndexBinding {
    pub relation: SemanticId,
    pub layout: LayoutBinding,
    pub key_parts: Vec<SemanticIndexKeyPart>,
}

impl SemanticIndexBinding {
    #[must_use]
    pub fn single(
        relation: SemanticId,
        layout: LayoutBinding,
        column: usize,
        equivalence: SemanticId,
    ) -> Self {
        Self {
            relation,
            layout,
            key_parts: vec![SemanticIndexKeyPart {
                column,
                equivalence,
            }],
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum NativeColumn {
    Unit(usize),
    Bool(Vec<bool>),
    I64(Vec<i64>),
    F64Bits(Vec<u64>),
    Text(Vec<String>),
    Algebraic(Box<algebraic_native::AlgebraicNativeColumn>),
    LiveEntityIds {
        entity_type: SemanticId,
        values: Vec<kernel_types::EntityId>,
    },
    DenseLiveEntityIds {
        entity_type: SemanticId,
        ids: Arc<DenseEntityIds>,
        values: Vec<LocalEntityId>,
    },
    HistoricalEntityIds {
        entity_type: SemanticId,
        values: Vec<kernel_types::EntityId>,
    },
}

impl NativeColumn {
    pub fn dense_live_entity_ids(
        entity_type: SemanticId,
        ids: Arc<DenseEntityIds>,
        values: Vec<kernel_types::EntityId>,
    ) -> Result<Self, PhysicalExecutionError> {
        let values = values
            .into_iter()
            .map(|id| {
                ids.local(id)
                    .ok_or(PhysicalExecutionError::PhysicalTypeMismatch)
            })
            .collect::<Result<Vec<_>, _>>()?;
        Ok(Self::DenseLiveEntityIds {
            entity_type,
            ids,
            values,
        })
    }

    fn len(&self) -> usize {
        match self {
            Self::Unit(len) => *len,
            Self::Bool(values) => values.len(),
            Self::I64(values) => values.len(),
            Self::F64Bits(values) => values.len(),
            Self::Text(values) => values.len(),
            Self::Algebraic(column) => column.len(),
            Self::LiveEntityIds { values, .. } | Self::HistoricalEntityIds { values, .. } => {
                values.len()
            }
            Self::DenseLiveEntityIds { values, .. } => values.len(),
        }
    }

    fn estimated_heap_bytes(&self) -> usize {
        match self {
            Self::Unit(_) => 0,
            Self::Bool(values) => values.capacity().div_ceil(8),
            Self::I64(values) => values.capacity().saturating_mul(std::mem::size_of::<i64>()),
            Self::F64Bits(values) => values.capacity().saturating_mul(std::mem::size_of::<u64>()),
            Self::Text(values) => values
                .capacity()
                .saturating_mul(std::mem::size_of::<String>())
                .saturating_add(saturating_usize_sum(values.iter().map(String::capacity))),
            Self::Algebraic(column) => {
                std::mem::size_of::<algebraic_native::AlgebraicNativeColumn>()
                    .saturating_add(column.estimated_heap_bytes())
            }
            Self::LiveEntityIds { values, .. } | Self::HistoricalEntityIds { values, .. } => values
                .capacity()
                .saturating_mul(std::mem::size_of::<kernel_types::EntityId>()),
            Self::DenseLiveEntityIds { values, .. } => values
                .capacity()
                .saturating_mul(std::mem::size_of::<LocalEntityId>()),
        }
    }

    fn semantic_work_units_at(&self, index: usize) -> Result<usize, PhysicalExecutionError> {
        if index >= self.len() {
            return Err(PhysicalExecutionError::ColumnShapeMismatch);
        }
        match self {
            Self::Unit(_)
            | Self::Bool(_)
            | Self::I64(_)
            | Self::F64Bits(_)
            | Self::LiveEntityIds { .. }
            | Self::DenseLiveEntityIds { .. }
            | Self::HistoricalEntityIds { .. } => Ok(1),
            Self::Text(values) => Ok(1_usize.saturating_add(values[index].len())),
            Self::Algebraic(column) => column.semantic_work_units_at(index),
        }
    }

    fn value_at(&self, index: usize) -> Value {
        match self {
            Self::Unit(_) => Value::Unit,
            Self::Bool(values) => Value::Bool(values[index]),
            Self::I64(values) => Value::I64(values[index]),
            Self::F64Bits(values) => Value::F64Bits(values[index]),
            Self::Text(values) => Value::Text(values[index].clone()),
            Self::Algebraic(column) => column
                .value_at(index)
                .expect("validated algebraic native column index"),
            Self::LiveEntityIds {
                entity_type,
                values,
            } => Value::LiveEntityRef {
                entity_type: *entity_type,
                id: values[index],
            },
            Self::DenseLiveEntityIds {
                entity_type,
                ids,
                values,
            } => Value::LiveEntityRef {
                entity_type: *entity_type,
                id: ids
                    .external(values[index])
                    .expect("dense live entity column shares its revision identity map"),
            },
            Self::HistoricalEntityIds {
                entity_type,
                values,
            } => Value::HistoricalEntityId {
                entity_type: *entity_type,
                id: values[index],
            },
        }
    }

    pub fn from_typed_values(
        values: &[Value],
        ty: &kernel_schema::TypeExpr,
    ) -> Result<Self, PhysicalExecutionError> {
        use kernel_schema::{ScalarType, TypeExpr};
        let template = match ty {
            TypeExpr::Scalar(ScalarType::Unit) => Some(Self::Unit(0)),
            TypeExpr::Scalar(ScalarType::Bool) => Some(Self::Bool(Vec::new())),
            TypeExpr::Scalar(ScalarType::I64) => Some(Self::I64(Vec::new())),
            TypeExpr::Scalar(ScalarType::F64) => Some(Self::F64Bits(Vec::new())),
            TypeExpr::Scalar(ScalarType::Text) => Some(Self::Text(Vec::new())),
            TypeExpr::Scalar(ScalarType::LiveEntityRef(entity_type)) => Some(Self::LiveEntityIds {
                entity_type: *entity_type,
                values: Vec::new(),
            }),
            TypeExpr::Scalar(ScalarType::HistoricalEntityId(entity_type)) => {
                Some(Self::HistoricalEntityIds {
                    entity_type: *entity_type,
                    values: Vec::new(),
                })
            }
            _ => None,
        };
        if let Some(template) = template {
            return Self::from_values_like(&template, values.to_vec());
        }
        Self::algebraic(values, ty)
    }

    pub fn algebraic(
        values: &[Value],
        ty: &kernel_schema::TypeExpr,
    ) -> Result<Self, PhysicalExecutionError> {
        algebraic_native::AlgebraicNativeColumn::from_values(values, ty)
            .map(Box::new)
            .map(Self::Algebraic)
    }

    fn from_values_like(
        template: &Self,
        values: Vec<Value>,
    ) -> Result<Self, PhysicalExecutionError> {
        match template {
            Self::Unit(_) => {
                if values.iter().all(|value| matches!(value, Value::Unit)) {
                    Ok(Self::Unit(values.len()))
                } else {
                    Err(PhysicalExecutionError::PhysicalTypeMismatch)
                }
            }
            Self::Bool(_) => values
                .into_iter()
                .map(|value| match value {
                    Value::Bool(value) => Ok(value),
                    _ => Err(PhysicalExecutionError::PhysicalTypeMismatch),
                })
                .collect::<Result<Vec<_>, _>>()
                .map(Self::Bool),
            Self::I64(_) => values
                .into_iter()
                .map(|value| match value {
                    Value::I64(value) => Ok(value),
                    _ => Err(PhysicalExecutionError::PhysicalTypeMismatch),
                })
                .collect::<Result<Vec<_>, _>>()
                .map(Self::I64),
            Self::F64Bits(_) => values
                .into_iter()
                .map(|value| match value {
                    Value::F64Bits(value) => Ok(value),
                    _ => Err(PhysicalExecutionError::PhysicalTypeMismatch),
                })
                .collect::<Result<Vec<_>, _>>()
                .map(Self::F64Bits),
            Self::Text(_) => values
                .into_iter()
                .map(|value| match value {
                    Value::Text(value) => Ok(value),
                    _ => Err(PhysicalExecutionError::PhysicalTypeMismatch),
                })
                .collect::<Result<Vec<_>, _>>()
                .map(Self::Text),
            Self::Algebraic(template) => {
                algebraic_native::AlgebraicNativeColumn::from_values(&values, template.ty())
                    .map(Box::new)
                    .map(Self::Algebraic)
            }
            Self::LiveEntityIds { entity_type, .. } => values
                .into_iter()
                .map(|value| match value {
                    Value::LiveEntityRef {
                        entity_type: value_type,
                        id,
                    } if value_type == *entity_type => Ok(id),
                    _ => Err(PhysicalExecutionError::PhysicalTypeMismatch),
                })
                .collect::<Result<Vec<_>, _>>()
                .map(|values| Self::LiveEntityIds {
                    entity_type: *entity_type,
                    values,
                }),
            Self::DenseLiveEntityIds {
                entity_type, ids, ..
            } => values
                .into_iter()
                .map(|value| match value {
                    Value::LiveEntityRef {
                        entity_type: value_type,
                        id,
                    } if value_type == *entity_type => ids
                        .local(id)
                        .ok_or(PhysicalExecutionError::PhysicalTypeMismatch),
                    _ => Err(PhysicalExecutionError::PhysicalTypeMismatch),
                })
                .collect::<Result<Vec<_>, _>>()
                .map(|values| Self::DenseLiveEntityIds {
                    entity_type: *entity_type,
                    ids: Arc::clone(ids),
                    values,
                }),
            Self::HistoricalEntityIds { entity_type, .. } => values
                .into_iter()
                .map(|value| match value {
                    Value::HistoricalEntityId {
                        entity_type: value_type,
                        id,
                    } if value_type == *entity_type => Ok(id),
                    _ => Err(PhysicalExecutionError::PhysicalTypeMismatch),
                })
                .collect::<Result<Vec<_>, _>>()
                .map(|values| Self::HistoricalEntityIds {
                    entity_type: *entity_type,
                    values,
                }),
        }
    }

    fn select_positions(&self, positions: &[usize]) -> Result<Self, PhysicalExecutionError> {
        Ok(match self {
            Self::Unit(_) => Self::Unit(positions.len()),
            Self::Bool(values) => Self::Bool(
                positions
                    .iter()
                    .map(|&position| {
                        values
                            .get(position)
                            .copied()
                            .ok_or(PhysicalExecutionError::ColumnShapeMismatch)
                    })
                    .collect::<Result<Vec<_>, _>>()?,
            ),
            Self::I64(values) => Self::I64(
                positions
                    .iter()
                    .map(|&position| {
                        values
                            .get(position)
                            .copied()
                            .ok_or(PhysicalExecutionError::ColumnShapeMismatch)
                    })
                    .collect::<Result<Vec<_>, _>>()?,
            ),
            Self::F64Bits(values) => Self::F64Bits(
                positions
                    .iter()
                    .map(|&position| {
                        values
                            .get(position)
                            .copied()
                            .ok_or(PhysicalExecutionError::ColumnShapeMismatch)
                    })
                    .collect::<Result<Vec<_>, _>>()?,
            ),
            Self::Text(values) => Self::Text(
                positions
                    .iter()
                    .map(|&position| {
                        values
                            .get(position)
                            .cloned()
                            .ok_or(PhysicalExecutionError::ColumnShapeMismatch)
                    })
                    .collect::<Result<Vec<_>, _>>()?,
            ),
            Self::Algebraic(column) => {
                Self::Algebraic(Box::new(column.select_positions(positions)?))
            }
            Self::LiveEntityIds {
                entity_type,
                values,
            } => Self::LiveEntityIds {
                entity_type: *entity_type,
                values: positions
                    .iter()
                    .map(|&position| {
                        values
                            .get(position)
                            .copied()
                            .ok_or(PhysicalExecutionError::ColumnShapeMismatch)
                    })
                    .collect::<Result<Vec<_>, _>>()?,
            },
            Self::DenseLiveEntityIds {
                entity_type,
                ids,
                values,
            } => Self::DenseLiveEntityIds {
                entity_type: *entity_type,
                ids: Arc::clone(ids),
                values: positions
                    .iter()
                    .map(|&position| {
                        values
                            .get(position)
                            .copied()
                            .ok_or(PhysicalExecutionError::ColumnShapeMismatch)
                    })
                    .collect::<Result<Vec<_>, _>>()?,
            },
            Self::HistoricalEntityIds {
                entity_type,
                values,
            } => Self::HistoricalEntityIds {
                entity_type: *entity_type,
                values: positions
                    .iter()
                    .map(|&position| {
                        values
                            .get(position)
                            .copied()
                            .ok_or(PhysicalExecutionError::ColumnShapeMismatch)
                    })
                    .collect::<Result<Vec<_>, _>>()?,
            },
        })
    }

    fn swap_remove_at(&mut self, index: usize) -> Result<(), PhysicalExecutionError> {
        match self {
            Self::Unit(len) => *len -= 1,
            Self::Bool(values) => {
                values.swap_remove(index);
            }
            Self::I64(values) => {
                values.swap_remove(index);
            }
            Self::F64Bits(values) => {
                values.swap_remove(index);
            }
            Self::Text(values) => {
                values.swap_remove(index);
            }
            Self::Algebraic(column) => column.swap_remove_at(index)?,
            Self::LiveEntityIds { values, .. } | Self::HistoricalEntityIds { values, .. } => {
                values.swap_remove(index);
            }
            Self::DenseLiveEntityIds { values, .. } => {
                values.swap_remove(index);
            }
        }
        Ok(())
    }

    fn push_value(&mut self, value: &Value) -> Result<(), PhysicalExecutionError> {
        match (self, value) {
            (Self::Unit(len), Value::Unit) => *len += 1,
            (Self::Bool(values), Value::Bool(value)) => values.push(*value),
            (Self::I64(values), Value::I64(value)) => values.push(*value),
            (Self::F64Bits(values), Value::F64Bits(value)) => values.push(*value),
            (Self::Text(values), Value::Text(value)) => values.push(value.clone()),
            (Self::Algebraic(column), value) => column.push_value(value)?,
            (
                Self::LiveEntityIds {
                    entity_type,
                    values,
                },
                Value::LiveEntityRef {
                    entity_type: value_type,
                    id,
                },
            ) if entity_type == value_type => values.push(*id),
            (
                Self::DenseLiveEntityIds {
                    entity_type,
                    ids,
                    values,
                },
                Value::LiveEntityRef {
                    entity_type: value_type,
                    id,
                },
            ) if entity_type == value_type => values.push(
                ids.local(*id)
                    .ok_or(PhysicalExecutionError::PhysicalTypeMismatch)?,
            ),
            (
                Self::HistoricalEntityIds {
                    entity_type,
                    values,
                },
                Value::HistoricalEntityId {
                    entity_type: value_type,
                    id,
                },
            ) if entity_type == value_type => values.push(*id),
            _ => return Err(PhysicalExecutionError::PhysicalTypeMismatch),
        }
        Ok(())
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum NativeRelation {
    RowStore(Vec<kernel_query::Row>),
    Columnar {
        columns: Vec<Vec<Value>>,
        row_count: usize,
    },
    I64Columnar {
        columns: Vec<Vec<i64>>,
        row_count: usize,
    },
    TypedColumnar {
        columns: Vec<NativeColumn>,
        row_count: usize,
    },
}

impl NativeRelation {
    pub fn columnar(columns: Vec<Vec<Value>>) -> Result<Self, PhysicalExecutionError> {
        let row_count = columns.first().map_or(0, Vec::len);
        if columns.iter().any(|column| column.len() != row_count) {
            return Err(PhysicalExecutionError::ColumnShapeMismatch);
        }
        Ok(Self::Columnar { columns, row_count })
    }

    pub fn i64_columnar(columns: Vec<Vec<i64>>) -> Result<Self, PhysicalExecutionError> {
        let row_count = columns.first().map_or(0, Vec::len);
        if columns.iter().any(|column| column.len() != row_count) {
            return Err(PhysicalExecutionError::ColumnShapeMismatch);
        }
        Ok(Self::I64Columnar { columns, row_count })
    }

    pub fn typed_from_rows(
        rows: &[kernel_query::Row],
        column_types: &[kernel_schema::TypeExpr],
    ) -> Result<Self, PhysicalExecutionError> {
        if rows.iter().any(|row| row.len() != column_types.len()) {
            return Err(PhysicalExecutionError::ColumnShapeMismatch);
        }
        let mut columns = Vec::with_capacity(column_types.len());
        for (column_index, ty) in column_types.iter().enumerate() {
            let values = rows
                .iter()
                .map(|row| row[column_index].clone())
                .collect::<Vec<_>>();
            columns.push(NativeColumn::from_typed_values(&values, ty)?);
        }
        Self::typed_columnar(columns)
    }

    pub fn typed_columnar(columns: Vec<NativeColumn>) -> Result<Self, PhysicalExecutionError> {
        let row_count = columns.first().map_or(0, NativeColumn::len);
        if columns.iter().any(|column| column.len() != row_count) {
            return Err(PhysicalExecutionError::ColumnShapeMismatch);
        }
        Ok(Self::TypedColumnar { columns, row_count })
    }

    #[must_use]
    pub fn row_store(rows: Vec<kernel_query::Row>) -> Self {
        Self::RowStore(rows)
    }
}

fn value_heap_bytes(value: &Value) -> usize {
    match value {
        Value::Unit
        | Value::Bool(_)
        | Value::I64(_)
        | Value::F64Bits(_)
        | Value::LiveEntityRef { .. }
        | Value::HistoricalEntityId { .. } => 0,
        Value::Text(value) => value.capacity(),
        Value::Product(values) => values.values().fold(0, |bytes, value| {
            bytes
                .saturating_add(std::mem::size_of::<(SemanticId, Value)>())
                .saturating_add(value_heap_bytes(value))
        }),
        Value::Option(value) => value.as_deref().map_or(0, |value| {
            std::mem::size_of::<Value>().saturating_add(value_heap_bytes(value))
        }),
        Value::Variant { value, .. } => {
            std::mem::size_of::<Value>().saturating_add(value_heap_bytes(value))
        }
        Value::Seq(values)
        | Value::Set {
            elements: values, ..
        } => values
            .capacity()
            .saturating_mul(std::mem::size_of::<Value>())
            .saturating_add(saturating_usize_sum(values.iter().map(value_heap_bytes))),
        Value::Bag { entries, .. } => entries
            .capacity()
            .saturating_mul(std::mem::size_of::<(Value, u64)>())
            .saturating_add(saturating_usize_sum(
                entries.iter().map(|(value, _)| value_heap_bytes(value)),
            )),
        Value::Map { entries, .. } => entries
            .capacity()
            .saturating_mul(std::mem::size_of::<(Value, Value)>())
            .saturating_add(saturating_usize_sum(entries.iter().map(|(key, value)| {
                value_heap_bytes(key).saturating_add(value_heap_bytes(value))
            }))),
    }
}

fn native_relation_estimated_heap_bytes(relation: &NativeRelation) -> usize {
    match relation {
        NativeRelation::RowStore(rows) => rows
            .capacity()
            .saturating_mul(std::mem::size_of::<kernel_query::Row>())
            .saturating_add(saturating_usize_sum(rows.iter().map(|row| {
                row.capacity()
                    .saturating_mul(std::mem::size_of::<Value>())
                    .saturating_add(saturating_usize_sum(row.iter().map(value_heap_bytes)))
            }))),
        NativeRelation::Columnar { columns, .. } => columns
            .capacity()
            .saturating_mul(std::mem::size_of::<Vec<Value>>())
            .saturating_add(saturating_usize_sum(columns.iter().map(|column| {
                column
                    .capacity()
                    .saturating_mul(std::mem::size_of::<Value>())
                    .saturating_add(saturating_usize_sum(column.iter().map(value_heap_bytes)))
            }))),
        NativeRelation::I64Columnar { columns, .. } => columns
            .capacity()
            .saturating_mul(std::mem::size_of::<Vec<i64>>())
            .saturating_add(saturating_usize_sum(columns.iter().map(|column| {
                column.capacity().saturating_mul(std::mem::size_of::<i64>())
            }))),
        NativeRelation::TypedColumnar { columns, .. } => columns
            .capacity()
            .saturating_mul(std::mem::size_of::<NativeColumn>())
            .saturating_add(saturating_usize_sum(
                columns.iter().map(NativeColumn::estimated_heap_bytes),
            )),
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PhysicalRowSlot {
    generation: u64,
    position: Option<usize>,
    previous: Option<PhysicalRowId>,
    next: Option<PhysicalRowId>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct InstalledRelation {
    data: NativeRelation,
    row_ids: Vec<PhysicalRowId>,
    slots: Vec<PhysicalRowSlot>,
    free_slots: Vec<usize>,
    logical_head: Option<PhysicalRowId>,
    logical_tail: Option<PhysicalRowId>,
    scan_order_is_physical: bool,
}

fn installed_relation_estimated_retained_bytes(relation: &InstalledRelation) -> usize {
    std::mem::size_of::<InstalledRelation>()
        .saturating_add(native_relation_estimated_heap_bytes(&relation.data))
        .saturating_add(
            relation
                .row_ids
                .capacity()
                .saturating_mul(std::mem::size_of::<PhysicalRowId>()),
        )
        .saturating_add(
            relation
                .slots
                .capacity()
                .saturating_mul(std::mem::size_of::<PhysicalRowSlot>()),
        )
        .saturating_add(
            relation
                .free_slots
                .capacity()
                .saturating_mul(std::mem::size_of::<usize>()),
        )
}

impl InstalledRelation {
    fn new(data: NativeRelation) -> Self {
        let row_count = native_row_count(&data);
        let mut row_ids = Vec::with_capacity(row_count);
        let mut slots = Vec::with_capacity(row_count);
        for index in 0..row_count {
            let id = PhysicalRowId {
                slot: index,
                generation: 0,
            };
            row_ids.push(id);
            slots.push(PhysicalRowSlot {
                generation: 0,
                position: Some(index),
                previous: index.checked_sub(1).map(|slot| PhysicalRowId {
                    slot,
                    generation: 0,
                }),
                next: (index + 1 < row_count).then_some(PhysicalRowId {
                    slot: index + 1,
                    generation: 0,
                }),
            });
        }
        Self {
            data,
            row_ids,
            slots,
            free_slots: Vec::new(),
            logical_head: (row_count > 0).then_some(PhysicalRowId {
                slot: 0,
                generation: 0,
            }),
            logical_tail: row_count.checked_sub(1).map(|slot| PhysicalRowId {
                slot,
                generation: 0,
            }),
            scan_order_is_physical: true,
        }
    }

    fn row_id_at(&self, index: usize) -> Result<PhysicalRowId, PhysicalExecutionError> {
        self.row_ids
            .get(index)
            .copied()
            .ok_or(PhysicalExecutionError::ColumnShapeMismatch)
    }

    fn position(&self, id: PhysicalRowId) -> Option<usize> {
        let slot = self.slots.get(id.slot)?;
        (slot.generation == id.generation)
            .then_some(slot.position)
            .flatten()
    }

    fn remove_row(&mut self, index: usize) -> Result<PhysicalRowId, PhysicalExecutionError> {
        let id = self.row_id_at(index)?;
        let next_generation = self
            .slots
            .get(id.slot)
            .filter(|slot| slot.generation == id.generation && slot.position.is_some())
            .ok_or(RelQueryError::InconsistentIncrementalDelta)?
            .generation
            .checked_add(1)
            .ok_or(PhysicalExecutionError::HandleGenerationExhausted)?;
        remove_native_row(&mut self.data, index)?;
        self.row_ids.swap_remove(index);
        self.scan_order_is_physical = false;
        if let Some(moved_id) = self.row_ids.get(index).copied() {
            self.slots[moved_id.slot].position = Some(index);
        }

        let removed_slot = self
            .slots
            .get(id.slot)
            .cloned()
            .ok_or(PhysicalExecutionError::ColumnShapeMismatch)?;
        if removed_slot.generation != id.generation || removed_slot.position.is_none() {
            return Err(RelQueryError::InconsistentIncrementalDelta.into());
        }
        if let Some(previous) = removed_slot.previous {
            self.slots[previous.slot].next = removed_slot.next;
        } else {
            self.logical_head = removed_slot.next;
        }
        if let Some(next) = removed_slot.next {
            self.slots[next.slot].previous = removed_slot.previous;
        } else {
            self.logical_tail = removed_slot.previous;
        }
        let slot = &mut self.slots[id.slot];
        slot.position = None;
        slot.previous = None;
        slot.next = None;
        slot.generation = next_generation;
        self.free_slots.push(id.slot);
        Ok(id)
    }

    fn next_logical_id(&self, id: PhysicalRowId) -> Option<PhysicalRowId> {
        let slot = self.slots.get(id.slot)?;
        (slot.generation == id.generation)
            .then_some(slot.next)
            .flatten()
    }

    fn scan_positions(&self) -> Box<dyn Iterator<Item = usize> + '_> {
        if self.scan_order_is_physical {
            Box::new(0..self.row_ids.len())
        } else {
            Box::new(
                std::iter::successors(self.logical_head, |id| self.next_logical_id(*id))
                    .filter_map(|id| self.position(id)),
            )
        }
    }

    fn planned_insert_ids(
        &self,
        removed: &[PhysicalRowId],
        count: usize,
    ) -> Result<Vec<PhysicalRowId>, PhysicalExecutionError> {
        let mut fresh_slot = self.slots.len();
        (0..count)
            .map(|offset| {
                if offset < removed.len() {
                    let removed_id = removed[removed.len() - 1 - offset];
                    let generation = self.slots[removed_id.slot]
                        .generation
                        .checked_add(1)
                        .ok_or(PhysicalExecutionError::HandleGenerationExhausted)?;
                    Ok(PhysicalRowId {
                        slot: removed_id.slot,
                        generation,
                    })
                } else {
                    let free_offset = offset - removed.len();
                    if free_offset < self.free_slots.len() {
                        let slot = self.free_slots[self.free_slots.len() - 1 - free_offset];
                        Ok(PhysicalRowId {
                            slot,
                            generation: self.slots[slot].generation,
                        })
                    } else {
                        let id = PhysicalRowId {
                            slot: fresh_slot,
                            generation: 0,
                        };
                        fresh_slot += 1;
                        Ok(id)
                    }
                }
            })
            .collect()
    }

    fn push_row(
        &mut self,
        row: &kernel_query::Row,
    ) -> Result<PhysicalRowId, PhysicalExecutionError> {
        push_native_row(&mut self.data, row)?;
        let position = self.row_ids.len();
        let id = if let Some(slot_index) = self.free_slots.pop() {
            let slot = &mut self.slots[slot_index];
            let id = PhysicalRowId {
                slot: slot_index,
                generation: slot.generation,
            };
            slot.position = Some(position);
            slot.previous = self.logical_tail;
            slot.next = None;
            id
        } else {
            let id = PhysicalRowId {
                slot: self.slots.len(),
                generation: 0,
            };
            self.slots.push(PhysicalRowSlot {
                generation: 0,
                position: Some(position),
                previous: self.logical_tail,
                next: None,
            });
            id
        };
        if let Some(previous) = self.logical_tail {
            self.slots[previous.slot].next = Some(id);
        } else {
            self.logical_head = Some(id);
        }
        self.logical_tail = Some(id);
        self.row_ids.push(id);
        Ok(id)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub(crate) enum UnifiedArtifactId {
    I64Index(I64IndexBinding),
    SemanticIndex(SemanticIndexBinding),
    ObservableAtom(SemanticIndexBinding),
    SemanticQuotientFactor(SemanticIndexBinding),
    SemanticQuotientSupport(SemanticQuotientSupportBinding),
    SemanticStatistics(SemanticIndexBinding),
}

impl UnifiedArtifactId {
    fn capabilities(&self) -> BTreeSet<PhysicalCapability> {
        match self {
            Self::I64Index(_) | Self::SemanticIndex(_) => {
                BTreeSet::from([PhysicalCapability::PointLookup])
            }
            Self::ObservableAtom(_) => BTreeSet::from([
                PhysicalCapability::ObservableFiber,
                PhysicalCapability::ExactCardinality,
            ]),
            Self::SemanticQuotientFactor(_) | Self::SemanticQuotientSupport(_) => {
                BTreeSet::from([PhysicalCapability::QuotientFiber])
            }
            Self::SemanticStatistics(_) => BTreeSet::from([PhysicalCapability::ExactCardinality]),
        }
    }

    fn touches_relation_layout(&self, relation: SemanticId, layout: LayoutBinding) -> bool {
        match self {
            Self::I64Index(binding) => {
                binding.relation == relation && binding.layout.id == layout.id
            }
            Self::SemanticIndex(binding)
            | Self::ObservableAtom(binding)
            | Self::SemanticQuotientFactor(binding)
            | Self::SemanticStatistics(binding) => {
                binding.relation == relation && binding.layout.id == layout.id
            }
            Self::SemanticQuotientSupport(binding) => {
                binding
                    .leaves
                    .iter()
                    .any(|(candidate_relation, candidate_layout, _)| {
                        *candidate_relation == relation && candidate_layout.id == layout.id
                    })
            }
        }
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PhysicalStore {
    relations: Arc<BTreeMap<(SemanticId, LayoutId), Arc<InstalledRelation>>>,
    i64_indexes: Arc<BTreeMap<I64IndexBinding, Arc<MaterializedI64IndexState>>>,
    semantic_indexes: Arc<BTreeMap<SemanticIndexBinding, Arc<MaterializedSemanticIndexState>>>,
    semantic_quotient_factors:
        Arc<BTreeMap<SemanticIndexBinding, Arc<MaterializedSemanticQuotientFactorState>>>,
    semantic_quotient_supports: Arc<
        BTreeMap<SemanticQuotientSupportBinding, Arc<MaterializedSemanticQuotientSupportState>>,
    >,
    semantic_statistics:
        Arc<BTreeMap<SemanticIndexBinding, Arc<MaterializedSemanticStatisticsState>>>,
    observable_atom_states:
        Arc<BTreeMap<SemanticIndexBinding, Arc<MaterializedObservableAtomState>>>,
    advisor_managed_artifacts: Arc<BTreeSet<UnifiedArtifactId>>,
    semantic_quotient_support_local_delta_updates: u64,
    transition_epoch: u64,
    revision: Option<RevisionId>,
    state_identity: Arc<()>,
}

/// Correctness-first storage prepare result. The retained source snapshot makes
/// freshness exact even for two different stores with equal epoch/revision counters.
#[derive(Debug, PartialEq, Eq)]
struct PreparedPhysicalStoreTransition {
    source_epoch: u64,
    source_revision: Option<RevisionId>,
    source_identity: Arc<()>,
    candidate: Box<PhysicalStore>,
    resolved_delta: StorageResolvedRelationDelta,
}

impl PreparedPhysicalStoreTransition {
    fn into_candidate_if_current(
        self,
        current: &PhysicalStore,
    ) -> Result<(PhysicalStore, StorageResolvedRelationDelta), PhysicalExecutionError> {
        if !current.can_commit_prepared(&self) {
            return Err(PhysicalExecutionError::StalePreparedTransition);
        }
        Ok((*self.candidate, self.resolved_delta))
    }
}

/// One normalized base-relation mutation participating in a logical revision.
/// A revision batch may contain several relations, but at most one mutation per
/// relation; callers normalize multiple edits to one relation before prepare.
pub struct RevisionRelationMutation<'a> {
    pub relation: SemanticId,
    pub delta: &'a RelationDelta,
}

/// One intent-bearing relation rewrite participating in a logical revision.
/// The embedded Γ-validated delta remains the DTC/physical maintenance effect;
/// Rewrite identity/law identity are preserved independently.
pub struct RevisionRelationRewrite<'a, I = Value> {
    pub relation: SemanticId,
    pub rewrite: &'a PreparedRelationRewrite<I>,
}

pub struct RevisionRewriteTransitionRequest<'a, I = Value> {
    pub target_revision: &'a kernel_revision::Revision,
    pub rewrites: &'a [RevisionRelationRewrite<'a, I>],
    pub registry: &'a kernel_semantics::SemanticRegistry,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RuntimeRewriteIntent {
    pub spec: RewriteSpecId,
    pub law_set: RewriteLawSetId,
}

/// One maintained query registered under the authoritative runtime revision.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RuntimeMaterializationSpec {
    pub id: kernel_types::MaterializationId,
    pub query: RelExpr,
}

/// Logical descriptor carried across the pre-durable seal boundary.
///
/// It intentionally contains semantic relation deltas rather than physical row
/// handles/layout mutations. A later WAL layer can serialize this descriptor
/// without making reconstructible physical state durable authority.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RevisionCommitDescriptor {
    source_revision: RevisionId,
    target: Box<kernel_revision::Revision>,
    change: RevisionCommitChange,
    rewrite_intents: BTreeMap<SemanticId, RuntimeRewriteIntent>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RevisionCommitChange {
    RelationData {
        semantic_revision: kernel_types::SemanticRevision,
        relation_deltas: BTreeMap<SemanticId, RelationDelta>,
    },
    FullRevision,
    FullRevisionAndMaterializations {
        materializations: Vec<DurableMaterializationSpec>,
    },
}

impl RevisionCommitDescriptor {
    #[must_use]
    pub const fn source_revision(&self) -> RevisionId {
        self.source_revision
    }

    #[must_use]
    pub fn target_revision(&self) -> RevisionId {
        self.target.id()
    }

    #[must_use]
    pub fn target(&self) -> &kernel_revision::Revision {
        self.target.as_ref()
    }

    #[must_use]
    pub const fn change(&self) -> &RevisionCommitChange {
        &self.change
    }

    #[must_use]
    pub const fn rewrite_intents(&self) -> &BTreeMap<SemanticId, RuntimeRewriteIntent> {
        &self.rewrite_intents
    }

    #[must_use]
    pub const fn semantic_revision(&self) -> Option<kernel_types::SemanticRevision> {
        match &self.change {
            RevisionCommitChange::RelationData {
                semantic_revision, ..
            } => Some(*semantic_revision),
            RevisionCommitChange::FullRevision
            | RevisionCommitChange::FullRevisionAndMaterializations { .. } => None,
        }
    }

    #[must_use]
    pub fn relation_deltas(&self) -> Option<&BTreeMap<SemanticId, RelationDelta>> {
        match &self.change {
            RevisionCommitChange::RelationData {
                relation_deltas, ..
            } => Some(relation_deltas),
            RevisionCommitChange::FullRevision
            | RevisionCommitChange::FullRevisionAndMaterializations { .. } => None,
        }
    }

    pub fn durable_descriptor(
        &self,
        transaction_id: ClientTransactionId,
        registry: &kernel_semantics::SemanticRegistry,
    ) -> Result<DurableRevisionDescriptor, DurabilityError> {
        match &self.change {
            RevisionCommitChange::RelationData {
                semantic_revision,
                relation_deltas,
            } => {
                let relation_mutations = relation_deltas
                    .iter()
                    .map(|(&relation, delta)| DurableRelationMutation {
                        relation,
                        inserted: delta.inserted.clone(),
                        removed: delta.removed.clone(),
                    })
                    .collect();
                if self.rewrite_intents.is_empty() {
                    Ok(DurableRevisionDescriptor::relation_data(
                        transaction_id,
                        self.source_revision,
                        self.target.as_ref(),
                        *semantic_revision,
                        relation_mutations,
                        registry,
                    )?)
                } else {
                    let rewrite_intents = self
                        .rewrite_intents
                        .iter()
                        .map(|(&relation, intent)| DurableRelationRewriteIntent {
                            relation,
                            rewrite_spec: intent.spec.0,
                            law_set: intent.law_set.0,
                        })
                        .collect();
                    Ok(DurableRevisionDescriptor::relation_rewrites(
                        transaction_id,
                        self.source_revision,
                        self.target.as_ref(),
                        *semantic_revision,
                        relation_mutations,
                        rewrite_intents,
                        registry,
                    )?)
                }
            }
            RevisionCommitChange::FullRevision => DurableRevisionDescriptor::full_revision(
                transaction_id,
                self.source_revision,
                self.target.as_ref(),
                registry,
            )
            .map_err(DurabilityError::Encode),
            RevisionCommitChange::FullRevisionAndMaterializations { materializations } => {
                DurableRevisionDescriptor::full_revision_and_materializations(
                    transaction_id,
                    self.source_revision,
                    self.target.as_ref(),
                    materializations,
                    registry,
                )
                .map_err(DurabilityError::Encode)
            }
        }
    }

    pub fn durable_resolution_descriptor(
        &self,
        transaction_id: ClientTransactionId,
        causal_parents: Vec<RevisionId>,
        registry: &kernel_semantics::SemanticRegistry,
    ) -> Result<DurableRevisionDescriptor, DurabilityError> {
        let RevisionCommitChange::RelationData {
            semantic_revision,
            relation_deltas,
        } = &self.change
        else {
            return Err(DurabilityError::Protocol {
                offset: 0,
                reason: "durable resolution requires relation-data change",
            });
        };
        if self.rewrite_intents.is_empty() {
            return Err(DurabilityError::Protocol {
                offset: 0,
                reason: "durable resolution requires exact Rewrite intent",
            });
        }
        let relation_mutations = relation_deltas
            .iter()
            .map(|(&relation, delta)| DurableRelationMutation {
                relation,
                inserted: delta.inserted.clone(),
                removed: delta.removed.clone(),
            })
            .collect();
        let rewrite_intents = self
            .rewrite_intents
            .iter()
            .map(|(&relation, intent)| DurableRelationRewriteIntent {
                relation,
                rewrite_spec: intent.spec.0,
                law_set: intent.law_set.0,
            })
            .collect();
        DurableRevisionDescriptor::relation_resolution(
            transaction_id,
            self.source_revision,
            self.target.as_ref(),
            *semantic_revision,
            DurableRelationResolution {
                relation_mutations,
                rewrite_intents,
                causal_parents,
            },
            registry,
        )
        .map_err(DurabilityError::Encode)
    }
}

#[derive(Debug)]
pub enum DurableRuntimeCommitError {
    Runtime(PhysicalExecutionError),
    Recovery(RuntimeRecoveryError),
    PrepareDurability(DurabilityError),
    CommitDurabilityUncertain(DurabilityError),
    TransactionIdConflict {
        transaction_id: ClientTransactionId,
        committed_target: RevisionId,
        requested_target: RevisionId,
    },
}

impl From<PhysicalExecutionError> for DurableRuntimeCommitError {
    fn from(value: PhysicalExecutionError) -> Self {
        Self::Runtime(value)
    }
}

