#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct SemanticAccessCostModel;

impl SemanticAccessCostModel {
    #[must_use]
    pub const fn join_scan_work(left_rows: usize, right_rows: usize) -> usize {
        left_rows.saturating_mul(right_rows)
    }

    #[must_use]
    pub const fn persisted_join_work(
        left_rows: usize,
        right_rows: usize,
        right_distinct_keys: usize,
    ) -> usize {
        if left_rows == 0 || right_rows == 0 || right_distinct_keys == 0 {
            return 0;
        }
        let average_bucket = right_rows.div_ceil(right_distinct_keys);
        left_rows.saturating_mul(1_usize.saturating_add(average_bucket))
    }

    #[must_use]
    pub const fn ephemeral_join_work(
        left_rows: usize,
        right_rows: usize,
        right_distinct_keys: usize,
        key_parts: usize,
    ) -> usize {
        if left_rows == 0 || right_rows == 0 || right_distinct_keys == 0 {
            return 0;
        }
        let key_parts = if key_parts == 0 { 1 } else { key_parts };
        let build_work = right_rows.saturating_mul(key_parts);
        build_work.saturating_add(Self::persisted_join_work(
            left_rows,
            right_rows,
            right_distinct_keys,
        ))
    }

    #[must_use]
    pub const fn choose_filter(row_count: usize, matching_rows: usize) -> SemanticAccessPath {
        let scan_work = row_count;
        let index_work = 1_usize.saturating_add(matching_rows);
        if index_work < scan_work {
            SemanticAccessPath::PersistedIndex
        } else {
            SemanticAccessPath::FullScan
        }
    }

    #[must_use]
    pub const fn choose_join(
        left_rows: usize,
        right_rows: usize,
        right_distinct_keys: usize,
    ) -> SemanticAccessPath {
        if left_rows == 0 || right_rows == 0 || right_distinct_keys == 0 {
            return SemanticAccessPath::PersistedIndex;
        }
        let nested_work = Self::join_scan_work(left_rows, right_rows);
        let indexed_work = Self::persisted_join_work(left_rows, right_rows, right_distinct_keys);
        if indexed_work < nested_work {
            SemanticAccessPath::PersistedIndex
        } else {
            SemanticAccessPath::FullScan
        }
    }

    #[must_use]
    pub const fn choose_ephemeral_join(
        left_rows: usize,
        right_rows: usize,
        right_distinct_keys: usize,
        key_parts: usize,
    ) -> SemanticAccessPath {
        if left_rows == 0 || right_rows == 0 || right_distinct_keys == 0 {
            return SemanticAccessPath::PersistedIndex;
        }
        let nested_work = Self::join_scan_work(left_rows, right_rows);
        let indexed_work =
            Self::ephemeral_join_work(left_rows, right_rows, right_distinct_keys, key_parts);
        if indexed_work < nested_work {
            SemanticAccessPath::PersistedIndex
        } else {
            SemanticAccessPath::FullScan
        }
    }
}

/// Minimal physical-plan vocabulary for the correctness-first baseline.
///
/// This is deliberately closed and contains no host callbacks, opaque expression
/// nodes, storage engines, caches, or hidden optimizer state. Physical choices
/// are explicit enum values so later specialized lowering can replace them
/// without changing logical query semantics.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Plan {
    Scan {
        relation: SemanticId,
        layout: LayoutBinding,
        algorithm: ScanAlgorithm,
    },
    FilterEqConst {
        input: Box<Self>,
        column: usize,
        value: Value,
        equivalence: SemanticId,
    },
    FilterEqColumns {
        input: Box<Self>,
        left_column: usize,
        right_column: usize,
        equivalence: SemanticId,
    },
    Project {
        input: Box<Self>,
        columns: Vec<usize>,
    },
    JoinEq {
        left: Box<Self>,
        right: Box<Self>,
        left_column: usize,
        right_column: usize,
        equivalence: SemanticId,
        algorithm: JoinAlgorithm,
    },
    Difference {
        left: Box<Self>,
        right: Box<Self>,
    },
    AntiJoin {
        left: Box<Self>,
        right: Box<Self>,
        left_column: usize,
        right_column: usize,
        equivalence: SemanticId,
    },
    Distinct {
        input: Box<Self>,
        column_equivalences: Vec<SemanticId>,
    },
    Group {
        input: Box<Self>,
        group_columns: Vec<usize>,
        group_equivalences: Vec<SemanticId>,
        aggregate: AggregateSpec,
        algorithm: GroupAlgorithm,
    },
    TopKWithTies {
        input: Box<Self>,
        column: usize,
        ordering: SemanticId,
        direction: OrderDirection,
        k: usize,
        algorithm: TopKAlgorithm,
    },
    PromoteToBag(Box<Self>),
}

