impl Plan {
    #[must_use]
    pub fn lower_baseline(expr: &RelExpr) -> Self {
        Self::lower_with_catalog(expr, &PhysicalCatalog::default())
    }

    #[must_use]
    pub fn lower_with_catalog(expr: &RelExpr, catalog: &PhysicalCatalog) -> Self {
        match expr {
            RelExpr::Scan(relation) => Self::Scan {
                relation: *relation,
                layout: catalog.relation_layout(*relation),
                algorithm: ScanAlgorithm::FullScan,
            },
            RelExpr::FilterEqConst {
                input,
                column,
                value,
                equivalence,
            } => Self::FilterEqConst {
                input: Box::new(Self::lower_with_catalog(input, catalog)),
                column: *column,
                value: value.clone(),
                equivalence: *equivalence,
            },
            RelExpr::FilterEqColumns {
                input,
                left_column,
                right_column,
                equivalence,
            } => Self::FilterEqColumns {
                input: Box::new(Self::lower_with_catalog(input, catalog)),
                left_column: *left_column,
                right_column: *right_column,
                equivalence: *equivalence,
            },
            RelExpr::Project { input, columns } => Self::Project {
                input: Box::new(Self::lower_with_catalog(input, catalog)),
                columns: columns.clone(),
            },
            RelExpr::JoinEq {
                left,
                right,
                left_column,
                right_column,
                equivalence,
            } => Self::lower_join(
                left,
                right,
                *left_column,
                *right_column,
                *equivalence,
                catalog,
            ),
            RelExpr::Difference { left, right } => Self::Difference {
                left: Box::new(Self::lower_with_catalog(left, catalog)),
                right: Box::new(Self::lower_with_catalog(right, catalog)),
            },
            RelExpr::AntiJoin {
                left,
                right,
                left_column,
                right_column,
                equivalence,
            } => Self::AntiJoin {
                left: Box::new(Self::lower_with_catalog(left, catalog)),
                right: Box::new(Self::lower_with_catalog(right, catalog)),
                left_column: *left_column,
                right_column: *right_column,
                equivalence: *equivalence,
            },
            RelExpr::Distinct {
                input,
                column_equivalences,
            } => Self::Distinct {
                input: Box::new(Self::lower_with_catalog(input, catalog)),
                column_equivalences: column_equivalences.clone(),
            },
            RelExpr::Group {
                input,
                group_columns,
                group_equivalences,
                aggregate,
            } => Self::Group {
                input: Box::new(Self::lower_with_catalog(input, catalog)),
                group_columns: group_columns.clone(),
                group_equivalences: group_equivalences.clone(),
                aggregate: aggregate.clone(),
                algorithm: GroupAlgorithm::LinearReplay,
            },
            RelExpr::TopKWithTies {
                input,
                column,
                ordering,
                direction,
                k,
            } => Self::TopKWithTies {
                input: Box::new(Self::lower_with_catalog(input, catalog)),
                column: *column,
                ordering: *ordering,
                direction: *direction,
                k: *k,
                algorithm: TopKAlgorithm::FullSort,
            },
            RelExpr::PromoteToBag(input) => {
                Self::PromoteToBag(Box::new(Self::lower_with_catalog(input, catalog)))
            }
        }
    }

    fn lower_join(
        left: &RelExpr,
        right: &RelExpr,
        left_column: usize,
        right_column: usize,
        equivalence: SemanticId,
        catalog: &PhysicalCatalog,
    ) -> Self {
        let left = Self::lower_with_catalog(left, catalog);
        let right = Self::lower_with_catalog(right, catalog);
        let algorithm = if direct_columnar_scan(&left) && direct_columnar_scan(&right) {
            JoinAlgorithm::IndexedPrimitiveIfAvailable
        } else {
            JoinAlgorithm::NestedLoop
        };
        Self::JoinEq {
            left: Box::new(left),
            right: Box::new(right),
            left_column,
            right_column,
            equivalence,
            algorithm,
        }
    }

    #[must_use]
    pub fn to_logical_expr(&self) -> RelExpr {
        match self {
            Self::Scan { relation, .. } => RelExpr::Scan(*relation),
            Self::FilterEqConst {
                input,
                column,
                value,
                equivalence,
            } => RelExpr::FilterEqConst {
                input: Box::new(input.to_logical_expr()),
                column: *column,
                value: value.clone(),
                equivalence: *equivalence,
            },
            Self::FilterEqColumns {
                input,
                left_column,
                right_column,
                equivalence,
            } => RelExpr::FilterEqColumns {
                input: Box::new(input.to_logical_expr()),
                left_column: *left_column,
                right_column: *right_column,
                equivalence: *equivalence,
            },
            Self::Project { input, columns } => RelExpr::Project {
                input: Box::new(input.to_logical_expr()),
                columns: columns.clone(),
            },
            Self::JoinEq {
                left,
                right,
                left_column,
                right_column,
                equivalence,
                ..
            } => RelExpr::JoinEq {
                left: Box::new(left.to_logical_expr()),
                right: Box::new(right.to_logical_expr()),
                left_column: *left_column,
                right_column: *right_column,
                equivalence: *equivalence,
            },
            Self::Difference { left, right } => RelExpr::Difference {
                left: Box::new(left.to_logical_expr()),
                right: Box::new(right.to_logical_expr()),
            },
            Self::AntiJoin {
                left,
                right,
                left_column,
                right_column,
                equivalence,
            } => RelExpr::AntiJoin {
                left: Box::new(left.to_logical_expr()),
                right: Box::new(right.to_logical_expr()),
                left_column: *left_column,
                right_column: *right_column,
                equivalence: *equivalence,
            },
            Self::Distinct {
                input,
                column_equivalences,
            } => RelExpr::Distinct {
                input: Box::new(input.to_logical_expr()),
                column_equivalences: column_equivalences.clone(),
            },
            Self::Group {
                input,
                group_columns,
                group_equivalences,
                aggregate,
                ..
            } => RelExpr::Group {
                input: Box::new(input.to_logical_expr()),
                group_columns: group_columns.clone(),
                group_equivalences: group_equivalences.clone(),
                aggregate: aggregate.clone(),
            },
            Self::TopKWithTies {
                input,
                column,
                ordering,
                direction,
                k,
                ..
            } => RelExpr::TopKWithTies {
                input: Box::new(input.to_logical_expr()),
                column: *column,
                ordering: *ordering,
                direction: *direction,
                k: *k,
            },
            Self::PromoteToBag(input) => RelExpr::PromoteToBag(Box::new(input.to_logical_expr())),
        }
    }

    #[must_use]
    pub fn shape(&self) -> PlanShape {
        let mut shape = PlanShape::default();
        self.accumulate_shape(&mut shape);
        shape
    }

    fn accumulate_shape(&self, shape: &mut PlanShape) {
        shape.nodes += 1;
        match self {
            Self::Scan { .. } => shape.scans += 1,
            Self::FilterEqConst { input, .. } | Self::FilterEqColumns { input, .. } => {
                shape.filters += 1;
                input.accumulate_shape(shape);
            }
            Self::Project { input, .. } => {
                shape.projects += 1;
                input.accumulate_shape(shape);
            }
            Self::JoinEq { left, right, .. } => {
                shape.joins += 1;
                left.accumulate_shape(shape);
                right.accumulate_shape(shape);
            }
            Self::Difference { left, right } | Self::AntiJoin { left, right, .. } => {
                left.accumulate_shape(shape);
                right.accumulate_shape(shape);
            }
            Self::Distinct { input, .. } => {
                shape.distincts += 1;
                input.accumulate_shape(shape);
            }
            Self::Group { input, .. } => {
                shape.groups += 1;
                input.accumulate_shape(shape);
            }
            Self::TopKWithTies { input, .. } => {
                shape.top_k += 1;
                input.accumulate_shape(shape);
            }
            Self::PromoteToBag(input) => {
                shape.bag_promotions += 1;
                input.accumulate_shape(shape);
            }
        }
    }

    /// Reference-only semantic execution used to falsify lowering. This is not
    /// the physical runtime and therefore carries no performance claim.
    pub fn reference_execute(
        &self,
        model: &kernel_model::FiniteModel,
        context: &kernel_schema::SemanticContext,
        registry: &kernel_semantics::SemanticRegistry,
    ) -> Result<RelationValue, RelQueryError> {
        self.to_logical_expr()
            .prepare(context, registry)?
            .evaluate(model, context, registry)
    }

    fn guarantees_set_uniqueness(&self) -> bool {
        match self {
            Self::Distinct { .. } | Self::Group { .. } => true,
            Self::FilterEqConst { input, .. }
            | Self::FilterEqColumns { input, .. }
            | Self::TopKWithTies { input, .. } => input.guarantees_set_uniqueness(),
            Self::Scan { .. }
            | Self::Project { .. }
            | Self::JoinEq { .. }
            | Self::Difference { .. }
            | Self::AntiJoin { .. }
            | Self::PromoteToBag(_) => false,
        }
    }

    pub fn execute_native(
        &self,
        store: &PhysicalStore,
        result_type: &RelType,
        context: &kernel_schema::SemanticContext,
        registry: &kernel_semantics::SemanticRegistry,
    ) -> Result<(RelationValue, ExecutionStats), PhysicalExecutionError> {
        self.execute_native_with_prepared_programs(
            store,
            result_type,
            context,
            registry,
            None,
            None,
        )
    }

    fn execute_native_with_prepared_programs(
        &self,
        store: &PhysicalStore,
        result_type: &RelType,
        context: &kernel_schema::SemanticContext,
        registry: &kernel_semantics::SemanticRegistry,
        anchor_pullback_program: Option<&PreparedAnchorPullbackProgram>,
        prepared_program: Option<&PreparedSemanticQuotientProgram>,
    ) -> Result<(RelationValue, ExecutionStats), PhysicalExecutionError> {
        let mut stats = ExecutionStats::default();
        let rows = if let Some(program) = anchor_pullback_program {
            let accelerated_quotient = prepared_program
                .map(|quotient| {
                    prepared_quotient_acceleration_available(
                        self, quotient, store, context, registry,
                    )
                })
                .transpose()?
                .unwrap_or(false);
            if accelerated_quotient {
                if let Some(quotient) = prepared_program
                    && let Some(rows) = try_execute_nway_order_preserving_join(
                        self,
                        Some(quotient),
                        store,
                        context,
                        registry,
                        &mut stats,
                    )?
                {
                    stats.multiway_join_reorders = stats.multiway_join_reorders.saturating_add(1);
                    stats.multiway_join_order_preserving_enumerations = stats
                        .multiway_join_order_preserving_enumerations
                        .saturating_add(1);
                    stats.multiway_join_prepared_quotient_hits =
                        stats.multiway_join_prepared_quotient_hits.saturating_add(1);
                    rows
                } else if let Some(rows) = try_execute_anchor_pullback_join(
                    self, program, store, context, registry, &mut stats,
                )? {
                    rows
                } else {
                    self.execute_native_rows(store, context, registry, &mut stats)?
                }
            } else if let Some(rows) = try_execute_anchor_pullback_join(
                self, program, store, context, registry, &mut stats,
            )? {
                rows
            } else if let Some(quotient) = prepared_program {
                if let Some(rows) = try_execute_nway_order_preserving_join(
                    self,
                    Some(quotient),
                    store,
                    context,
                    registry,
                    &mut stats,
                )? {
                    stats.multiway_join_reorders = stats.multiway_join_reorders.saturating_add(1);
                    stats.multiway_join_order_preserving_enumerations = stats
                        .multiway_join_order_preserving_enumerations
                        .saturating_add(1);
                    stats.multiway_join_prepared_quotient_hits =
                        stats.multiway_join_prepared_quotient_hits.saturating_add(1);
                    rows
                } else {
                    self.execute_native_rows(store, context, registry, &mut stats)?
                }
            } else {
                self.execute_native_rows(store, context, registry, &mut stats)?
            }
        } else if let Some(program) = prepared_program {
            if let Some(rows) = try_execute_nway_order_preserving_join(
                self,
                Some(program),
                store,
                context,
                registry,
                &mut stats,
            )? {
                stats.multiway_join_reorders = stats.multiway_join_reorders.saturating_add(1);
                stats.multiway_join_order_preserving_enumerations = stats
                    .multiway_join_order_preserving_enumerations
                    .saturating_add(1);
                stats.multiway_join_prepared_quotient_hits =
                    stats.multiway_join_prepared_quotient_hits.saturating_add(1);
                rows
            } else {
                self.execute_native_rows(store, context, registry, &mut stats)?
            }
        } else {
            self.execute_native_rows(store, context, registry, &mut stats)?
        };
        let value = match &result_type.semantics {
            kernel_schema::RelationSemantics::Set {
                column_equivalences,
            } if self.guarantees_set_uniqueness() => RelationValue::Set {
                rows,
                column_equivalences: column_equivalences.clone(),
            },
            _ => relation_value_from_rows(rows, result_type, context, registry)?,
        };
        stats.output_rows = value.rows().len();
        Ok((value, stats))
    }

    fn execute_native_rows(
        &self,
        store: &PhysicalStore,
        context: &kernel_schema::SemanticContext,
        registry: &kernel_semantics::SemanticRegistry,
        stats: &mut ExecutionStats,
    ) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
        if let Some(rows) = try_execute_multiway_join(self, store, context, registry, stats)? {
            return Ok(rows);
        }
        if let Some(rows) = try_execute_native_fast_path(self, store, context, registry, stats)? {
            return Ok(rows);
        }
        match self {
            Self::Project { input, columns } => {
                execute_project_plan(input, columns, store, context, registry, stats)
            }
            Self::FilterEqConst {
                input,
                column,
                value,
                equivalence,
            } => execute_filter_const(
                input,
                *column,
                value,
                *equivalence,
                store,
                &StatefulBatchEnv { context, registry },
                stats,
            ),
            Self::FilterEqColumns {
                input,
                left_column,
                right_column,
                equivalence,
            } => execute_filter_columns(
                input,
                *left_column,
                *right_column,
                *equivalence,
                store,
                &StatefulBatchEnv { context, registry },
                stats,
            ),
            Self::Scan {
                relation,
                layout,
                algorithm: ScanAlgorithm::FullScan,
            } => scan_rows(store, *relation, *layout, context, stats),
            Self::PromoteToBag(input) => input.execute_native_rows(store, context, registry, stats),
            _ => self.execute_native_rows_complex(store, context, registry, stats),
        }
    }

    fn execute_native_rows_complex(
        &self,
        store: &PhysicalStore,
        context: &kernel_schema::SemanticContext,
        registry: &kernel_semantics::SemanticRegistry,
        stats: &mut ExecutionStats,
    ) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
        match self {
            Self::JoinEq {
                left,
                right,
                left_column,
                right_column,
                equivalence,
                algorithm,
            } => execute_join_plan(
                left,
                right,
                *left_column,
                *right_column,
                *equivalence,
                *algorithm,
                store,
                context,
                registry,
                stats,
            ),
            Self::Difference { left, right } => {
                execute_difference_plan(left, right, store, context, registry, stats)
            }
            Self::AntiJoin {
                left,
                right,
                left_column,
                right_column,
                equivalence,
            } => execute_anti_join_plan(
                left,
                right,
                AntiJoinPlanSpec {
                    left_column: *left_column,
                    right_column: *right_column,
                    equivalence: *equivalence,
                },
                store,
                &StatefulBatchEnv { context, registry },
                stats,
            ),
            Self::Distinct {
                input,
                column_equivalences,
            } => execute_distinct_plan(input, column_equivalences, store, context, registry, stats),
            Self::Group {
                input,
                group_columns,
                group_equivalences,
                aggregate,
                algorithm: GroupAlgorithm::LinearReplay,
            } => execute_group_plan(
                input,
                group_columns,
                group_equivalences,
                aggregate,
                store,
                context,
                registry,
                stats,
            ),
            Self::TopKWithTies {
                input,
                column,
                ordering,
                direction,
                k,
                algorithm: TopKAlgorithm::FullSort,
            } => execute_top_k_plan(
                input, *column, *ordering, *direction, *k, store, context, registry, stats,
            ),
            Self::Project { .. }
            | Self::FilterEqConst { .. }
            | Self::FilterEqColumns { .. }
            | Self::Scan { .. }
            | Self::PromoteToBag(_) => unreachable!("simple plan delegated to complex executor"),
        }
    }
}

fn execute_distinct_plan(
    input: &Plan,
    column_equivalences: &[SemanticId],
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let rows = input.execute_native_rows(store, context, registry, stats)?;
    distinct_rows(rows, column_equivalences, context, registry)
}

fn execute_filter_const(
    input: &Plan,
    column: usize,
    value: &Value,
    equivalence: SemanticId,
    store: &PhysicalStore,
    env: &StatefulBatchEnv<'_>,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let input_rows = input.execute_native_rows(store, env.context, env.registry, stats)?;
    filter_rows(
        input_rows,
        column,
        value,
        equivalence,
        env.context,
        env.registry,
        stats,
    )
}

fn execute_filter_columns(
    input: &Plan,
    left_column: usize,
    right_column: usize,
    equivalence: SemanticId,
    store: &PhysicalStore,
    env: &StatefulBatchEnv<'_>,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let input_rows = input.execute_native_rows(store, env.context, env.registry, stats)?;
    filter_rows_columns(
        input_rows,
        left_column,
        right_column,
        equivalence,
        env.context,
        env.registry,
        stats,
    )
}

fn execute_difference_plan(
    left: &Plan,
    right: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let left_rows = left.execute_native_rows(store, context, registry, stats)?;
    let right_rows = right.execute_native_rows(store, context, registry, stats)?;
    let left_type = left.to_logical_expr().typecheck(context, registry)?;
    let right_type = right.to_logical_expr().typecheck(context, registry)?;
    if left_type != right_type {
        return Err(RelQueryError::TypeMismatch.into());
    }
    let column_equivalences = match &left_type.semantics {
        kernel_schema::RelationSemantics::Set {
            column_equivalences,
        }
        | kernel_schema::RelationSemantics::Bag {
            column_equivalences,
        } => column_equivalences,
    };
    let left_value = relation_value_from_rows(left_rows, &left_type, context, registry)?;
    let right_value = relation_value_from_rows(right_rows, &right_type, context, registry)?;
    Ok(kernel_query::difference_relation_values(
        left_value,
        right_value,
        column_equivalences,
        context,
        registry,
    )?
    .into_rows())
}

#[derive(Debug, Clone, Copy)]
struct AntiJoinPlanSpec {
    left_column: usize,
    right_column: usize,
    equivalence: SemanticId,
}

fn execute_anti_join_plan(
    left: &Plan,
    right: &Plan,
    spec: AntiJoinPlanSpec,
    store: &PhysicalStore,
    env: &StatefulBatchEnv<'_>,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let left_rows = left.execute_native_rows(store, env.context, env.registry, stats)?;
    let right_rows = right.execute_native_rows(store, env.context, env.registry, stats)?;
    let left_type = left
        .to_logical_expr()
        .typecheck(env.context, env.registry)?;
    let right_type = right
        .to_logical_expr()
        .typecheck(env.context, env.registry)?;
    let left_value = relation_value_from_rows(left_rows, &left_type, env.context, env.registry)?;
    let right_value = relation_value_from_rows(right_rows, &right_type, env.context, env.registry)?;
    Ok(kernel_query::anti_join_relation_values(
        left_value,
        &right_value,
        spec.left_column,
        spec.right_column,
        spec.equivalence,
        env.context,
        env.registry,
    )?
    .into_rows())
}

fn try_execute_native_fast_path(
    plan: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    if let Some(rows) =
        try_execute_persisted_semantic_multi_key_join_plan(plan, store, context, registry, stats)?
    {
        return Ok(Some(rows));
    }
    if let Some(rows) =
        try_execute_persisted_semantic_filter_plan(plan, store, context, registry, stats)?
    {
        return Ok(Some(rows));
    }
    if let Some((rows, batch_stats)) =
        try_execute_typed_stateful_producer_chain(plan, store, context, registry)?
    {
        merge_execution_stats(stats, batch_stats);
        return Ok(Some(rows));
    }
    if let Some((rows, batch_stats)) =
        try_execute_typed_stateful_batch(plan, store, context, registry)?
    {
        merge_execution_stats(stats, batch_stats);
        return Ok(Some(rows));
    }
    if let Some((rows, batch_stats)) =
        try_execute_indexed_join_batch_chain(plan, store, context, registry)?
    {
        merge_execution_stats(stats, batch_stats);
        return Ok(Some(rows));
    }
    if let Some((rows, batch_stats)) =
        try_execute_typed_batch_chain(plan, store, context, registry)?
    {
        merge_execution_stats(stats, batch_stats);
        return Ok(Some(rows));
    }
    Ok(None)
}

#[derive(Debug, Clone, Copy)]
struct JoinBatchColumn {
    side: usize,
    column: usize,
}

#[derive(Debug)]
struct JoinBatchPredicate {
    column: JoinBatchColumn,
    expected: i64,
}

#[derive(Debug)]
struct IndexedJoinBatchProgram<'a> {
    left: &'a InstalledRelation,
    right: &'a InstalledRelation,
    left_columns: Vec<&'a [i64]>,
    right_columns: Vec<&'a [i64]>,
    left_key_column: usize,
    right_key_column: usize,
    equivalence: SemanticId,
    right_relation: SemanticId,
    right_layout: LayoutBinding,
    columns: Vec<JoinBatchColumn>,
    predicates: Vec<JoinBatchPredicate>,
    downstream_ops: usize,
    projected: bool,
}

enum JoinBatchIndex<'a> {
    Persisted(&'a MaterializedI64IndexState),
    Ephemeral(BTreeMap<i64, Vec<usize>>),
    FullScan,
}

fn select_join_batch_index<'a>(
    program: &IndexedJoinBatchProgram<'a>,
    store: &'a PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<JoinBatchIndex<'a>>, PhysicalExecutionError> {
    let left_keys = program
        .left_columns
        .get(program.left_key_column)
        .ok_or(RelQueryError::ColumnOutOfBounds)?;
    let right_keys = program
        .right_columns
        .get(program.right_key_column)
        .ok_or(RelQueryError::ColumnOutOfBounds)?;
    let decision = right_scan_join_access_decision(
        RightJoinAccessRequest {
            left_rows: left_keys.len(),
            right_relation: program.right_relation,
            right_layout: program.right_layout,
            right_column: program.right_key_column,
            equivalence: program.equivalence,
            allow_ephemeral: true,
        },
        store,
        context,
        registry,
    )?;
    match decision.family {
        JoinAccessFamily::PersistedI64 => {
            let index = store
                .i64_index(I64IndexBinding {
                    relation: program.right_relation,
                    layout: program.right_layout,
                    key_column: program.right_key_column,
                    equivalence: program.equivalence,
                })
                .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
            stats.persisted_index_hits = stats.persisted_index_hits.saturating_add(1);
            Ok(Some(JoinBatchIndex::Persisted(index)))
        }
        JoinAccessFamily::EphemeralI64 => {
            let mut index = BTreeMap::<i64, Vec<usize>>::new();
            for position in program.right.scan_positions() {
                index
                    .entry(right_keys[position])
                    .or_default()
                    .push(position);
            }
            stats.ephemeral_index_builds = stats.ephemeral_index_builds.saturating_add(1);
            stats.scanned_rows = stats.scanned_rows.saturating_add(right_keys.len());
            stats.values_read = stats.values_read.saturating_add(right_keys.len());
            if SemanticAccessCostModel::choose_ephemeral_join(
                left_keys.len(),
                right_keys.len(),
                index.len(),
                1,
            ) == SemanticAccessPath::FullScan
            {
                return Ok(Some(JoinBatchIndex::FullScan));
            }
            Ok(Some(JoinBatchIndex::Ephemeral(index)))
        }
        JoinAccessFamily::FullScan
        | JoinAccessFamily::PersistedSemantic
        | JoinAccessFamily::EphemeralSemantic => Ok(None),
    }
}

fn try_execute_indexed_join_batch_chain(
    plan: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<(Vec<kernel_query::Row>, ExecutionStats)>, PhysicalExecutionError> {
    let Some(program) = build_indexed_join_batch_program(plan, store, context, registry)? else {
        return Ok(None);
    };
    if program.downstream_ops == 0 {
        return Ok(None);
    }
    let left_keys = program
        .left_columns
        .get(program.left_key_column)
        .ok_or(RelQueryError::ColumnOutOfBounds)?;
    let right_keys = program
        .right_columns
        .get(program.right_key_column)
        .ok_or(RelQueryError::ColumnOutOfBounds)?;
    let mut stats = ExecutionStats::default();
    let Some(index) = select_join_batch_index(&program, store, context, registry, &mut stats)?
    else {
        return Ok(None);
    };

    let mut out = Vec::new();
    for left_position in program.left.scan_positions() {
        stats.scanned_rows = stats.scanned_rows.saturating_add(1);
        stats.values_read = stats.values_read.saturating_add(1);
        let key = left_keys[left_position];
        match &index {
            JoinBatchIndex::Persisted(index) => {
                if let Some(right_row_ids) = index.probe(key) {
                    for right_row_id in right_row_ids {
                        let right_position = program
                            .right
                            .position(*right_row_id)
                            .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
                        execute_join_batch_candidate(
                            &program,
                            left_position,
                            right_position,
                            &mut out,
                            &mut stats,
                        )?;
                    }
                }
            }
            JoinBatchIndex::Ephemeral(ephemeral) => {
                if let Some(right_positions) = ephemeral.get(&key) {
                    for &right_position in right_positions {
                        execute_join_batch_candidate(
                            &program,
                            left_position,
                            right_position,
                            &mut out,
                            &mut stats,
                        )?;
                    }
                }
            }
            JoinBatchIndex::FullScan => {
                for right_position in program.right.scan_positions() {
                    stats.values_read = stats.values_read.saturating_add(1);
                    if right_keys[right_position] == key {
                        execute_join_batch_candidate(
                            &program,
                            left_position,
                            right_position,
                            &mut out,
                            &mut stats,
                        )?;
                    }
                }
            }
        }
    }
    stats.typed_batch_chain_hits = stats.typed_batch_chain_hits.saturating_add(1);
    if program.projected {
        stats.fused_join_project_hits = stats.fused_join_project_hits.saturating_add(1);
    }
    Ok(Some((out, stats)))
}

fn execute_join_batch_candidate(
    program: &IndexedJoinBatchProgram<'_>,
    left_position: usize,
    right_position: usize,
    out: &mut Vec<kernel_query::Row>,
    stats: &mut ExecutionStats,
) -> Result<(), PhysicalExecutionError> {
    for predicate in &program.predicates {
        stats.values_read = stats.values_read.saturating_add(1);
        let candidate =
            join_batch_i64_value(program, predicate.column, left_position, right_position)?;
        if candidate != predicate.expected {
            return Ok(());
        }
    }
    let mut row = Vec::with_capacity(program.columns.len());
    for &column in &program.columns {
        let value = join_batch_i64_value(program, column, left_position, right_position)?;
        stats.values_read = stats.values_read.saturating_add(1);
        row.push(Value::I64(value));
    }
    out.push(row);
    Ok(())
}

fn join_batch_i64_value(
    program: &IndexedJoinBatchProgram<'_>,
    column: JoinBatchColumn,
    left_position: usize,
    right_position: usize,
) -> Result<i64, PhysicalExecutionError> {
    let (columns, position) = if column.side == 0 {
        (&program.left_columns, left_position)
    } else {
        (&program.right_columns, right_position)
    };
    columns
        .get(column.column)
        .and_then(|values| values.get(position))
        .copied()
        .ok_or(RelQueryError::ColumnOutOfBounds.into())
}

fn build_indexed_join_batch_program<'a>(
    plan: &Plan,
    store: &'a PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<IndexedJoinBatchProgram<'a>>, PhysicalExecutionError> {
    match plan {
        Plan::Project { input, columns } => {
            let Some(mut program) =
                build_indexed_join_batch_program(input, store, context, registry)?
            else {
                return Ok(None);
            };
            let mut projected = Vec::with_capacity(columns.len());
            for &column in columns {
                projected.push(
                    *program
                        .columns
                        .get(column)
                        .ok_or(RelQueryError::ColumnOutOfBounds)?,
                );
            }
            program.columns = projected;
            program.downstream_ops = program.downstream_ops.saturating_add(1);
            program.projected = true;
            Ok(Some(program))
        }
        Plan::FilterEqConst {
            input,
            column,
            value,
            equivalence,
        } => {
            let Some(mut program) =
                build_indexed_join_batch_program(input, store, context, registry)?
            else {
                return Ok(None);
            };
            if *equivalence != program.equivalence {
                let Some(resolved) =
                    registry.resolve_primitive_equivalence(context, *equivalence)?
                else {
                    return Ok(None);
                };
                if !matches!(
                    resolved.bind_right(value),
                    Ok(kernel_semantics::BoundPrimitivePredicate::I64(_))
                ) {
                    return Ok(None);
                }
            }
            let expected = match value {
                Value::I64(value) => *value,
                _ => return Ok(None),
            };
            let column = *program
                .columns
                .get(*column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            program
                .predicates
                .push(JoinBatchPredicate { column, expected });
            program.downstream_ops = program.downstream_ops.saturating_add(1);
            Ok(Some(program))
        }
        Plan::PromoteToBag(input) => {
            let Some(mut program) =
                build_indexed_join_batch_program(input, store, context, registry)?
            else {
                return Ok(None);
            };
            program.downstream_ops = program.downstream_ops.saturating_add(1);
            Ok(Some(program))
        }
        Plan::JoinEq {
            left,
            right,
            left_column,
            right_column,
            equivalence,
            algorithm: JoinAlgorithm::IndexedPrimitiveIfAvailable,
        } => build_indexed_join_batch_base(
            left,
            right,
            *left_column,
            *right_column,
            *equivalence,
            store,
            context,
            registry,
        ),
        Plan::Scan { .. }
        | Plan::FilterEqColumns { .. }
        | Plan::JoinEq { .. }
        | Plan::Difference { .. }
        | Plan::AntiJoin { .. }
        | Plan::Distinct { .. }
        | Plan::Group { .. }
        | Plan::TopKWithTies { .. } => Ok(None),
    }
}

#[allow(clippy::too_many_arguments)]
fn build_indexed_join_batch_base<'a>(
    left: &Plan,
    right: &Plan,
    left_column: usize,
    right_column: usize,
    equivalence: SemanticId,
    store: &'a PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<IndexedJoinBatchProgram<'a>>, PhysicalExecutionError> {
    let Some((left_relation, left_layout)) = direct_scan_relation(left) else {
        return Ok(None);
    };
    let Some((right_relation, right_layout)) = direct_scan_relation(right) else {
        return Ok(None);
    };
    let Some(resolved) = registry.resolve_primitive_equivalence(context, equivalence)? else {
        return Ok(None);
    };
    if !matches!(
        resolved.bind_right(&Value::I64(0)),
        Ok(kernel_semantics::BoundPrimitivePredicate::I64(_))
    ) {
        return Ok(None);
    }
    let left_installed = store.installed(left_relation, left_layout)?;
    let right_installed = store.installed(right_relation, right_layout)?;
    validate_indexable_i64_relation(context, left_relation, &left_installed.data)?;
    validate_indexable_i64_relation(context, right_relation, &right_installed.data)?;
    let Some(left_columns) = native_all_i64_columns(&left_installed.data) else {
        return Ok(None);
    };
    let Some(right_columns) = native_all_i64_columns(&right_installed.data) else {
        return Ok(None);
    };
    if left_column >= left_columns.len() || right_column >= right_columns.len() {
        return Err(RelQueryError::ColumnOutOfBounds.into());
    }
    let columns = (0..left_columns.len())
        .map(|column| JoinBatchColumn { side: 0, column })
        .chain((0..right_columns.len()).map(|column| JoinBatchColumn { side: 1, column }))
        .collect();
    Ok(Some(IndexedJoinBatchProgram {
        left: left_installed,
        right: right_installed,
        left_columns,
        right_columns,
        left_key_column: left_column,
        right_key_column: right_column,
        equivalence,
        right_relation,
        right_layout,
        columns,
        predicates: Vec::new(),
        downstream_ops: 0,
        projected: false,
    }))
}

#[derive(Debug)]
struct TypedBatchProgram<'a> {
    installed: &'a InstalledRelation,
    columns: Vec<usize>,
    predicates: Vec<TypedBatchPredicate>,
}

#[derive(Debug)]
struct TypedBatchPredicate {
    physical_column: usize,
    kind: TypedBatchPredicateKind,
}

#[derive(Debug)]
enum TypedBatchPredicateKind {
    Primitive(kernel_semantics::BoundPrimitivePredicate),
    Algebraic {
        compiled: kernel_semantics::CompiledEquivalence,
        expected: kernel_semantics::CanonicalEqKey,
    },
}

fn merge_execution_stats(target: &mut ExecutionStats, source: ExecutionStats) {
    target.scanned_rows = target.scanned_rows.saturating_add(source.scanned_rows);
    target.values_read = target.values_read.saturating_add(source.values_read);
    target.persisted_index_hits = target
        .persisted_index_hits
        .saturating_add(source.persisted_index_hits);
    target.persisted_index_cost_rejections = target
        .persisted_index_cost_rejections
        .saturating_add(source.persisted_index_cost_rejections);
    target.ephemeral_index_builds = target
        .ephemeral_index_builds
        .saturating_add(source.ephemeral_index_builds);
    target.fused_join_project_hits = target
        .fused_join_project_hits
        .saturating_add(source.fused_join_project_hits);
    target.typed_batch_chain_hits = target
        .typed_batch_chain_hits
        .saturating_add(source.typed_batch_chain_hits);
    target.typed_stateful_batch_hits = target
        .typed_stateful_batch_hits
        .saturating_add(source.typed_stateful_batch_hits);
    target.typed_stateful_producer_hits = target
        .typed_stateful_producer_hits
        .saturating_add(source.typed_stateful_producer_hits);
    target.multiway_join_reorders = target
        .multiway_join_reorders
        .saturating_add(source.multiway_join_reorders);
    target.multiway_join_order_preserving_enumerations = target
        .multiway_join_order_preserving_enumerations
        .saturating_add(source.multiway_join_order_preserving_enumerations);
    target.multiway_join_semantic_quotient_constraints = target
        .multiway_join_semantic_quotient_constraints
        .saturating_add(source.multiway_join_semantic_quotient_constraints);
    target.multiway_join_semantic_quotient_pruned_rows = target
        .multiway_join_semantic_quotient_pruned_rows
        .saturating_add(source.multiway_join_semantic_quotient_pruned_rows);
    target.multiway_join_prepared_quotient_hits = target
        .multiway_join_prepared_quotient_hits
        .saturating_add(source.multiway_join_prepared_quotient_hits);
    target.multiway_join_maintained_quotient_key_hits = target
        .multiway_join_maintained_quotient_key_hits
        .saturating_add(source.multiway_join_maintained_quotient_key_hits);
    target.multiway_join_maintained_quotient_support_hits = target
        .multiway_join_maintained_quotient_support_hits
        .saturating_add(source.multiway_join_maintained_quotient_support_hits);
    target.multiway_join_cyclic_budget_rejections = target
        .multiway_join_cyclic_budget_rejections
        .saturating_add(source.multiway_join_cyclic_budget_rejections);
    target.multiway_join_cyclic_prefix_index_lookups = target
        .multiway_join_cyclic_prefix_index_lookups
        .saturating_add(source.multiway_join_cyclic_prefix_index_lookups);
    target.multiway_join_semantic_quotient_candidate_visits = target
        .multiway_join_semantic_quotient_candidate_visits
        .saturating_add(source.multiway_join_semantic_quotient_candidate_visits);
}

struct TypedBatchSelection<'a> {
    program: TypedBatchProgram<'a>,
    positions: Vec<usize>,
    stats: ExecutionStats,
}

fn execute_typed_batch_selection<'a>(
    plan: &Plan,
    store: &'a PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<TypedBatchSelection<'a>>, PhysicalExecutionError> {
    let Some(program) = build_typed_batch_program(plan, store, context, registry)? else {
        return Ok(None);
    };
    let NativeRelation::TypedColumnar { columns, .. } = &program.installed.data else {
        return Ok(None);
    };
    let mut stats = ExecutionStats::default();
    let positions = if program.predicates.is_empty() {
        if program.installed.scan_order_is_physical {
            (0..native_row_count(&program.installed.data)).collect::<Vec<_>>()
        } else {
            program.installed.scan_positions().collect::<Vec<_>>()
        }
    } else {
        let source: Box<dyn Iterator<Item = usize> + '_> =
            if program.installed.scan_order_is_physical {
                Box::new(0..native_row_count(&program.installed.data))
            } else {
                program.installed.scan_positions()
            };
        let mut selected = Vec::new();
        for position in source {
            let mut matched = true;
            for predicate in &program.predicates {
                stats.values_read = stats.values_read.saturating_add(1);
                if !typed_batch_predicate_matches(
                    columns
                        .get(predicate.physical_column)
                        .ok_or(RelQueryError::ColumnOutOfBounds)?,
                    position,
                    predicate,
                )? {
                    matched = false;
                    break;
                }
            }
            if matched {
                selected.push(position);
            }
        }
        selected
    };
    stats.scanned_rows = native_row_count(&program.installed.data);
    stats.typed_batch_chain_hits = stats.typed_batch_chain_hits.saturating_add(1);
    Ok(Some(TypedBatchSelection {
        program,
        positions,
        stats,
    }))
}

fn materialize_typed_batch_row(
    program: &TypedBatchProgram<'_>,
    columns: &[NativeColumn],
    position: usize,
    stats: &mut ExecutionStats,
) -> Result<kernel_query::Row, PhysicalExecutionError> {
    let mut row = Vec::with_capacity(program.columns.len());
    for &physical_column in &program.columns {
        row.push(
            columns
                .get(physical_column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?
                .value_at(position),
        );
    }
    stats.values_read = stats.values_read.saturating_add(program.columns.len());
    Ok(row)
}

fn equivalence_is_i64_exact(
    equivalence: SemanticId,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<bool, PhysicalExecutionError> {
    let Some(resolved) = registry.resolve_primitive_equivalence(context, equivalence)? else {
        return Ok(false);
    };
    Ok(matches!(
        resolved.bind_right(&Value::I64(0)),
        Ok(kernel_semantics::BoundPrimitivePredicate::I64(0))
    ))
}

#[derive(Debug)]
struct OwnedTypedBatch {
    columns: Vec<NativeColumn>,
    positions: Vec<usize>,
    stats: ExecutionStats,
}

impl OwnedTypedBatch {
    fn dense(
        columns: Vec<NativeColumn>,
        stats: ExecutionStats,
    ) -> Result<Self, PhysicalExecutionError> {
        let len = columns.first().map_or(0, NativeColumn::len);
        if columns.iter().any(|column| column.len() != len) {
            return Err(PhysicalExecutionError::ColumnShapeMismatch);
        }
        Ok(Self {
            columns,
            positions: (0..len).collect(),
            stats,
        })
    }

    fn project(&mut self, projection: &[usize]) -> Result<(), PhysicalExecutionError> {
        let mut columns = Vec::with_capacity(projection.len());
        for &column in projection {
            columns.push(
                self.columns
                    .get(column)
                    .cloned()
                    .ok_or(RelQueryError::ColumnOutOfBounds)?,
            );
        }
        self.columns = columns;
        Ok(())
    }

    fn filter(
        &mut self,
        column: usize,
        value: &Value,
        equivalence: SemanticId,
        env: &StatefulBatchEnv<'_>,
    ) -> Result<(), PhysicalExecutionError> {
        let physical = self
            .columns
            .get(column)
            .ok_or(RelQueryError::ColumnOutOfBounds)?;
        let Some(resolved) = env
            .registry
            .resolve_primitive_equivalence(env.context, equivalence)?
        else {
            return Err(PhysicalExecutionError::UnsupportedPhysicalPlan);
        };
        let bound = resolved.bind_right(value)?;
        if !typed_column_bound_compatible(physical, &bound) {
            return Err(PhysicalExecutionError::PhysicalTypeMismatch);
        }
        let mut selected = Vec::with_capacity(self.positions.len());
        for &position in &self.positions {
            self.stats.values_read = self.stats.values_read.saturating_add(1);
            if typed_column_matches_bound(physical, position, &bound)? {
                selected.push(position);
            }
        }
        self.positions = selected;
        Ok(())
    }

    fn materialize(mut self) -> (Vec<kernel_query::Row>, ExecutionStats) {
        let mut rows = Vec::with_capacity(self.positions.len());
        for position in self.positions {
            let mut row = Vec::with_capacity(self.columns.len());
            for column in &self.columns {
                row.push(column.value_at(position));
            }
            self.stats.values_read = self.stats.values_read.saturating_add(self.columns.len());
            rows.push(row);
        }
        self.stats.typed_stateful_producer_hits =
            self.stats.typed_stateful_producer_hits.saturating_add(1);
        (rows, self.stats)
    }
}

fn try_execute_typed_stateful_producer_chain(
    plan: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<(Vec<kernel_query::Row>, ExecutionStats)>, PhysicalExecutionError> {
    if !matches!(
        plan,
        Plan::Project { .. } | Plan::FilterEqConst { .. } | Plan::PromoteToBag(_)
    ) {
        return Ok(None);
    }
    let env = StatefulBatchEnv { context, registry };
    let Some(batch) = try_produce_typed_stateful_batch(plan, store, &env)? else {
        return Ok(None);
    };
    Ok(Some(batch.materialize()))
}

fn try_produce_typed_stateful_batch(
    plan: &Plan,
    store: &PhysicalStore,
    env: &StatefulBatchEnv<'_>,
) -> Result<Option<OwnedTypedBatch>, PhysicalExecutionError> {
    match plan {
        Plan::Project { input, columns } => {
            let Some(mut batch) = try_produce_typed_stateful_batch(input, store, env)? else {
                return Ok(None);
            };
            batch.project(columns)?;
            Ok(Some(batch))
        }
        Plan::FilterEqConst {
            input,
            column,
            value,
            equivalence,
        } => {
            let Some(mut batch) = try_produce_typed_stateful_batch(input, store, env)? else {
                return Ok(None);
            };
            batch.filter(*column, value, *equivalence, env)?;
            Ok(Some(batch))
        }
        Plan::PromoteToBag(input) => try_produce_typed_stateful_batch(input, store, env),
        Plan::Group {
            input,
            group_columns,
            group_equivalences,
            aggregate,
            algorithm: GroupAlgorithm::LinearReplay,
        } => produce_typed_group(
            input,
            GroupBatchSpec {
                group_columns,
                group_equivalences,
                aggregate,
            },
            store,
            env,
        ),
        Plan::TopKWithTies {
            input,
            column,
            ordering,
            direction,
            k,
            algorithm: TopKAlgorithm::FullSort,
        } => produce_typed_top_k(
            input,
            TopKBatchSpec {
                column: *column,
                ordering: *ordering,
                direction: *direction,
                k: *k,
            },
            store,
            env,
        ),
        Plan::Scan { .. }
        | Plan::FilterEqColumns { .. }
        | Plan::Distinct { .. }
        | Plan::JoinEq { .. }
        | Plan::Difference { .. }
        | Plan::AntiJoin { .. } => Ok(None),
    }
}

fn produce_typed_group(
    input: &Plan,
    spec: GroupBatchSpec<'_>,
    store: &PhysicalStore,
    env: &StatefulBatchEnv<'_>,
) -> Result<Option<OwnedTypedBatch>, PhysicalExecutionError> {
    if let Some(selection) = execute_typed_batch_selection(input, store, env.context, env.registry)?
    {
        return produce_group_from_raw_selection(selection, spec, env).map(Some);
    }
    let Some(batch) = try_produce_typed_stateful_batch(input, store, env)? else {
        return Ok(None);
    };
    produce_group_from_owned_batch(batch, spec, env).map(Some)
}

fn produce_group_from_raw_selection(
    selection: TypedBatchSelection<'_>,
    spec: GroupBatchSpec<'_>,
    env: &StatefulBatchEnv<'_>,
) -> Result<OwnedTypedBatch, PhysicalExecutionError> {
    validate_group_batch_spec(spec)?;
    let TypedBatchSelection {
        program,
        positions,
        mut stats,
    } = selection;
    let NativeRelation::TypedColumnar { columns, .. } = &program.installed.data else {
        return Err(PhysicalExecutionError::UnsupportedPhysicalPlan);
    };
    let physical_group_columns = resolve_group_columns(&program.columns, spec.group_columns)?;
    let output_columns = produce_group_columns(
        columns,
        &program.columns,
        &positions,
        &physical_group_columns,
        spec,
        env,
        &mut stats,
    )?
    .ok_or(PhysicalExecutionError::UnsupportedPhysicalPlan)?;
    OwnedTypedBatch::dense(output_columns, stats)
}

fn produce_group_from_owned_batch(
    batch: OwnedTypedBatch,
    spec: GroupBatchSpec<'_>,
    env: &StatefulBatchEnv<'_>,
) -> Result<OwnedTypedBatch, PhysicalExecutionError> {
    validate_group_batch_spec(spec)?;
    let OwnedTypedBatch {
        columns,
        positions,
        mut stats,
    } = batch;
    let logical_columns = (0..columns.len()).collect::<Vec<_>>();
    let group_columns = resolve_group_columns(&logical_columns, spec.group_columns)?;
    let output_columns = produce_group_columns(
        &columns,
        &logical_columns,
        &positions,
        &group_columns,
        spec,
        env,
        &mut stats,
    )?
    .ok_or(PhysicalExecutionError::UnsupportedPhysicalPlan)?;
    OwnedTypedBatch::dense(output_columns, stats)
}

fn validate_group_batch_spec(spec: GroupBatchSpec<'_>) -> Result<(), PhysicalExecutionError> {
    if spec.group_columns.len() != spec.group_equivalences.len() {
        return Err(RelQueryError::TypeMismatch.into());
    }
    Ok(())
}

fn resolve_group_columns(
    logical_columns: &[usize],
    group_columns: &[usize],
) -> Result<Vec<usize>, PhysicalExecutionError> {
    group_columns
        .iter()
        .map(|column| {
            logical_columns
                .get(*column)
                .copied()
                .ok_or_else(|| RelQueryError::ColumnOutOfBounds.into())
        })
        .collect()
}

fn produce_group_columns(
    columns: &[NativeColumn],
    logical_columns: &[usize],
    positions: &[usize],
    physical_group_columns: &[usize],
    spec: GroupBatchSpec<'_>,
    env: &StatefulBatchEnv<'_>,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<NativeColumn>>, PhysicalExecutionError> {
    if let Some(output_columns) = try_produce_exact_i64_group_columns(
        logical_columns,
        columns,
        positions,
        physical_group_columns,
        spec,
        env,
        stats,
    )? {
        return Ok(Some(output_columns));
    }
    produce_primitive_group_columns(
        logical_columns,
        columns,
        positions,
        physical_group_columns,
        spec,
        env,
        stats,
    )
}

fn try_produce_exact_i64_group_columns(
    logical_columns: &[usize],
    columns: &[NativeColumn],
    positions: &[usize],
    physical_group_columns: &[usize],
    spec: GroupBatchSpec<'_>,
    env: &StatefulBatchEnv<'_>,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<NativeColumn>>, PhysicalExecutionError> {
    if spec.group_columns.len() != 1
        || !equivalence_is_i64_exact(spec.group_equivalences[0], env.context, env.registry)?
    {
        return Ok(None);
    }
    let Some(NativeColumn::I64(keys)) = columns.get(physical_group_columns[0]) else {
        return Ok(None);
    };
    let mut lookup = BTreeMap::<i64, usize>::new();
    let mut output_keys = Vec::<i64>::new();
    match spec.aggregate {
        AggregateSpec::Count { .. } => {
            let mut counts = Vec::<kernel_aggregate::ExactCount>::new();
            for &position in positions {
                let key = keys[position];
                let index = *lookup.entry(key).or_insert_with(|| {
                    let index = output_keys.len();
                    output_keys.push(key);
                    counts.push(kernel_aggregate::ExactCount::default());
                    index
                });
                counts[index].add_one();
            }
            stats.values_read = stats.values_read.saturating_add(positions.len());
            let output_counts = counts
                .into_iter()
                .map(|count| count.finish_i64().map_err(RelQueryError::from))
                .collect::<Result<Vec<_>, _>>()?;
            Ok(Some(vec![
                NativeColumn::I64(output_keys),
                NativeColumn::I64(output_counts),
            ]))
        }
        AggregateSpec::ExactF64Sum { value_column, .. } => {
            let physical_value_column = *logical_columns
                .get(*value_column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            let Some(NativeColumn::F64Bits(values)) = columns.get(physical_value_column) else {
                return Ok(None);
            };
            let mut sums = Vec::<kernel_aggregate::ExactF64Sum>::new();
            for &position in positions {
                let key = keys[position];
                let index = *lookup.entry(key).or_insert_with(|| {
                    let index = output_keys.len();
                    output_keys.push(key);
                    sums.push(kernel_aggregate::ExactF64Sum::default());
                    index
                });
                sums[index]
                    .add(f64::from_bits(values[position]))
                    .map_err(RelQueryError::from)?;
            }
            stats.values_read = stats
                .values_read
                .saturating_add(positions.len().saturating_mul(2));
            Ok(Some(vec![
                NativeColumn::I64(output_keys),
                NativeColumn::F64Bits(sums.into_iter().map(|sum| sum.finish().to_bits()).collect()),
            ]))
        }
    }
}

fn produce_primitive_group_columns(
    logical_columns: &[usize],
    columns: &[NativeColumn],
    positions: &[usize],
    physical_group_columns: &[usize],
    spec: GroupBatchSpec<'_>,
    env: &StatefulBatchEnv<'_>,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<NativeColumn>>, PhysicalExecutionError> {
    let mut encoders = Vec::with_capacity(spec.group_equivalences.len());
    for &equivalence in spec.group_equivalences {
        let Some(encoder) = env
            .registry
            .resolve_primitive_equivalence(env.context, equivalence)?
        else {
            return Ok(None);
        };
        encoders.push(encoder);
    }
    let Some(accumulation) = accumulate_primitive_groups(
        logical_columns,
        columns,
        positions,
        physical_group_columns,
        spec,
        &encoders,
        stats,
    )?
    else {
        return Ok(None);
    };
    finish_primitive_group_columns(
        columns,
        physical_group_columns,
        spec.aggregate,
        &accumulation.representatives,
        accumulation.aggregates,
    )
    .map(Some)
}

struct PrimitiveGroupAccumulation {
    representatives: Vec<Vec<Value>>,
    aggregates: Vec<TypedGroupState>,
}

fn accumulate_primitive_groups(
    logical_columns: &[usize],
    columns: &[NativeColumn],
    positions: &[usize],
    physical_group_columns: &[usize],
    spec: GroupBatchSpec<'_>,
    encoders: &[kernel_semantics::ResolvedPrimitiveEquivalence],
    stats: &mut ExecutionStats,
) -> Result<Option<PrimitiveGroupAccumulation>, PhysicalExecutionError> {
    let mut lookup = BTreeMap::<Vec<kernel_semantics::CanonicalEqKey>, usize>::new();
    let mut representatives = Vec::<Vec<Value>>::new();
    let mut aggregates = Vec::<TypedGroupState>::new();
    if positions.is_empty() && spec.group_columns.is_empty() {
        representatives.push(Vec::new());
        aggregates.push(new_typed_group_state(spec.aggregate));
    }
    for &position in positions {
        let mut canonical = Vec::with_capacity(physical_group_columns.len());
        let mut representative = Vec::with_capacity(physical_group_columns.len());
        for (&physical_column, encoder) in physical_group_columns.iter().zip(encoders) {
            let value = columns
                .get(physical_column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?
                .value_at(position);
            canonical.push(encoder.canonical_key(&value)?);
            representative.push(value);
        }
        stats.values_read = stats
            .values_read
            .saturating_add(physical_group_columns.len());
        let index = if let Some(index) = lookup.get(&canonical).copied() {
            index
        } else {
            let index = representatives.len();
            lookup.insert(canonical, index);
            representatives.push(representative);
            aggregates.push(new_typed_group_state(spec.aggregate));
            index
        };
        if !update_typed_group_state(
            &mut aggregates[index],
            spec.aggregate,
            logical_columns,
            columns,
            position,
            stats,
        )? {
            return Ok(None);
        }
    }
    Ok(Some(PrimitiveGroupAccumulation {
        representatives,
        aggregates,
    }))
}

fn update_typed_group_state(
    aggregate_state: &mut TypedGroupState,
    aggregate: &AggregateSpec,
    logical_columns: &[usize],
    columns: &[NativeColumn],
    position: usize,
    execution_stats: &mut ExecutionStats,
) -> Result<bool, PhysicalExecutionError> {
    match (aggregate_state, aggregate) {
        (TypedGroupState::Count(count), AggregateSpec::Count { .. }) => count.add_one(),
        (TypedGroupState::ExactF64Sum(sum), AggregateSpec::ExactF64Sum { value_column, .. }) => {
            let physical_value_column = *logical_columns
                .get(*value_column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            let Some(NativeColumn::F64Bits(values)) = columns.get(physical_value_column) else {
                return Ok(false);
            };
            sum.add(f64::from_bits(values[position]))
                .map_err(RelQueryError::from)?;
            execution_stats.values_read = execution_stats.values_read.saturating_add(1);
        }
        _ => return Err(RelQueryError::TypeMismatch.into()),
    }
    Ok(true)
}

fn finish_primitive_group_columns(
    columns: &[NativeColumn],
    physical_group_columns: &[usize],
    aggregate: &AggregateSpec,
    representatives: &[Vec<Value>],
    aggregates: Vec<TypedGroupState>,
) -> Result<Vec<NativeColumn>, PhysicalExecutionError> {
    let mut output_columns = Vec::with_capacity(physical_group_columns.len() + 1);
    for (key_index, &physical_column) in physical_group_columns.iter().enumerate() {
        let values = representatives
            .iter()
            .map(|key| key[key_index].clone())
            .collect::<Vec<_>>();
        output_columns.push(NativeColumn::from_values_like(
            columns
                .get(physical_column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?,
            values,
        )?);
    }
    match aggregate {
        AggregateSpec::Count { .. } => output_columns.push(NativeColumn::I64(
            aggregates
                .into_iter()
                .map(|state| match state {
                    TypedGroupState::Count(count) => {
                        count.finish_i64().map_err(RelQueryError::from)
                    }
                    TypedGroupState::ExactF64Sum(_) => Err(RelQueryError::TypeMismatch),
                })
                .collect::<Result<Vec<_>, _>>()?,
        )),
        AggregateSpec::ExactF64Sum { .. } => output_columns.push(NativeColumn::F64Bits(
            aggregates
                .into_iter()
                .map(|state| match state {
                    TypedGroupState::ExactF64Sum(sum) => Ok(sum.finish().to_bits()),
                    TypedGroupState::Count(_) => Err(RelQueryError::TypeMismatch),
                })
                .collect::<Result<Vec<_>, RelQueryError>>()?,
        )),
    }
    Ok(output_columns)
}

fn produce_typed_top_k(
    input: &Plan,
    spec: TopKBatchSpec,
    store: &PhysicalStore,
    env: &StatefulBatchEnv<'_>,
) -> Result<Option<OwnedTypedBatch>, PhysicalExecutionError> {
    if let Some(selection) = execute_typed_batch_selection(input, store, env.context, env.registry)?
    {
        return produce_top_k_from_raw_selection(selection, spec, env).map(Some);
    }
    let Some(batch) = try_produce_typed_stateful_batch(input, store, env)? else {
        return Ok(None);
    };
    produce_top_k_from_owned_batch(batch, spec, env).map(Some)
}

fn produce_top_k_from_raw_selection(
    selection: TypedBatchSelection<'_>,
    spec: TopKBatchSpec,
    env: &StatefulBatchEnv<'_>,
) -> Result<OwnedTypedBatch, PhysicalExecutionError> {
    let TypedBatchSelection {
        program,
        mut positions,
        mut stats,
    } = selection;
    let NativeRelation::TypedColumnar { columns, .. } = &program.installed.data else {
        return Err(PhysicalExecutionError::UnsupportedPhysicalPlan);
    };
    retain_top_k_positions(
        columns,
        &program.columns,
        &mut positions,
        spec,
        env,
        &mut stats,
    )?;
    let compact = select_logical_columns(columns, &program.columns, &positions)?;
    OwnedTypedBatch::dense(compact, stats)
}

fn produce_top_k_from_owned_batch(
    batch: OwnedTypedBatch,
    spec: TopKBatchSpec,
    env: &StatefulBatchEnv<'_>,
) -> Result<OwnedTypedBatch, PhysicalExecutionError> {
    let OwnedTypedBatch {
        columns,
        mut positions,
        mut stats,
    } = batch;
    let logical_columns = (0..columns.len()).collect::<Vec<_>>();
    retain_top_k_positions(
        &columns,
        &logical_columns,
        &mut positions,
        spec,
        env,
        &mut stats,
    )?;
    let compact = select_logical_columns(&columns, &logical_columns, &positions)?;
    OwnedTypedBatch::dense(compact, stats)
}

fn retain_top_k_positions(
    columns: &[NativeColumn],
    logical_columns: &[usize],
    positions: &mut Vec<usize>,
    spec: TopKBatchSpec,
    env: &StatefulBatchEnv<'_>,
    stats: &mut ExecutionStats,
) -> Result<(), PhysicalExecutionError> {
    if spec.k == 0 || positions.is_empty() {
        positions.clear();
        return Ok(());
    }
    let physical_column = *logical_columns
        .get(spec.column)
        .ok_or(RelQueryError::ColumnOutOfBounds)?;
    let order_column = columns
        .get(physical_column)
        .ok_or(RelQueryError::ColumnOutOfBounds)?;
    if matches!(
        env.registry.ordering_domain(env.context, spec.ordering)?,
        kernel_semantics::OrderingDomain::I64
    ) && let NativeColumn::I64(values) = order_column
    {
        select_top_k_i64_positions(positions, values, spec.direction, spec.k, stats);
        return Ok(());
    }
    sort_typed_top_k_positions(positions, order_column, spec, env, stats)?;
    retain_semantic_top_k_ties(positions, order_column, spec, env, stats)
}

fn retain_semantic_top_k_ties(
    positions: &mut Vec<usize>,
    order_column: &NativeColumn,
    spec: TopKBatchSpec,
    env: &StatefulBatchEnv<'_>,
    stats: &mut ExecutionStats,
) -> Result<(), PhysicalExecutionError> {
    if spec.k >= positions.len() {
        return Ok(());
    }
    let threshold = order_column.value_at(positions[spec.k - 1]);
    stats.values_read = stats.values_read.saturating_add(1);
    let mut keep = spec.k;
    while keep < positions.len() {
        let candidate = order_column.value_at(positions[keep]);
        stats.values_read = stats.values_read.saturating_add(1);
        if env
            .registry
            .compare(env.context, spec.ordering, &candidate, &threshold)?
            != std::cmp::Ordering::Equal
        {
            break;
        }
        keep += 1;
    }
    positions.truncate(keep);
    Ok(())
}

fn select_logical_columns(
    columns: &[NativeColumn],
    logical_columns: &[usize],
    positions: &[usize],
) -> Result<Vec<NativeColumn>, PhysicalExecutionError> {
    logical_columns
        .iter()
        .map(|&column| {
            columns
                .get(column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?
                .select_positions(positions)
        })
        .collect()
}

fn try_execute_typed_stateful_batch(
    plan: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<(Vec<kernel_query::Row>, ExecutionStats)>, PhysicalExecutionError> {
    let env = StatefulBatchEnv { context, registry };
    match plan {
        Plan::Distinct {
            input,
            column_equivalences,
        } => try_execute_typed_distinct(input, column_equivalences, store, &env),
        Plan::Group {
            input,
            group_columns,
            group_equivalences,
            aggregate,
            algorithm: GroupAlgorithm::LinearReplay,
        } => try_execute_typed_group(
            input,
            GroupBatchSpec {
                group_columns,
                group_equivalences,
                aggregate,
            },
            store,
            &env,
        ),
        Plan::TopKWithTies {
            input,
            column,
            ordering,
            direction,
            k,
            algorithm: TopKAlgorithm::FullSort,
        } => try_execute_typed_top_k(
            input,
            TopKBatchSpec {
                column: *column,
                ordering: *ordering,
                direction: *direction,
                k: *k,
            },
            store,
            &env,
        ),
        Plan::Scan { .. }
        | Plan::FilterEqConst { .. }
        | Plan::FilterEqColumns { .. }
        | Plan::Project { .. }
        | Plan::JoinEq { .. }
        | Plan::Difference { .. }
        | Plan::AntiJoin { .. }
        | Plan::PromoteToBag(_) => Ok(None),
    }
}

struct StatefulBatchEnv<'a> {
    context: &'a kernel_schema::SemanticContext,
    registry: &'a kernel_semantics::SemanticRegistry,
}

#[derive(Clone, Copy)]
struct GroupBatchSpec<'a> {
    group_columns: &'a [usize],
    group_equivalences: &'a [SemanticId],
    aggregate: &'a AggregateSpec,
}

#[derive(Clone, Copy)]
struct TopKBatchSpec {
    column: usize,
    ordering: SemanticId,
    direction: OrderDirection,
    k: usize,
}

fn try_execute_typed_distinct(
    input: &Plan,
    column_equivalences: &[SemanticId],
    store: &PhysicalStore,
    env: &StatefulBatchEnv<'_>,
) -> Result<Option<(Vec<kernel_query::Row>, ExecutionStats)>, PhysicalExecutionError> {
    let Some(mut selection) =
        execute_typed_batch_selection(input, store, env.context, env.registry)?
    else {
        return Ok(None);
    };
    let NativeRelation::TypedColumnar { columns, .. } = &selection.program.installed.data else {
        return Ok(None);
    };
    let mut unique: Vec<kernel_query::Row> = Vec::new();
    if selection.program.columns.len() == 1
        && column_equivalences.len() == 1
        && equivalence_is_i64_exact(column_equivalences[0], env.context, env.registry)?
    {
        let physical_column = selection.program.columns[0];
        if let Some(NativeColumn::I64(values)) = columns.get(physical_column) {
            let mut seen = BTreeSet::new();
            for position in selection.positions {
                selection.stats.values_read = selection.stats.values_read.saturating_add(1);
                let value = values[position];
                if seen.insert(value) {
                    unique.push(vec![Value::I64(value)]);
                }
            }
            selection.stats.typed_stateful_batch_hits =
                selection.stats.typed_stateful_batch_hits.saturating_add(1);
            return Ok(Some((unique, selection.stats)));
        }
    }
    for position in selection.positions {
        let row = materialize_typed_batch_row(
            &selection.program,
            columns,
            position,
            &mut selection.stats,
        )?;
        let mut duplicate = false;
        for existing in &unique {
            if semantic_rows_equal(
                &row,
                existing,
                column_equivalences,
                env.context,
                env.registry,
            )? {
                duplicate = true;
                break;
            }
        }
        if !duplicate {
            unique.push(row);
        }
    }
    selection.stats.typed_stateful_batch_hits =
        selection.stats.typed_stateful_batch_hits.saturating_add(1);
    Ok(Some((unique, selection.stats)))
}

fn try_execute_typed_group(
    input: &Plan,
    spec: GroupBatchSpec<'_>,
    store: &PhysicalStore,
    env: &StatefulBatchEnv<'_>,
) -> Result<Option<(Vec<kernel_query::Row>, ExecutionStats)>, PhysicalExecutionError> {
    let Some(mut selection) =
        execute_typed_batch_selection(input, store, env.context, env.registry)?
    else {
        return Ok(None);
    };
    let NativeRelation::TypedColumnar { columns, .. } = &selection.program.installed.data else {
        return Ok(None);
    };
    let rows = group_typed_batch_selection(
        &selection.program,
        columns,
        &selection.positions,
        spec,
        env,
        &mut selection.stats,
    )?;
    selection.stats.typed_stateful_batch_hits =
        selection.stats.typed_stateful_batch_hits.saturating_add(1);
    Ok(Some((rows, selection.stats)))
}

fn try_execute_typed_top_k(
    input: &Plan,
    spec: TopKBatchSpec,
    store: &PhysicalStore,
    env: &StatefulBatchEnv<'_>,
) -> Result<Option<(Vec<kernel_query::Row>, ExecutionStats)>, PhysicalExecutionError> {
    let Some(mut selection) =
        execute_typed_batch_selection(input, store, env.context, env.registry)?
    else {
        return Ok(None);
    };
    let NativeRelation::TypedColumnar { columns, .. } = &selection.program.installed.data else {
        return Ok(None);
    };
    let rows = top_k_typed_batch_selection(
        &selection.program,
        columns,
        selection.positions,
        spec,
        env,
        &mut selection.stats,
    )?;
    selection.stats.typed_stateful_batch_hits =
        selection.stats.typed_stateful_batch_hits.saturating_add(1);
    Ok(Some((rows, selection.stats)))
}

fn try_group_i64_exact_batch(
    program: &TypedBatchProgram<'_>,
    columns: &[NativeColumn],
    positions: &[usize],
    spec: GroupBatchSpec<'_>,
    env: &StatefulBatchEnv<'_>,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    if spec.group_columns.len() != 1
        || spec.group_equivalences.len() != 1
        || !equivalence_is_i64_exact(spec.group_equivalences[0], env.context, env.registry)?
    {
        return Ok(None);
    }
    let physical_group_column = *program
        .columns
        .get(spec.group_columns[0])
        .ok_or(RelQueryError::ColumnOutOfBounds)?;
    let Some(NativeColumn::I64(keys)) = columns.get(physical_group_column) else {
        return Ok(None);
    };
    let mut lookup = BTreeMap::<i64, usize>::new();
    match spec.aggregate {
        AggregateSpec::Count { .. } => {
            stats.values_read = stats.values_read.saturating_add(positions.len());
            let mut groups: Vec<(i64, kernel_aggregate::ExactCount)> = Vec::new();
            for &position in positions {
                let key = keys[position];
                let index = if let Some(index) = lookup.get(&key).copied() {
                    index
                } else {
                    let index = groups.len();
                    groups.push((key, kernel_aggregate::ExactCount::default()));
                    lookup.insert(key, index);
                    index
                };
                groups[index].1.add_one();
            }
            let rows = groups
                .into_iter()
                .map(|(key, count)| {
                    Ok(vec![
                        Value::I64(key),
                        Value::I64(count.finish_i64().map_err(RelQueryError::from)?),
                    ])
                })
                .collect::<Result<Vec<_>, PhysicalExecutionError>>()?;
            Ok(Some(rows))
        }
        AggregateSpec::ExactF64Sum { value_column, .. } => {
            stats.values_read = stats
                .values_read
                .saturating_add(positions.len().saturating_mul(2));
            let physical_value_column = *program
                .columns
                .get(*value_column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            let Some(NativeColumn::F64Bits(values)) = columns.get(physical_value_column) else {
                return Ok(None);
            };
            let mut groups: Vec<(i64, kernel_aggregate::ExactF64Sum)> = Vec::new();
            for &position in positions {
                let key = keys[position];
                let index = if let Some(index) = lookup.get(&key).copied() {
                    index
                } else {
                    let index = groups.len();
                    groups.push((key, kernel_aggregate::ExactF64Sum::default()));
                    lookup.insert(key, index);
                    index
                };
                groups[index]
                    .1
                    .add(f64::from_bits(values[position]))
                    .map_err(RelQueryError::from)?;
            }
            Ok(Some(
                groups
                    .into_iter()
                    .map(|(key, sum)| vec![Value::I64(key), Value::F64Bits(sum.finish().to_bits())])
                    .collect(),
            ))
        }
    }
}

enum TypedGroupState {
    Count(kernel_aggregate::ExactCount),
    ExactF64Sum(kernel_aggregate::ExactF64Sum),
}

fn new_typed_group_state(aggregate: &AggregateSpec) -> TypedGroupState {
    match aggregate {
        AggregateSpec::Count { .. } => {
            TypedGroupState::Count(kernel_aggregate::ExactCount::default())
        }
        AggregateSpec::ExactF64Sum { .. } => {
            TypedGroupState::ExactF64Sum(kernel_aggregate::ExactF64Sum::default())
        }
    }
}

fn finish_typed_groups(
    groups: Vec<(Vec<Value>, TypedGroupState)>,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    groups
        .into_iter()
        .map(|(mut key, state)| {
            key.push(match state {
                TypedGroupState::Count(count) => {
                    Value::I64(count.finish_i64().map_err(RelQueryError::from)?)
                }
                TypedGroupState::ExactF64Sum(sum) => Value::F64Bits(sum.finish().to_bits()),
            });
            Ok(key)
        })
        .collect()
}

fn group_typed_batch_selection(
    program: &TypedBatchProgram<'_>,
    columns: &[NativeColumn],
    positions: &[usize],
    spec: GroupBatchSpec<'_>,
    env: &StatefulBatchEnv<'_>,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    if spec.group_columns.len() != spec.group_equivalences.len() {
        return Err(RelQueryError::TypeMismatch.into());
    }
    if let Some(rows) = try_group_i64_exact_batch(program, columns, positions, spec, env, stats)? {
        return Ok(rows);
    }
    let physical_group_columns = spec
        .group_columns
        .iter()
        .map(|column| {
            program
                .columns
                .get(*column)
                .copied()
                .ok_or(RelQueryError::ColumnOutOfBounds)
        })
        .collect::<Result<Vec<_>, _>>()?;
    let physical_sum_column = match spec.aggregate {
        AggregateSpec::ExactF64Sum { value_column, .. } => Some(
            *program
                .columns
                .get(*value_column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?,
        ),
        AggregateSpec::Count { .. } => None,
    };

    let mut groups: Vec<(Vec<Value>, TypedGroupState)> = Vec::new();
    if positions.is_empty() && spec.group_columns.is_empty() {
        groups.push((Vec::new(), new_typed_group_state(spec.aggregate)));
    }
    for &position in positions {
        let mut key = Vec::with_capacity(physical_group_columns.len());
        for &physical_column in &physical_group_columns {
            key.push(
                columns
                    .get(physical_column)
                    .ok_or(RelQueryError::ColumnOutOfBounds)?
                    .value_at(position),
            );
        }
        stats.values_read = stats
            .values_read
            .saturating_add(physical_group_columns.len());
        let mut found = None;
        'groups: for (index, (existing, _)) in groups.iter().enumerate() {
            for ((left, right), equivalence) in
                existing.iter().zip(&key).zip(spec.group_equivalences)
            {
                if !env
                    .registry
                    .equivalent(env.context, *equivalence, left, right)?
                {
                    continue 'groups;
                }
            }
            found = Some(index);
            break;
        }
        let index = if let Some(index) = found {
            index
        } else {
            groups.push((key, new_typed_group_state(spec.aggregate)));
            groups.len() - 1
        };
        match (&mut groups[index].1, spec.aggregate) {
            (TypedGroupState::Count(count), AggregateSpec::Count { .. }) => count.add_one(),
            (TypedGroupState::ExactF64Sum(sum), AggregateSpec::ExactF64Sum { .. }) => {
                let physical_column =
                    physical_sum_column.ok_or(RelQueryError::ColumnOutOfBounds)?;
                let column = columns
                    .get(physical_column)
                    .ok_or(RelQueryError::ColumnOutOfBounds)?;
                let NativeColumn::F64Bits(values) = column else {
                    return Err(PhysicalExecutionError::PhysicalTypeMismatch);
                };
                let bits = *values
                    .get(position)
                    .ok_or(PhysicalExecutionError::ColumnShapeMismatch)?;
                stats.values_read = stats.values_read.saturating_add(1);
                sum.add(f64::from_bits(bits)).map_err(RelQueryError::from)?;
            }
            _ => return Err(RelQueryError::TypeMismatch.into()),
        }
    }
    finish_typed_groups(groups)
}

fn top_k_typed_batch_selection(
    program: &TypedBatchProgram<'_>,
    columns: &[NativeColumn],
    mut positions: Vec<usize>,
    spec: TopKBatchSpec,
    env: &StatefulBatchEnv<'_>,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    if spec.k == 0 || positions.is_empty() {
        return Ok(Vec::new());
    }
    let physical_column = *program
        .columns
        .get(spec.column)
        .ok_or(RelQueryError::ColumnOutOfBounds)?;
    let order_column = columns
        .get(physical_column)
        .ok_or(RelQueryError::ColumnOutOfBounds)?;
    if matches!(
        env.registry.ordering_domain(env.context, spec.ordering)?,
        kernel_semantics::OrderingDomain::I64
    ) && let NativeColumn::I64(values) = order_column
    {
        select_top_k_i64_positions(&mut positions, values, spec.direction, spec.k, stats);
        return positions
            .into_iter()
            .map(|position| materialize_typed_batch_row(program, columns, position, stats))
            .collect();
    }
    sort_typed_top_k_positions(&mut positions, order_column, spec, env, stats)?;
    if spec.k < positions.len() {
        let threshold = order_column.value_at(positions[spec.k - 1]);
        stats.values_read = stats.values_read.saturating_add(1);
        let mut keep = spec.k;
        while keep < positions.len() {
            let candidate = order_column.value_at(positions[keep]);
            stats.values_read = stats.values_read.saturating_add(1);
            if env
                .registry
                .compare(env.context, spec.ordering, &candidate, &threshold)?
                != std::cmp::Ordering::Equal
            {
                break;
            }
            keep += 1;
        }
        positions.truncate(keep);
    }
    positions
        .into_iter()
        .map(|position| materialize_typed_batch_row(program, columns, position, stats))
        .collect()
}

fn select_top_k_i64_positions(
    positions: &mut Vec<usize>,
    values: &[i64],
    direction: OrderDirection,
    k: usize,
    stats: &mut ExecutionStats,
) {
    stats.values_read = stats.values_read.saturating_add(positions.len());
    if k < positions.len() {
        let mut keys = positions
            .iter()
            .map(|&position| values[position])
            .collect::<Vec<_>>();
        let threshold_index = match direction {
            OrderDirection::Ascending => k - 1,
            OrderDirection::Descending => keys.len() - k,
        };
        let (_, threshold, _) = keys.select_nth_unstable(threshold_index);
        let threshold = *threshold;
        match direction {
            OrderDirection::Ascending => {
                positions.retain(|&position| values[position] <= threshold);
                positions.sort_by_key(|&position| values[position]);
            }
            OrderDirection::Descending => {
                positions.retain(|&position| values[position] >= threshold);
                positions.sort_by_key(|&position| std::cmp::Reverse(values[position]));
            }
        }
    } else {
        match direction {
            OrderDirection::Ascending => positions.sort_by_key(|&position| values[position]),
            OrderDirection::Descending => {
                positions.sort_by_key(|&position| std::cmp::Reverse(values[position]));
            }
        }
    }
}

fn sort_typed_top_k_positions(
    positions: &mut [usize],
    order_column: &NativeColumn,
    spec: TopKBatchSpec,
    env: &StatefulBatchEnv<'_>,
    stats: &mut ExecutionStats,
) -> Result<(), PhysicalExecutionError> {
    let reverse = spec.direction == OrderDirection::Descending;
    match (
        env.registry.ordering_domain(env.context, spec.ordering)?,
        order_column,
    ) {
        (kernel_semantics::OrderingDomain::I64, NativeColumn::I64(values)) => {
            stats.values_read = stats.values_read.saturating_add(positions.len());
            positions.sort_by(|left, right| {
                let compared = values[*left].cmp(&values[*right]);
                if reverse {
                    compared.reverse()
                } else {
                    compared
                }
            });
            Ok(())
        }
        (kernel_semantics::OrderingDomain::F64, NativeColumn::F64Bits(values)) => {
            positions.sort_by(|left, right| {
                stats.values_read = stats.values_read.saturating_add(2);
                let compared =
                    f64::from_bits(values[*left]).total_cmp(&f64::from_bits(values[*right]));
                if reverse {
                    compared.reverse()
                } else {
                    compared
                }
            });
            Ok(())
        }
        _ => {
            // General semantic-order fallback. It still sorts positions rather than rows;
            // primitive numeric domains above keep registry dispatch out of the comparator.
            let mut error = None;
            positions.sort_by(|left, right| {
                if error.is_some() {
                    return std::cmp::Ordering::Equal;
                }
                let left = order_column.value_at(*left);
                let right = order_column.value_at(*right);
                stats.values_read = stats.values_read.saturating_add(2);
                match env
                    .registry
                    .compare(env.context, spec.ordering, &left, &right)
                {
                    Ok(compared) => {
                        if reverse {
                            compared.reverse()
                        } else {
                            compared
                        }
                    }
                    Err(problem) => {
                        error = Some(problem);
                        std::cmp::Ordering::Equal
                    }
                }
            });
            if let Some(problem) = error {
                return Err(problem.into());
            }
            Ok(())
        }
    }
}

fn try_execute_typed_batch_chain(
    plan: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<(Vec<kernel_query::Row>, ExecutionStats)>, PhysicalExecutionError> {
    let Some(program) = build_typed_batch_program(plan, store, context, registry)? else {
        return Ok(None);
    };
    let NativeRelation::TypedColumnar { columns, .. } = &program.installed.data else {
        return Ok(None);
    };
    if let Some(result) = try_execute_i64_batch_program(&program, columns) {
        return Ok(Some(result));
    }
    let mut stats = ExecutionStats::default();
    let mut rows = Vec::new();
    if program.installed.scan_order_is_physical {
        for position in 0..native_row_count(&program.installed.data) {
            execute_typed_batch_position(position, &program, columns, &mut rows, &mut stats)?;
        }
    } else {
        for position in program.installed.scan_positions() {
            execute_typed_batch_position(position, &program, columns, &mut rows, &mut stats)?;
        }
    }
    stats.typed_batch_chain_hits = stats.typed_batch_chain_hits.saturating_add(1);
    Ok(Some((rows, stats)))
}

#[inline]
fn execute_typed_batch_position(
    position: usize,
    program: &TypedBatchProgram<'_>,
    columns: &[NativeColumn],
    rows: &mut Vec<kernel_query::Row>,
    stats: &mut ExecutionStats,
) -> Result<(), PhysicalExecutionError> {
    stats.scanned_rows = stats.scanned_rows.saturating_add(1);
    for predicate in &program.predicates {
        stats.values_read = stats.values_read.saturating_add(1);
        if !typed_batch_predicate_matches(
            columns
                .get(predicate.physical_column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?,
            position,
            predicate,
        )? {
            return Ok(());
        }
    }
    let mut row = Vec::with_capacity(program.columns.len());
    for &column in &program.columns {
        row.push(
            columns
                .get(column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?
                .value_at(position),
        );
    }
    stats.values_read = stats.values_read.saturating_add(program.columns.len());
    rows.push(row);
    Ok(())
}

fn try_execute_i64_batch_program(
    program: &TypedBatchProgram<'_>,
    columns: &[NativeColumn],
) -> Option<(Vec<kernel_query::Row>, ExecutionStats)> {
    let mut projected = Vec::with_capacity(program.columns.len());
    for &column in &program.columns {
        let Some(NativeColumn::I64(values)) = columns.get(column) else {
            return None;
        };
        projected.push(values.as_slice());
    }
    let mut predicates = Vec::with_capacity(program.predicates.len());
    for predicate in &program.predicates {
        let Some(NativeColumn::I64(values)) = columns.get(predicate.physical_column) else {
            return None;
        };
        let TypedBatchPredicateKind::Primitive(kernel_semantics::BoundPrimitivePredicate::I64(
            expected,
        )) = &predicate.kind
        else {
            return None;
        };
        predicates.push((values.as_slice(), *expected));
    }

    let mut stats = ExecutionStats::default();
    let mut rows = Vec::new();
    if program.installed.scan_order_is_physical {
        execute_i64_batch_positions(
            0..native_row_count(&program.installed.data),
            &predicates,
            &projected,
            &mut rows,
            &mut stats,
        );
    } else {
        execute_i64_batch_positions(
            program.installed.scan_positions(),
            &predicates,
            &projected,
            &mut rows,
            &mut stats,
        );
    }
    stats.typed_batch_chain_hits = stats.typed_batch_chain_hits.saturating_add(1);
    Some((rows, stats))
}

fn execute_i64_batch_positions(
    positions: impl IntoIterator<Item = usize>,
    predicates: &[(&[i64], i64)],
    projected: &[&[i64]],
    rows: &mut Vec<kernel_query::Row>,
    stats: &mut ExecutionStats,
) {
    match predicates {
        [] => {
            for position in positions {
                stats.scanned_rows = stats.scanned_rows.saturating_add(1);
                push_i64_batch_projection(projected, position, rows, stats);
            }
        }
        [(first, expected)] => {
            for position in positions {
                stats.scanned_rows = stats.scanned_rows.saturating_add(1);
                stats.values_read = stats.values_read.saturating_add(1);
                if first[position] == *expected {
                    push_i64_batch_projection(projected, position, rows, stats);
                }
            }
        }
        [(first, first_expected), (second, second_expected)] => {
            for position in positions {
                stats.scanned_rows = stats.scanned_rows.saturating_add(1);
                stats.values_read = stats.values_read.saturating_add(1);
                if first[position] != *first_expected {
                    continue;
                }
                stats.values_read = stats.values_read.saturating_add(1);
                if second[position] == *second_expected {
                    push_i64_batch_projection(projected, position, rows, stats);
                }
            }
        }
        _ => {
            for position in positions {
                stats.scanned_rows = stats.scanned_rows.saturating_add(1);
                let mut matched = true;
                for (values, expected) in predicates {
                    stats.values_read = stats.values_read.saturating_add(1);
                    if values[position] != *expected {
                        matched = false;
                        break;
                    }
                }
                if matched {
                    push_i64_batch_projection(projected, position, rows, stats);
                }
            }
        }
    }
}

fn push_i64_batch_projection(
    projected: &[&[i64]],
    position: usize,
    rows: &mut Vec<kernel_query::Row>,
    stats: &mut ExecutionStats,
) {
    if let [values] = projected {
        rows.push(vec![Value::I64(values[position])]);
    } else {
        rows.push(
            projected
                .iter()
                .map(|values| Value::I64(values[position]))
                .collect(),
        );
    }
    stats.values_read = stats.values_read.saturating_add(projected.len());
}

fn build_typed_batch_program<'a>(
    plan: &Plan,
    store: &'a PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<TypedBatchProgram<'a>>, PhysicalExecutionError> {
    match plan {
        Plan::Scan {
            relation,
            layout,
            algorithm: ScanAlgorithm::FullScan,
        } => {
            let installed = store.installed(*relation, *layout)?;
            let NativeRelation::TypedColumnar { columns, .. } = &installed.data else {
                return Ok(None);
            };
            validate_typed_columnar_schema(context, *relation, columns)?;
            Ok(Some(TypedBatchProgram {
                installed,
                columns: (0..columns.len()).collect(),
                predicates: Vec::new(),
            }))
        }
        Plan::Project { input, columns } => {
            let Some(mut program) = build_typed_batch_program(input, store, context, registry)?
            else {
                return Ok(None);
            };
            let mut projected = Vec::with_capacity(columns.len());
            for &column in columns {
                projected.push(
                    *program
                        .columns
                        .get(column)
                        .ok_or(RelQueryError::ColumnOutOfBounds)?,
                );
            }
            program.columns = projected;
            Ok(Some(program))
        }
        Plan::FilterEqConst {
            input,
            column,
            value,
            equivalence,
        } => {
            let Some(mut program) = build_typed_batch_program(input, store, context, registry)?
            else {
                return Ok(None);
            };
            let Some(&physical_column) = program.columns.get(*column) else {
                return Err(RelQueryError::ColumnOutOfBounds.into());
            };
            let NativeRelation::TypedColumnar { columns, .. } = &program.installed.data else {
                return Ok(None);
            };
            let predicate = columns
                .get(physical_column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            let kind = if let Some(resolved) =
                registry.resolve_primitive_equivalence(context, *equivalence)?
            {
                let bound = resolved.bind_right(value)?;
                // Reject a physical/schema mismatch before entering the scan loop.
                if let Some(position) = program.installed.scan_positions().next() {
                    let _ = typed_column_matches_bound(predicate, position, &bound)?;
                } else if !typed_column_bound_compatible(predicate, &bound) {
                    return Err(PhysicalExecutionError::PhysicalTypeMismatch);
                }
                TypedBatchPredicateKind::Primitive(bound)
            } else if let NativeColumn::Algebraic(column) = predicate
                && context
                    .schema
                    .structural_equivalence(*equivalence)
                    .is_some()
            {
                let compiled = registry.compile_equivalence(context, *equivalence)?;
                let expected = compiled.canonical_key(value)?;
                if let Some(position) = program.installed.scan_positions().next() {
                    let _ = column.canonical_key_at_compiled(position, &compiled)?;
                }
                TypedBatchPredicateKind::Algebraic { compiled, expected }
            } else {
                return Ok(None);
            };
            program.predicates.push(TypedBatchPredicate {
                physical_column,
                kind,
            });
            Ok(Some(program))
        }
        Plan::PromoteToBag(input) => build_typed_batch_program(input, store, context, registry),
        Plan::FilterEqColumns { .. }
        | Plan::JoinEq { .. }
        | Plan::Difference { .. }
        | Plan::AntiJoin { .. }
        | Plan::Distinct { .. }
        | Plan::Group { .. }
        | Plan::TopKWithTies { .. } => Ok(None),
    }
}

fn typed_column_bound_compatible(
    column: &NativeColumn,
    bound: &kernel_semantics::BoundPrimitivePredicate,
) -> bool {
    matches!(
        (column, bound),
        (
            NativeColumn::Unit(_),
            kernel_semantics::BoundPrimitivePredicate::Unit
        ) | (
            NativeColumn::Bool(_),
            kernel_semantics::BoundPrimitivePredicate::Bool(_)
        ) | (
            NativeColumn::I64(_),
            kernel_semantics::BoundPrimitivePredicate::I64(_)
        ) | (
            NativeColumn::F64Bits(_),
            kernel_semantics::BoundPrimitivePredicate::F64Bits(_)
        ) | (
            NativeColumn::Text(_),
            kernel_semantics::BoundPrimitivePredicate::TextExact(_)
                | kernel_semantics::BoundPrimitivePredicate::TextAsciiCaseInsensitive(_)
        )
    ) || matches!(
        (column, bound),
        (
            NativeColumn::LiveEntityIds { entity_type, .. },
            kernel_semantics::BoundPrimitivePredicate::LiveEntityId {
                entity_type: expected_type,
                ..
            }
        ) if entity_type == expected_type
    ) || matches!(
        (column, bound),
        (
            NativeColumn::DenseLiveEntityIds { entity_type, .. },
            kernel_semantics::BoundPrimitivePredicate::LiveEntityId {
                entity_type: expected_type,
                ..
            }
        ) if entity_type == expected_type
    ) || matches!(
        (column, bound),
        (
            NativeColumn::HistoricalEntityIds { entity_type, .. },
            kernel_semantics::BoundPrimitivePredicate::HistoricalEntityId {
                entity_type: expected_type,
                ..
            }
        ) if entity_type == expected_type
    )
}

fn typed_column_matches_bound(
    column: &NativeColumn,
    index: usize,
    bound: &kernel_semantics::BoundPrimitivePredicate,
) -> Result<bool, PhysicalExecutionError> {
    if !typed_column_bound_compatible(column, bound) {
        return Err(PhysicalExecutionError::PhysicalTypeMismatch);
    }
    let matched = match (column, bound) {
        (NativeColumn::Unit(_), kernel_semantics::BoundPrimitivePredicate::Unit) => true,
        (NativeColumn::Bool(values), kernel_semantics::BoundPrimitivePredicate::Bool(expected)) => {
            values.get(index).is_some_and(|value| value == expected)
        }
        (NativeColumn::I64(values), kernel_semantics::BoundPrimitivePredicate::I64(expected)) => {
            values.get(index).is_some_and(|value| value == expected)
        }
        (
            NativeColumn::F64Bits(values),
            kernel_semantics::BoundPrimitivePredicate::F64Bits(expected),
        ) => values.get(index).is_some_and(|value| value == expected),
        (
            NativeColumn::Text(values),
            kernel_semantics::BoundPrimitivePredicate::TextExact(expected),
        ) => values.get(index).is_some_and(|value| value == expected),
        (
            NativeColumn::Text(values),
            kernel_semantics::BoundPrimitivePredicate::TextAsciiCaseInsensitive(expected),
        ) => values
            .get(index)
            .is_some_and(|value| value.eq_ignore_ascii_case(expected)),
        (
            NativeColumn::LiveEntityIds { values, .. },
            kernel_semantics::BoundPrimitivePredicate::LiveEntityId { id: expected, .. },
        ) => values.get(index).is_some_and(|value| value == expected),
        (
            NativeColumn::DenseLiveEntityIds { ids, values, .. },
            kernel_semantics::BoundPrimitivePredicate::LiveEntityId { id: expected, .. },
        ) => ids
            .local(*expected)
            .is_some_and(|expected| values.get(index).is_some_and(|value| *value == expected)),
        (
            NativeColumn::HistoricalEntityIds { values, .. },
            kernel_semantics::BoundPrimitivePredicate::HistoricalEntityId { id: expected, .. },
        ) => values.get(index).is_some_and(|value| value == expected),
        _ => return Err(PhysicalExecutionError::PhysicalTypeMismatch),
    };
    Ok(matched)
}

fn typed_batch_predicate_matches(
    column: &NativeColumn,
    index: usize,
    predicate: &TypedBatchPredicate,
) -> Result<bool, PhysicalExecutionError> {
    match &predicate.kind {
        TypedBatchPredicateKind::Primitive(bound) => {
            typed_column_matches_bound(column, index, bound)
        }
        TypedBatchPredicateKind::Algebraic { compiled, expected } => {
            let NativeColumn::Algebraic(column) = column else {
                return Err(PhysicalExecutionError::PhysicalTypeMismatch);
            };
            Ok(column.canonical_key_at_compiled(index, compiled)? == *expected)
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct SemanticFilterPredicate<'a> {
    column: usize,
    value: &'a Value,
    equivalence: SemanticId,
}

fn collect_direct_filter_chain(
    plan: &Plan,
) -> Option<(SemanticId, LayoutBinding, Vec<SemanticFilterPredicate<'_>>)> {
    let mut predicates = Vec::new();
    let mut current = plan;
    loop {
        match current {
            Plan::FilterEqConst {
                input,
                column,
                value,
                equivalence,
            } => {
                predicates.push(SemanticFilterPredicate {
                    column: *column,
                    value,
                    equivalence: *equivalence,
                });
                current = input;
            }
            Plan::Scan {
                relation,
                layout,
                algorithm: ScanAlgorithm::FullScan,
            } => return Some((*relation, *layout, predicates)),
            _ => return None,
        }
    }
}

fn try_execute_persisted_semantic_filter_plan(
    plan: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let Some((relation, layout, predicates)) = collect_direct_filter_chain(plan) else {
        return Ok(None);
    };
    if predicates.is_empty() {
        return Ok(None);
    }
    let installed = store.installed(relation, layout)?;
    let row_count = native_row_count(&installed.data);
    let bindings = store
        .semantic_indexes
        .keys()
        .chain(store.observable_atom_states.keys())
        .filter(|binding| binding.relation == relation && binding.layout == layout)
        .cloned()
        .collect::<BTreeSet<_>>();
    let mut rejected_by_cost = false;
    let mut best: Option<(SemanticIndexBinding, Vec<&Value>, usize, usize)> = None;

    for binding in bindings {
        let Some(capability) = store.semantic_fiber_capability(&binding, context, registry)? else {
            continue;
        };
        let mut values = Vec::with_capacity(binding.key_parts.len());
        let mut complete = true;
        for part in &binding.key_parts {
            let Some(predicate) = predicates.iter().find(|predicate| {
                predicate.column == part.column && predicate.equivalence == part.equivalence
            }) else {
                complete = false;
                break;
            };
            values.push(predicate.value);
        }
        if !complete {
            continue;
        }
        let matching_rows = capability
            .probe_values(&values, context, registry)?
            .map_or(0, |rows| rows.len());
        if SemanticAccessCostModel::choose_filter(row_count, matching_rows)
            == SemanticAccessPath::FullScan
        {
            rejected_by_cost = true;
            continue;
        }
        let replace = best.as_ref().is_none_or(|(_, _, best_rows, best_parts)| {
            matching_rows < *best_rows
                || (matching_rows == *best_rows && binding.key_parts.len() > *best_parts)
        });
        if replace {
            let parts = binding.key_parts.len();
            best = Some((binding, values, matching_rows, parts));
        }
    }

    let Some((binding, values, _, _)) = best else {
        if rejected_by_cost {
            stats.persisted_index_cost_rejections =
                stats.persisted_index_cost_rejections.saturating_add(1);
        }
        return Ok(None);
    };
    let capability = store
        .semantic_fiber_capability(&binding, context, registry)?
        .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
    let Some(row_ids) = capability.probe_values(&values, context, registry)? else {
        stats.persisted_index_hits = stats.persisted_index_hits.saturating_add(1);
        return Ok(Some(Vec::new()));
    };
    let mut rows = Vec::with_capacity(row_ids.len());
    for row_id in row_ids {
        let position = installed
            .position(row_id)
            .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
        let row = materialize_native_row(&installed.data, position)?;
        let mut matched = true;
        for predicate in &predicates {
            let candidate = row
                .get(predicate.column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            stats.values_read = stats.values_read.saturating_add(1);
            if !registry.equivalent(context, predicate.equivalence, candidate, predicate.value)? {
                matched = false;
                break;
            }
        }
        stats.scanned_rows = stats.scanned_rows.saturating_add(1);
        if matched {
            stats.values_read = stats.values_read.saturating_add(row.len());
            rows.push(row);
        }
    }
    stats.persisted_index_hits = stats.persisted_index_hits.saturating_add(1);
    Ok(Some(rows))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct MultiwayJoinColumnRef {
    leaf: usize,
    column: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MultiwayJoinLeaf {
    plan: Plan,
    relation: SemanticId,
    layout: LayoutBinding,
    width: usize,
    rows: usize,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct MultiwayJoinPredicate {
    left: MultiwayJoinColumnRef,
    right: MultiwayJoinColumnRef,
    equivalence: SemanticId,
}

/// Query-local APNF coordinate program.
///
/// Each logical join predicate owns a distinct observable coordinate even when
/// multiple predicates use the same pinned Γ-equivalence. The coordinate IDs
/// themselves are allocated only when execution constructs a revision-local
/// observable catalog; this prepared form contains no semantic state.
#[derive(Debug, Clone, PartialEq, Eq)]
struct PreparedAnchorPullbackProgram {
    leaf_count: usize,
    predicates: Vec<MultiwayJoinPredicate>,
}

#[derive(Debug, Clone)]
struct MultiwayJoinCandidate {
    plan: Plan,
    cost: u128,
    estimated_rows: usize,
}

#[derive(Debug, Clone, Copy)]
struct MultiwayJoinInterval {
    start: usize,
    split: usize,
    end: usize,
}

struct MultiwayPlannerContext<'a> {
    store: &'a PhysicalStore,
    leaves: &'a [MultiwayJoinLeaf],
    context: &'a kernel_schema::SemanticContext,
    registry: &'a kernel_semantics::SemanticRegistry,
}

struct PreferredNwayOrderPreservingJoin {
    leaves: Vec<MultiwayJoinLeaf>,
    predicates: Vec<MultiwayJoinPredicate>,
    search_order: Vec<usize>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SemanticQuotientSearchCertificate {
    GyoAcyclic,
    BoundedCyclic,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PreparedSemanticQuotientProgram {
    specs: Vec<(SemanticId, Vec<MultiwayJoinColumnRef>)>,
    hypergraph_order: Option<Vec<usize>>,
    search_certificate: Option<SemanticQuotientSearchCertificate>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SemanticQuotientLeaf {
    leaf: usize,
    keys: Vec<Option<kernel_semantics::CanonicalEqKey>>,
    buckets: BTreeMap<kernel_semantics::CanonicalEqKey, Vec<u64>>,
    live_rows_by_key: BTreeMap<kernel_semantics::CanonicalEqKey, usize>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SemanticQuotientConstraint {
    leaves: Vec<SemanticQuotientLeaf>,
    key_leaf_support: BTreeMap<kernel_semantics::CanonicalEqKey, usize>,
    live_key_leaf_support: BTreeMap<kernel_semantics::CanonicalEqKey, usize>,
}

type SemanticQuotientKeySpec = (usize, usize, SemanticId);
type SemanticQuotientKeyCache =
    BTreeMap<SemanticQuotientKeySpec, Vec<kernel_semantics::CanonicalEqKey>>;

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct SemanticQuotientSupportBinding {
    leaves: Vec<(SemanticId, LayoutBinding, usize)>,
    specs: Vec<(SemanticId, Vec<MultiwayJoinColumnRef>)>,
}

#[derive(Debug, Clone)]
struct MaterializedSemanticQuotientSupportState {
    binding: SemanticQuotientSupportBinding,
    key_binding: kernel_semantic_index::SemanticIndexBinding,
    handles: Vec<Vec<PhysicalRowId>>,
    constraints: Vec<SemanticQuotientConstraint>,
    base_masks: Vec<Vec<u64>>,
    bfc: SemanticQuotientBfcMaintenance,
}

impl PartialEq for MaterializedSemanticQuotientSupportState {
    fn eq(&self, other: &Self) -> bool {
        self.binding == other.binding
            && self.key_binding == other.key_binding
            && self.handles == other.handles
            && self.constraints == other.constraints
            && self.base_masks == other.base_masks
    }
}

impl Eq for MaterializedSemanticQuotientSupportState {}

/// Reconstructible maintenance acceleration for the semantic quotient support
/// state. Atom ids are stable for the lifetime of this materialization and are
/// keyed by `(leaf, StableRowHandle)`, including the handle generation.
#[derive(Debug, Clone)]
struct SemanticQuotientBfcMaintenance {
    atoms_by_handle: Vec<BTreeMap<PhysicalRowId, kernel_grounded_closure::GroundedAtomId>>,
    program: kernel_grounded_closure::BipolarSupportProgram,
    certificate: kernel_grounded_closure::BipolarSupportCertificate,
    last_work: kernel_grounded_closure::GroundedWorkStats,
}

#[derive(Debug)]
struct SemanticQuotientComponentRefreshLeafPatch {
    leaf: usize,
    handles: Vec<PhysicalRowId>,
    constraint_keys: Vec<(usize, Vec<Option<kernel_semantics::CanonicalEqKey>>)>,
}

impl MaterializedSemanticQuotientSupportState {
    fn compatible_with(
        &self,
        context: &kernel_schema::SemanticContext,
        registry: &kernel_semantics::SemanticRegistry,
    ) -> Result<bool, PhysicalExecutionError> {
        let dependencies = semantic_key_dependencies_for_equivalences(
            self.binding
                .specs
                .iter()
                .map(|(equivalence, _)| *equivalence),
            context,
            registry,
        )?;
        Ok(self.key_binding.is_valid_for(context, &dependencies))
    }

    fn supports_relation(&self, relation: SemanticId, layout: LayoutBinding) -> bool {
        self.binding
            .leaves
            .iter()
            .any(|(candidate, candidate_layout, _)| {
                *candidate == relation && candidate_layout.id == layout.id
            })
    }

    fn apply_bfc_structural_refresh(
        &mut self,
        patches: Vec<SemanticQuotientComponentRefreshLeafPatch>,
    ) -> bool {
        if patches.is_empty() {
            return false;
        }
        let mut touched_constraints = BTreeSet::new();
        for patch in patches {
            self.handles[patch.leaf] = patch.handles;
            for (constraint_index, keys) in patch.constraint_keys {
                let Some(quotient_leaf) = self.constraints[constraint_index]
                    .leaves
                    .iter_mut()
                    .find(|candidate| candidate.leaf == patch.leaf)
                else {
                    return false;
                };
                quotient_leaf.keys = keys;
                rebuild_quotient_leaf_buckets(quotient_leaf);
                touched_constraints.insert(constraint_index);
            }
        }
        for constraint_index in touched_constraints {
            self.constraints[constraint_index].key_leaf_support =
                quotient_key_leaf_support(&self.constraints[constraint_index].leaves);
        }
        let mut atom_count = self.bfc.program.atom_count();
        for (leaf, handles) in self.handles.iter().enumerate() {
            for handle in handles {
                self.bfc.atoms_by_handle[leaf]
                    .entry(*handle)
                    .or_insert_with(|| {
                        let atom = kernel_grounded_closure::GroundedAtomId::new(atom_count);
                        atom_count = atom_count.saturating_add(1);
                        atom
                    });
            }
        }
        let Ok(program) = compile_semantic_quotient_bfc_program(
            &self.handles,
            &self.constraints,
            &self.bfc.atoms_by_handle,
            atom_count,
        ) else {
            return false;
        };
        let Ok((certificate, work)) = kernel_grounded_closure::reconcile_bipolar_support(
            &self.bfc.program,
            &program,
            &self.bfc.certificate,
        ) else {
            return false;
        };
        let Ok(masks) = semantic_quotient_masks_from_bfc(
            &self.handles,
            &self.bfc.atoms_by_handle,
            &certificate,
        ) else {
            return false;
        };
        self.base_masks = masks;
        for constraint in &mut self.constraints {
            reset_constraint_live_support(constraint, &self.base_masks);
        }
        self.bfc.program = program;
        self.bfc.certificate = certificate;
        self.bfc.last_work = work;
        true
    }
}

#[cfg(test)]
fn full_ordinal_mask(row_count: usize) -> Vec<u64> {
    let words = row_count.div_ceil(64);
    let mut mask = vec![u64::MAX; words];
    if let Some(last) = mask.last_mut() {
        let used = row_count % 64;
        if used != 0 {
            *last = (1_u64 << used) - 1;
        }
    }
    mask
}

fn mask_contains(mask: &[u64], ordinal: usize) -> bool {
    mask.get(ordinal / 64)
        .is_some_and(|word| word & (1_u64 << (ordinal % 64)) != 0)
}

#[cfg(test)]
fn mask_clear(mask: &mut [u64], ordinal: usize) -> bool {
    let Some(word) = mask.get_mut(ordinal / 64) else {
        return false;
    };
    let bit = 1_u64 << (ordinal % 64);
    let changed = *word & bit != 0;
    *word &= !bit;
    changed
}

fn mask_intersect_in_place(target: &mut [u64], other: &[u64]) {
    for (target, other) in target.iter_mut().zip(other) {
        *target &= *other;
    }
}

fn masks_intersect(left: &[u64], right: &[u64]) -> bool {
    left.iter()
        .zip(right)
        .any(|(left, right)| left & right != 0)
}

fn quotient_ordinal_transport(
    current: &[PhysicalRowId],
    next: &[PhysicalRowId],
) -> Option<(Vec<Option<usize>>, Vec<usize>)> {
    let next_ordinals = next
        .iter()
        .enumerate()
        .map(|(ordinal, handle)| (*handle, ordinal))
        .collect::<BTreeMap<_, _>>();
    if next_ordinals.len() != next.len() {
        return None;
    }
    let current_handles = current.iter().copied().collect::<BTreeSet<_>>();
    if current_handles.len() != current.len() {
        return None;
    }
    let old_to_new = current
        .iter()
        .map(|handle| next_ordinals.get(handle).copied())
        .collect::<Vec<_>>();
    let surviving_ordinals = old_to_new.iter().flatten().copied().collect::<Vec<_>>();
    if !surviving_ordinals
        .windows(2)
        .all(|window| window[0] < window[1])
    {
        return None;
    }
    let inserted = next
        .iter()
        .enumerate()
        .filter_map(|(ordinal, handle)| (!current_handles.contains(handle)).then_some(ordinal))
        .collect::<Vec<_>>();
    Some((old_to_new, inserted))
}

fn rebuild_quotient_leaf_buckets(leaf: &mut SemanticQuotientLeaf) {
    leaf.buckets.clear();
    let words = leaf.keys.len().div_ceil(64);
    for (ordinal, key) in leaf.keys.iter().enumerate() {
        let Some(key) = key else {
            continue;
        };
        let bucket = leaf
            .buckets
            .entry(key.clone())
            .or_insert_with(|| vec![0; words]);
        bucket[ordinal / 64] |= 1_u64 << (ordinal % 64);
    }
}

fn quotient_live_row_counts(
    leaf: &SemanticQuotientLeaf,
    mask: &[u64],
) -> BTreeMap<kernel_semantics::CanonicalEqKey, usize> {
    let mut counts = BTreeMap::new();
    for (ordinal, key) in leaf.keys.iter().enumerate() {
        if !mask_contains(mask, ordinal) {
            continue;
        }
        if let Some(key) = key {
            *counts.entry(key.clone()).or_insert(0) += 1;
        }
    }
    counts
}

fn reset_constraint_live_support(constraint: &mut SemanticQuotientConstraint, masks: &[Vec<u64>]) {
    let mut support = BTreeMap::new();
    for leaf in &mut constraint.leaves {
        leaf.live_rows_by_key = quotient_live_row_counts(leaf, &masks[leaf.leaf]);
        for key in leaf.live_rows_by_key.keys() {
            *support.entry(key.clone()).or_insert(0) += 1;
        }
    }
    constraint.live_key_leaf_support = support;
}

#[cfg(test)]
fn remove_live_ordinal_from_constraint(
    constraint: &mut SemanticQuotientConstraint,
    leaf_index: usize,
    ordinal: usize,
) {
    let Some(quotient_leaf) = constraint
        .leaves
        .iter_mut()
        .find(|candidate| candidate.leaf == leaf_index)
    else {
        return;
    };
    let Some(key) = quotient_leaf
        .keys
        .get(ordinal)
        .and_then(Option::as_ref)
        .cloned()
    else {
        return;
    };
    let Some(row_count) = quotient_leaf.live_rows_by_key.get_mut(&key) else {
        return;
    };
    *row_count = row_count.saturating_sub(1);
    if *row_count != 0 {
        return;
    }
    quotient_leaf.live_rows_by_key.remove(&key);
    if let Some(support) = constraint.live_key_leaf_support.get_mut(&key) {
        *support = support.saturating_sub(1);
        if *support == 0 {
            constraint.live_key_leaf_support.remove(&key);
        }
    }
}

#[cfg(test)]
fn constraint_viable_keys(
    constraint: &SemanticQuotientConstraint,
) -> BTreeSet<kernel_semantics::CanonicalEqKey> {
    let required = constraint.leaves.len();
    constraint
        .live_key_leaf_support
        .iter()
        .filter(|(key, support)| {
            **support == required && constraint.key_leaf_support.get(*key) == Some(&required)
        })
        .map(|(key, _)| key.clone())
        .collect()
}

#[cfg(test)]
fn quotient_constraints_by_leaf(
    leaf_count: usize,
    constraints: &[SemanticQuotientConstraint],
) -> Vec<Vec<usize>> {
    let mut constraints_by_leaf = vec![Vec::new(); leaf_count];
    for (constraint_index, constraint) in constraints.iter().enumerate() {
        for leaf in &constraint.leaves {
            constraints_by_leaf[leaf.leaf].push(constraint_index);
        }
    }
    constraints_by_leaf
}

#[cfg(test)]
fn propagate_quotient_support_deletions(
    handles: &[Vec<PhysicalRowId>],
    constraints: &mut [SemanticQuotientConstraint],
    masks: &mut [Vec<u64>],
    changed_leaves: &[usize],
) {
    let constraints_by_leaf = quotient_constraints_by_leaf(handles.len(), constraints);
    let mut queued = vec![false; constraints.len()];
    let mut queue = std::collections::VecDeque::new();
    for leaf in changed_leaves {
        for constraint in &constraints_by_leaf[*leaf] {
            if !queued[*constraint] {
                queued[*constraint] = true;
                queue.push_back(*constraint);
            }
        }
    }
    while let Some(constraint_index) = queue.pop_front() {
        queued[constraint_index] = false;
        let viable_keys = constraint_viable_keys(&constraints[constraint_index]);
        let constraint_leaves = constraints[constraint_index]
            .leaves
            .iter()
            .map(|leaf| (leaf.leaf, leaf.keys.clone()))
            .collect::<Vec<_>>();
        for (leaf_index, keys) in constraint_leaves {
            let mut leaf_changed = false;
            for (ordinal, key) in keys.iter().enumerate() {
                if mask_contains(&masks[leaf_index], ordinal)
                    && key.as_ref().is_none_or(|key| !viable_keys.contains(key))
                {
                    for dependent in &constraints_by_leaf[leaf_index] {
                        remove_live_ordinal_from_constraint(
                            &mut constraints[*dependent],
                            leaf_index,
                            ordinal,
                        );
                    }
                    leaf_changed |= mask_clear(&mut masks[leaf_index], ordinal);
                }
            }
            if leaf_changed {
                for dependent in &constraints_by_leaf[leaf_index] {
                    if !queued[*dependent] {
                        queued[*dependent] = true;
                        queue.push_back(*dependent);
                    }
                }
            }
        }
    }
}

fn prepare_semantic_quotient_component_refresh_patches(
    state: &MaterializedSemanticQuotientSupportState,
    leaf_updates: &[(usize, Vec<PhysicalRowId>)],
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<Vec<SemanticQuotientComponentRefreshLeafPatch>>, PhysicalExecutionError> {
    if !state.compatible_with(context, registry)? || leaf_updates.is_empty() {
        return Ok(None);
    }
    let mut patches = Vec::with_capacity(leaf_updates.len());
    for (leaf, next_handles) in leaf_updates {
        let Some(current_handles) = state.handles.get(*leaf) else {
            return Ok(None);
        };
        let Some((old_to_new, inserted_ordinals)) =
            quotient_ordinal_transport(current_handles, next_handles)
        else {
            return Ok(None);
        };
        let Some((relation, layout, _)) = state.binding.leaves.get(*leaf) else {
            return Ok(None);
        };
        let mut constraint_keys = Vec::new();
        for (constraint_index, constraint) in state.constraints.iter().enumerate() {
            let Some(current_leaf) = constraint
                .leaves
                .iter()
                .find(|candidate| candidate.leaf == *leaf)
            else {
                continue;
            };
            let Some((equivalence, endpoints)) = state.binding.specs.get(constraint_index) else {
                return Ok(None);
            };
            let columns = endpoints
                .iter()
                .filter(|endpoint| endpoint.leaf == *leaf)
                .map(|endpoint| endpoint.column)
                .collect::<Vec<_>>();
            if columns.is_empty() {
                return Ok(None);
            }
            let mut next_keys = vec![None; next_handles.len()];
            for (old_ordinal, new_ordinal) in old_to_new.iter().copied().enumerate() {
                if let Some(new_ordinal) = new_ordinal {
                    next_keys[new_ordinal].clone_from(&current_leaf.keys[old_ordinal]);
                }
            }
            for new_ordinal in &inserted_ordinals {
                let row_id = next_handles[*new_ordinal];
                let mut row_key = None;
                let mut consistent = true;
                for column in &columns {
                    let binding =
                        SemanticIndexBinding::single(*relation, *layout, *column, *equivalence);
                    let Some(key) =
                        store.semantic_quotient_single_key(&binding, row_id, context, registry)?
                    else {
                        return Ok(None);
                    };
                    if row_key.as_ref().is_some_and(|current| current != &key) {
                        consistent = false;
                        break;
                    }
                    row_key = Some(key);
                }
                next_keys[*new_ordinal] = consistent.then_some(row_key).flatten();
            }
            constraint_keys.push((constraint_index, next_keys));
        }
        patches.push(SemanticQuotientComponentRefreshLeafPatch {
            leaf: *leaf,
            handles: next_handles.clone(),
            constraint_keys,
        });
    }
    Ok(Some(patches))
}

fn leaf_row_by_handle(
    store: &PhysicalStore,
    leaf: &MultiwayJoinLeaf,
    row_id: PhysicalRowId,
) -> Result<kernel_query::Row, PhysicalExecutionError> {
    let installed = store.installed(leaf.relation, leaf.layout)?;
    let position = installed
        .position(row_id)
        .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
    materialize_native_row(&installed.data, position)
}

fn leaf_value_by_handle(
    store: &PhysicalStore,
    leaf: &MultiwayJoinLeaf,
    row_id: PhysicalRowId,
    column: usize,
) -> Result<Value, PhysicalExecutionError> {
    let installed = store.installed(leaf.relation, leaf.layout)?;
    let position = installed
        .position(row_id)
        .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
    match &installed.data {
        NativeRelation::RowStore(rows) => rows
            .get(position)
            .and_then(|row| row.get(column))
            .cloned()
            .ok_or(RelQueryError::ColumnOutOfBounds.into()),
        NativeRelation::Columnar { columns, row_count } => {
            if position >= *row_count {
                return Err(PhysicalExecutionError::ColumnShapeMismatch);
            }
            columns
                .get(column)
                .and_then(|values| values.get(position))
                .cloned()
                .ok_or(RelQueryError::ColumnOutOfBounds.into())
        }
        NativeRelation::I64Columnar { columns, row_count } => {
            if position >= *row_count {
                return Err(PhysicalExecutionError::ColumnShapeMismatch);
            }
            columns
                .get(column)
                .and_then(|values| values.get(position))
                .copied()
                .map(Value::I64)
                .ok_or(RelQueryError::ColumnOutOfBounds.into())
        }
        NativeRelation::TypedColumnar { columns, row_count } => {
            if position >= *row_count {
                return Err(PhysicalExecutionError::ColumnShapeMismatch);
            }
            columns
                .get(column)
                .map(|column| column.value_at(position))
                .ok_or(RelQueryError::ColumnOutOfBounds.into())
        }
    }
}

fn quotient_component_endpoints(
    predicates: &[MultiwayJoinPredicate],
    target: SemanticId,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Vec<Vec<MultiwayJoinColumnRef>>, PhysicalExecutionError> {
    let mut vertices = BTreeSet::new();
    let mut edges = Vec::new();
    for predicate in predicates {
        if registry.equivalence_refines(context, predicate.equivalence, target)? {
            vertices.insert(predicate.left);
            vertices.insert(predicate.right);
            edges.push((predicate.left, predicate.right));
        }
    }
    let mut unseen = vertices;
    let mut components = Vec::new();
    while let Some(start) = unseen.iter().next().copied() {
        unseen.remove(&start);
        let mut stack = vec![start];
        let mut component = BTreeSet::from([start]);
        while let Some(vertex) = stack.pop() {
            for (left, right) in &edges {
                let next = if *left == vertex {
                    Some(*right)
                } else if *right == vertex {
                    Some(*left)
                } else {
                    None
                };
                if let Some(next) = next
                    && component.insert(next)
                {
                    unseen.remove(&next);
                    stack.push(next);
                }
            }
        }
        if component.len() > 1 {
            components.push(component.into_iter().collect());
        }
    }
    Ok(components)
}

fn semantic_quotient_specs(
    predicates: &[MultiwayJoinPredicate],
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Vec<(SemanticId, Vec<MultiwayJoinColumnRef>)>, PhysicalExecutionError> {
    let equivalences = predicates
        .iter()
        .map(|predicate| predicate.equivalence)
        .collect::<BTreeSet<_>>();
    let mut candidates = Vec::new();
    for equivalence in equivalences {
        for endpoints in quotient_component_endpoints(predicates, equivalence, context, registry)? {
            candidates.push((equivalence, endpoints));
        }
    }

    let mut keep = vec![true; candidates.len()];
    for i in 0..candidates.len() {
        for j in 0..candidates.len() {
            if i == j || candidates[i].1 != candidates[j].1 {
                continue;
            }
            let j_refines_i =
                registry.equivalence_refines(context, candidates[j].0, candidates[i].0)?;
            let i_refines_j =
                registry.equivalence_refines(context, candidates[i].0, candidates[j].0)?;
            if j_refines_i && (!i_refines_j || j < i) {
                keep[i] = false;
                break;
            }
        }
    }
    Ok(candidates
        .into_iter()
        .zip(keep)
        .filter_map(|(candidate, keep)| keep.then_some(candidate))
        .collect())
}

fn quotient_hypergraph_search_order(
    leaf_count: usize,
    specs: &[(SemanticId, Vec<MultiwayJoinColumnRef>)],
) -> Option<Vec<usize>> {
    if leaf_count < 3 {
        return None;
    }
    let mut edges = specs
        .iter()
        .map(|(_, endpoints)| {
            endpoints
                .iter()
                .map(|endpoint| endpoint.leaf)
                .collect::<BTreeSet<_>>()
        })
        .filter(|edge| edge.len() > 1)
        .collect::<Vec<_>>();
    let covered = edges
        .iter()
        .flat_map(|edge| edge.iter().copied())
        .collect::<BTreeSet<_>>();
    if covered.len() != leaf_count || covered.iter().copied().ne(0..leaf_count) {
        return None;
    }

    let mut remaining = (0..leaf_count).collect::<BTreeSet<_>>();
    let mut eliminated = Vec::with_capacity(leaf_count);
    while !remaining.is_empty() {
        let mut keep = vec![true; edges.len()];
        for left in 0..edges.len() {
            if !keep[left] {
                continue;
            }
            for right in 0..edges.len() {
                if left == right || !keep[right] {
                    continue;
                }
                let proper_subset =
                    edges[left].len() < edges[right].len() && edges[left].is_subset(&edges[right]);
                let duplicate = left > right && edges[left] == edges[right];
                if proper_subset || duplicate {
                    keep[left] = false;
                    break;
                }
            }
        }
        edges = edges
            .into_iter()
            .zip(keep)
            .filter_map(|(edge, keep)| keep.then_some(edge))
            .collect();

        let mut degree = vec![0_usize; leaf_count];
        for edge in &edges {
            for leaf in edge {
                degree[*leaf] = degree[*leaf].saturating_add(1);
            }
        }
        let leaf = remaining
            .iter()
            .copied()
            .filter(|leaf| degree[*leaf] <= 1)
            .min()?;
        eliminated.push(leaf);
        remaining.remove(&leaf);
        for edge in &mut edges {
            edge.remove(&leaf);
        }
        edges.retain(|edge| !edge.is_empty());
    }
    eliminated.reverse();
    Some(eliminated)
}

fn quotient_hypergraph_cyclic_search_order(
    leaf_count: usize,
    specs: &[(SemanticId, Vec<MultiwayJoinColumnRef>)],
) -> Option<Vec<usize>> {
    if leaf_count < 3 {
        return None;
    }
    let edges = specs
        .iter()
        .map(|(_, endpoints)| {
            endpoints
                .iter()
                .map(|endpoint| endpoint.leaf)
                .collect::<BTreeSet<_>>()
        })
        .filter(|edge| edge.len() > 1)
        .collect::<Vec<_>>();
    let covered = edges
        .iter()
        .flat_map(|edge| edge.iter().copied())
        .collect::<BTreeSet<_>>();
    if covered.len() != leaf_count || covered.iter().copied().ne(0..leaf_count) {
        return None;
    }

    let mut adjacency = vec![BTreeSet::new(); leaf_count];
    for edge in edges {
        let vertices = edge.into_iter().collect::<Vec<_>>();
        for (index, left) in vertices.iter().copied().enumerate() {
            for right in vertices.iter().copied().skip(index + 1) {
                adjacency[left].insert(right);
                adjacency[right].insert(left);
            }
        }
    }

    let mut remaining = (0..leaf_count).collect::<BTreeSet<_>>();
    let mut eliminated = Vec::with_capacity(leaf_count);
    while !remaining.is_empty() {
        let next = remaining
            .iter()
            .copied()
            .map(|leaf| {
                let neighbors = adjacency[leaf]
                    .iter()
                    .copied()
                    .filter(|neighbor| remaining.contains(neighbor))
                    .collect::<Vec<_>>();
                let mut fill = 0_usize;
                for (index, left) in neighbors.iter().copied().enumerate() {
                    for right in neighbors.iter().copied().skip(index + 1) {
                        if !adjacency[left].contains(&right) {
                            fill = fill.saturating_add(1);
                        }
                    }
                }
                (fill, neighbors.len(), leaf, neighbors)
            })
            .min_by_key(|(fill, degree, leaf, _)| (*fill, *degree, *leaf))?;
        let (_, _, leaf, neighbors) = next;
        for (index, left) in neighbors.iter().copied().enumerate() {
            for right in neighbors.iter().copied().skip(index + 1) {
                adjacency[left].insert(right);
                adjacency[right].insert(left);
            }
        }
        remaining.remove(&leaf);
        eliminated.push(leaf);
    }
    eliminated.reverse();
    Some(eliminated)
}

fn flatten_multiway_join_shape(
    plan: &Plan,
    context: &kernel_schema::SemanticContext,
    leaf_count: &mut usize,
    predicates: &mut Vec<MultiwayJoinPredicate>,
) -> Result<Option<Vec<MultiwayJoinColumnRef>>, RelQueryError> {
    match plan {
        Plan::Scan {
            relation,
            algorithm: ScanAlgorithm::FullScan,
            ..
        } => {
            let definition = context
                .schema
                .relation(*relation)
                .ok_or(RelQueryError::UnknownRelation(*relation))?;
            let leaf = *leaf_count;
            *leaf_count = leaf.saturating_add(1);
            Ok(Some(
                (0..definition.columns.len())
                    .map(|column| MultiwayJoinColumnRef { leaf, column })
                    .collect(),
            ))
        }
        Plan::JoinEq {
            left,
            right,
            left_column,
            right_column,
            equivalence,
            ..
        } => {
            let Some(mut left_columns) =
                flatten_multiway_join_shape(left, context, leaf_count, predicates)?
            else {
                return Ok(None);
            };
            let Some(right_columns) =
                flatten_multiway_join_shape(right, context, leaf_count, predicates)?
            else {
                return Ok(None);
            };
            let left_ref = left_columns
                .get(*left_column)
                .copied()
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            let right_ref = right_columns
                .get(*right_column)
                .copied()
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            predicates.push(MultiwayJoinPredicate {
                left: left_ref,
                right: right_ref,
                equivalence: *equivalence,
            });
            left_columns.extend(right_columns);
            Ok(Some(left_columns))
        }
        Plan::FilterEqColumns {
            input,
            left_column,
            right_column,
            equivalence,
        } => {
            let Some(columns) =
                flatten_multiway_join_shape(input, context, leaf_count, predicates)?
            else {
                return Ok(None);
            };
            let left_ref = columns
                .get(*left_column)
                .copied()
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            let right_ref = columns
                .get(*right_column)
                .copied()
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            if left_ref.leaf == right_ref.leaf {
                return Ok(None);
            }
            predicates.push(MultiwayJoinPredicate {
                left: left_ref,
                right: right_ref,
                equivalence: *equivalence,
            });
            Ok(Some(columns))
        }
        _ => Ok(None),
    }
}

fn prepare_semantic_quotient_program(
    plan: &Plan,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<PreparedSemanticQuotientProgram>, RelQueryError> {
    if !matches!(plan, Plan::JoinEq { .. } | Plan::FilterEqColumns { .. }) {
        return Ok(None);
    }
    let mut leaf_count = 0;
    let mut predicates = Vec::new();
    let Some(_) = flatten_multiway_join_shape(plan, context, &mut leaf_count, &mut predicates)?
    else {
        return Ok(None);
    };
    if leaf_count < 3 {
        return Ok(None);
    }
    let specs =
        semantic_quotient_specs(&predicates, context, registry).map_err(|error| match error {
            PhysicalExecutionError::Query(query) => query,
            _ => RelQueryError::InconsistentIncrementalDelta,
        })?;
    let gyo_order = quotient_hypergraph_search_order(leaf_count, &specs);
    let (hypergraph_order, search_certificate) = if let Some(order) = gyo_order {
        (
            Some(order),
            Some(SemanticQuotientSearchCertificate::GyoAcyclic),
        )
    } else if leaf_count > 8 {
        (
            quotient_hypergraph_cyclic_search_order(leaf_count, &specs),
            Some(SemanticQuotientSearchCertificate::BoundedCyclic),
        )
    } else {
        (None, None)
    };
    if leaf_count > 8 && hypergraph_order.is_none() {
        return Ok(None);
    }
    Ok(Some(PreparedSemanticQuotientProgram {
        specs,
        hypergraph_order,
        search_certificate,
    }))
}

fn prepare_anchor_pullback_program(
    plan: &Plan,
    context: &kernel_schema::SemanticContext,
) -> Result<Option<PreparedAnchorPullbackProgram>, RelQueryError> {
    if !matches!(plan, Plan::JoinEq { .. } | Plan::FilterEqColumns { .. }) {
        return Ok(None);
    }
    let mut leaf_count = 0;
    let mut predicates = Vec::new();
    let Some(_) = flatten_multiway_join_shape(plan, context, &mut leaf_count, &mut predicates)?
    else {
        return Ok(None);
    };
    if leaf_count < 3 || predicates.is_empty() {
        return Ok(None);
    }
    Ok(Some(PreparedAnchorPullbackProgram {
        leaf_count,
        predicates,
    }))
}

#[derive(Debug)]
struct AnchorPullbackLeafRuntime {
    coordinates: Vec<RevisionObservableId>,
    tuples: Vec<Vec<EqClassId>>,
    rows_by_tuple: BTreeMap<Vec<EqClassId>, Vec<(usize, kernel_query::Row)>>,
    coordinate_indexes: Vec<BTreeMap<EqClassId, Vec<usize>>>,
}

impl AnchorPullbackLeafRuntime {
    fn candidate_tuple_indices(
        &self,
        assignments: &BTreeMap<RevisionObservableId, EqClassId>,
    ) -> Vec<usize> {
        let mut seed: Option<&Vec<usize>> = None;
        for (position, coordinate) in self.coordinates.iter().enumerate() {
            let Some(class) = assignments.get(coordinate) else {
                continue;
            };
            let Some(indices) = self.coordinate_indexes[position].get(class) else {
                return Vec::new();
            };
            if seed.is_none_or(|current| indices.len() < current.len()) {
                seed = Some(indices);
            }
        }
        seed.cloned()
            .unwrap_or_else(|| (0..self.tuples.len()).collect())
    }

    fn tuple_compatible(
        &self,
        tuple_index: usize,
        assignments: &BTreeMap<RevisionObservableId, EqClassId>,
    ) -> bool {
        self.coordinates
            .iter()
            .zip(&self.tuples[tuple_index])
            .all(|(coordinate, class)| {
                assignments
                    .get(coordinate)
                    .is_none_or(|assigned| assigned == class)
            })
    }
}

struct AnchorPullbackExecution<'a> {
    factors: &'a [AnchorPullbackLeafRuntime],
    search_order: &'a [usize],
    stats: &'a mut ExecutionStats,
    assignments: BTreeMap<RevisionObservableId, EqClassId>,
    selected: Vec<Option<usize>>,
    matches: Vec<(Vec<usize>, kernel_query::Row)>,
}

impl AnchorPullbackExecution<'_> {
    fn run(mut self) -> Vec<(Vec<usize>, kernel_query::Row)> {
        self.search(0);
        self.matches
    }

    fn search(&mut self, depth: usize) {
        if depth == self.search_order.len() {
            self.expand_selected_rows(0, &mut Vec::new(), &mut Vec::new());
            return;
        }
        let leaf = self.search_order[depth];
        let candidates = self.factors[leaf].candidate_tuple_indices(&self.assignments);
        for tuple_index in candidates {
            self.stats.multiway_join_apnf_candidate_visits = self
                .stats
                .multiway_join_apnf_candidate_visits
                .saturating_add(1);
            if !self.factors[leaf].tuple_compatible(tuple_index, &self.assignments) {
                continue;
            }
            let mut inserted = Vec::new();
            for (&coordinate, &class) in self.factors[leaf]
                .coordinates
                .iter()
                .zip(&self.factors[leaf].tuples[tuple_index])
            {
                if let std::collections::btree_map::Entry::Vacant(entry) =
                    self.assignments.entry(coordinate)
                {
                    entry.insert(class);
                    inserted.push(coordinate);
                }
            }
            self.selected[leaf] = Some(tuple_index);
            self.search(depth + 1);
            self.selected[leaf] = None;
            for coordinate in inserted {
                self.assignments.remove(&coordinate);
            }
        }
    }

    fn expand_selected_rows(
        &mut self,
        leaf: usize,
        ordinals: &mut Vec<usize>,
        row: &mut kernel_query::Row,
    ) {
        if leaf == self.factors.len() {
            self.matches.push((ordinals.clone(), row.clone()));
            return;
        }
        let tuple_index = self.selected[leaf].expect("all APNF factors are selected");
        let tuple = &self.factors[leaf].tuples[tuple_index];
        let bucket = self.factors[leaf]
            .rows_by_tuple
            .get(tuple)
            .expect("APNF reconstructed tuple has a physical row bucket");
        for (ordinal, physical_row) in bucket {
            ordinals.push(*ordinal);
            let original_len = row.len();
            row.extend(physical_row.iter().cloned());
            self.expand_selected_rows(leaf + 1, ordinals, row);
            row.truncate(original_len);
            ordinals.pop();
        }
    }
}

type AnchorPullbackRowBuckets = BTreeMap<Vec<EqClassId>, Vec<(usize, kernel_query::Row)>>;

struct AnchorPullbackFactorBuild {
    measure: kernel_semantics::anchor_pullback::RevisionFiniteMeasure,
    rows_by_tuple: AnchorPullbackRowBuckets,
}

struct AnchorPullbackFactorBuilder<'a> {
    predicates: &'a [MultiwayJoinPredicate],
    predicate_observables: &'a [RevisionObservableId],
    catalog: &'a mut kernel_semantics::observable::RevisionObservableCatalog,
    store: &'a PhysicalStore,
    context: &'a kernel_schema::SemanticContext,
    registry: &'a kernel_semantics::SemanticRegistry,
    stats: &'a mut ExecutionStats,
}

impl AnchorPullbackFactorBuilder<'_> {
    fn build(
        &mut self,
        leaf_index: usize,
        leaf: &MultiwayJoinLeaf,
    ) -> Result<AnchorPullbackFactorBuild, PhysicalExecutionError> {
        let incidence = self.incidence(leaf_index);
        let coordinates = incidence
            .keys()
            .map(|index| self.predicate_observables[*index])
            .collect::<Vec<_>>();
        let handles = self.store.logical_row_handles(leaf.relation, leaf.layout)?;
        let installed = self.store.installed(leaf.relation, leaf.layout)?;
        let mut rows_by_tuple = AnchorPullbackRowBuckets::new();
        for (ordinal, handle) in handles.iter().enumerate() {
            let position = installed
                .position(*handle)
                .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
            let row = materialize_native_row(&installed.data, position)?;
            self.stats.scanned_rows = self.stats.scanned_rows.saturating_add(1);
            if let Some(tuple) = self.observe_tuple(&row, &incidence)? {
                rows_by_tuple.entry(tuple).or_default().push((ordinal, row));
            }
        }
        let measure_rows = rows_by_tuple
            .iter()
            .map(|(tuple, rows)| {
                u64::try_from(rows.len())
                    .map(|weight| (tuple.clone(), weight))
                    .map_err(|_| PhysicalExecutionError::AnchorPullbackInvariant)
            })
            .collect::<Result<Vec<_>, _>>()?;
        let measure = kernel_semantics::anchor_pullback::RevisionFiniteMeasure::new(
            self.catalog,
            coordinates,
            measure_rows,
        )
        .map_err(|_| PhysicalExecutionError::AnchorPullbackInvariant)?;
        Ok(AnchorPullbackFactorBuild {
            measure,
            rows_by_tuple,
        })
    }

    fn incidence(&self, leaf_index: usize) -> BTreeMap<usize, Vec<usize>> {
        let mut incidence = BTreeMap::<usize, Vec<usize>>::new();
        for (predicate_index, predicate) in self.predicates.iter().enumerate() {
            if predicate.left.leaf == leaf_index {
                incidence
                    .entry(predicate_index)
                    .or_default()
                    .push(predicate.left.column);
            }
            if predicate.right.leaf == leaf_index {
                incidence
                    .entry(predicate_index)
                    .or_default()
                    .push(predicate.right.column);
            }
        }
        incidence
    }

    fn observe_tuple(
        &mut self,
        row: &kernel_query::Row,
        incidence: &BTreeMap<usize, Vec<usize>>,
    ) -> Result<Option<Vec<EqClassId>>, PhysicalExecutionError> {
        let mut tuple = Vec::with_capacity(incidence.len());
        for (&predicate_index, columns) in incidence {
            let observable = self.predicate_observables[predicate_index];
            let mut expected = None;
            for column in columns {
                let value = row.get(*column).ok_or(RelQueryError::ColumnOutOfBounds)?;
                self.stats.values_read = self.stats.values_read.saturating_add(1);
                let class = self
                    .catalog
                    .observe_value(self.registry, self.context, observable, value)
                    .map_err(|_| PhysicalExecutionError::AnchorPullbackInvariant)?;
                if expected.is_some_and(|candidate| candidate != class) {
                    return Ok(None);
                }
                expected = Some(class);
            }
            tuple.push(expected.ok_or(PhysicalExecutionError::AnchorPullbackInvariant)?);
        }
        Ok(Some(tuple))
    }
}

fn register_anchor_pullback_observables(
    predicates: &[MultiwayJoinPredicate],
    catalog: &mut kernel_semantics::observable::RevisionObservableCatalog,
    registry: &kernel_semantics::SemanticRegistry,
    context: &kernel_schema::SemanticContext,
) -> Result<Vec<RevisionObservableId>, PhysicalExecutionError> {
    predicates
        .iter()
        .enumerate()
        .map(|(index, predicate)| {
            let coordinate = u64::try_from(index)
                .ok()
                .and_then(|value| value.checked_add(1))
                .ok_or(PhysicalExecutionError::AnchorPullbackInvariant)?;
            catalog
                .register_equivalence_coordinate(
                    registry,
                    context,
                    predicate.equivalence,
                    coordinate,
                )
                .map_err(|_| PhysicalExecutionError::AnchorPullbackInvariant)
        })
        .collect()
}

fn anchor_pullback_runtime_factors(
    normal_form: &kernel_semantics::anchor_pullback::AnchorPullbackNormalForm,
    row_buckets: Vec<AnchorPullbackRowBuckets>,
) -> Result<Vec<AnchorPullbackLeafRuntime>, PhysicalExecutionError> {
    normal_form
        .anchors()
        .iter()
        .zip(row_buckets)
        .map(|(anchor, rows_by_tuple)| {
            let reconstructed = anchor.reconstructed_measure();
            for (tuple, weight) in &reconstructed {
                let actual = rows_by_tuple.get(tuple).map_or(0, Vec::len);
                if u64::try_from(actual).ok() != Some(*weight) {
                    return Err(PhysicalExecutionError::AnchorPullbackInvariant);
                }
            }
            let tuples = reconstructed.keys().cloned().collect::<Vec<_>>();
            let mut coordinate_indexes = anchor
                .coordinates()
                .iter()
                .map(|_| BTreeMap::<EqClassId, Vec<usize>>::new())
                .collect::<Vec<_>>();
            for (tuple_index, tuple) in tuples.iter().enumerate() {
                for (position, class) in tuple.iter().copied().enumerate() {
                    coordinate_indexes[position]
                        .entry(class)
                        .or_default()
                        .push(tuple_index);
                }
            }
            Ok(AnchorPullbackLeafRuntime {
                coordinates: anchor.coordinates().to_vec(),
                tuples,
                rows_by_tuple,
                coordinate_indexes,
            })
        })
        .collect()
}

fn anchor_pullback_search_order(
    normal_form: &kernel_semantics::anchor_pullback::AnchorPullbackNormalForm,
    factors: &[AnchorPullbackLeafRuntime],
) -> Result<(Vec<usize>, bool), PhysicalExecutionError> {
    let mut branch_free = Vec::new();
    for index in 0..factors.len() {
        if normal_form
            .branch_free_from_anchor(index)
            .map_err(|_| PhysicalExecutionError::AnchorPullbackInvariant)?
            .is_some()
        {
            branch_free.push(index);
        }
    }
    let mut search_order = (0..factors.len()).collect::<Vec<_>>();
    search_order.sort_by_key(|index| {
        (
            !branch_free.contains(index),
            factors[*index].tuples.len(),
            *index,
        )
    });
    Ok((search_order, !branch_free.is_empty()))
}

fn try_execute_anchor_pullback_join(
    plan: &Plan,
    program: &PreparedAnchorPullbackProgram,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let mut leaves = Vec::new();
    let mut predicates = Vec::new();
    let Some(_) = flatten_multiway_join_tree(plan, store, &mut leaves, &mut predicates)? else {
        return Ok(None);
    };
    if leaves.len() != program.leaf_count || predicates != program.predicates {
        return Err(PhysicalExecutionError::AnchorPullbackInvariant);
    }

    let mut catalog = kernel_semantics::observable::RevisionObservableCatalog::new(context)
        .map_err(|_| PhysicalExecutionError::AnchorPullbackInvariant)?;
    let predicate_observables =
        register_anchor_pullback_observables(&predicates, &mut catalog, registry, context)?;
    let mut finite_factors = Vec::with_capacity(leaves.len());
    let mut row_buckets = Vec::with_capacity(leaves.len());
    {
        let mut builder = AnchorPullbackFactorBuilder {
            predicates: &predicates,
            predicate_observables: &predicate_observables,
            catalog: &mut catalog,
            store,
            context,
            registry,
            stats,
        };
        for (leaf_index, leaf) in leaves.iter().enumerate() {
            let built = builder.build(leaf_index, leaf)?;
            finite_factors.push(built.measure);
            row_buckets.push(built.rows_by_tuple);
        }
    }
    let normal_form = kernel_semantics::anchor_pullback::AnchorPullbackNormalForm::new(
        &catalog,
        finite_factors,
        Vec::new(),
        predicate_observables,
    )
    .map_err(|_| PhysicalExecutionError::AnchorPullbackInvariant)?;
    let factors = anchor_pullback_runtime_factors(&normal_form, row_buckets)?;
    let (search_order, has_branch_free) = anchor_pullback_search_order(&normal_form, &factors)?;
    if has_branch_free {
        stats.multiway_join_apnf_branch_free =
            stats.multiway_join_apnf_branch_free.saturating_add(1);
    }
    let mut matches = AnchorPullbackExecution {
        factors: &factors,
        search_order: &search_order,
        stats,
        assignments: BTreeMap::new(),
        selected: vec![None; factors.len()],
        matches: Vec::new(),
    }
    .run();
    matches.sort_by(|left, right| left.0.cmp(&right.0));
    stats.multiway_join_apnf_executions = stats.multiway_join_apnf_executions.saturating_add(1);
    Ok(Some(matches.into_iter().map(|(_, row)| row).collect()))
}

fn quotient_key_cache(
    specs: &[(SemanticId, Vec<MultiwayJoinColumnRef>)],
    leaves: &[MultiwayJoinLeaf],
    handles: &[Vec<PhysicalRowId>],
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<SemanticQuotientKeyCache>, PhysicalExecutionError> {
    let mut cache = BTreeMap::new();
    for (equivalence, endpoints) in specs {
        if context
            .schema
            .structural_equivalence(*equivalence)
            .is_some()
        {
            registry.equivalence_domain(context, *equivalence)?;
        } else if registry
            .resolve_primitive_equivalence(context, *equivalence)?
            .is_none()
        {
            return Ok(None);
        }
        for endpoint in endpoints {
            let cache_key = (endpoint.leaf, endpoint.column, *equivalence);
            if cache.contains_key(&cache_key) {
                continue;
            }
            let factor_binding = SemanticIndexBinding::single(
                leaves[endpoint.leaf].relation,
                leaves[endpoint.leaf].layout,
                endpoint.column,
                *equivalence,
            );
            let maintained_factor =
                store.has_semantic_quotient_capability(&factor_binding, context, registry)?;
            let mut keys = Vec::with_capacity(handles[endpoint.leaf].len());
            for row_id in &handles[endpoint.leaf] {
                if maintained_factor
                    && let Some(key) = store.semantic_quotient_single_key(
                        &factor_binding,
                        *row_id,
                        context,
                        registry,
                    )?
                {
                    keys.push(key);
                    stats.multiway_join_maintained_quotient_key_hits = stats
                        .multiway_join_maintained_quotient_key_hits
                        .saturating_add(1);
                    continue;
                }
                let value =
                    leaf_value_by_handle(store, &leaves[endpoint.leaf], *row_id, endpoint.column)?;
                keys.push(registry.canonical_equivalence_key(context, *equivalence, &value)?);
                stats.values_read = stats.values_read.saturating_add(1);
            }
            cache.insert(cache_key, keys);
        }
    }
    Ok(Some(cache))
}

fn quotient_leaf_keys(
    leaf_index: usize,
    columns: &[usize],
    equivalence: SemanticId,
    row_count: usize,
    key_cache: &BTreeMap<(usize, usize, SemanticId), Vec<kernel_semantics::CanonicalEqKey>>,
) -> Result<SemanticQuotientLeaf, PhysicalExecutionError> {
    let mut keys = Vec::with_capacity(row_count);
    for ordinal in 0..row_count {
        let mut row_key = None;
        let mut consistent = true;
        for column in columns {
            let key = key_cache
                .get(&(leaf_index, *column, equivalence))
                .and_then(|keys| keys.get(ordinal))
                .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
            if row_key.as_ref().is_some_and(|current| current != key) {
                consistent = false;
                break;
            }
            row_key = Some(key.clone());
        }
        keys.push(consistent.then_some(row_key).flatten());
    }
    let mut buckets = BTreeMap::new();
    let mut live_rows_by_key = BTreeMap::new();
    for (ordinal, key) in keys.iter().enumerate() {
        let Some(key) = key else { continue };
        *live_rows_by_key.entry(key.clone()).or_insert(0) += 1;
        let mask = buckets
            .entry(key.clone())
            .or_insert_with(|| vec![0_u64; keys.len().div_ceil(64)]);
        mask[ordinal / 64] |= 1_u64 << (ordinal % 64);
    }
    Ok(SemanticQuotientLeaf {
        leaf: leaf_index,
        keys,
        buckets,
        live_rows_by_key,
    })
}

fn quotient_key_leaf_support(
    leaves: &[SemanticQuotientLeaf],
) -> BTreeMap<kernel_semantics::CanonicalEqKey, usize> {
    let mut support = BTreeMap::new();
    for leaf in leaves {
        for key in leaf.buckets.keys() {
            *support.entry(key.clone()).or_insert(0) += 1;
        }
    }
    support
}

struct SemanticQuotientBuildContext<'a> {
    leaves: &'a [MultiwayJoinLeaf],
    predicates: &'a [MultiwayJoinPredicate],
    handles: &'a [Vec<PhysicalRowId>],
    store: &'a PhysicalStore,
    context: &'a kernel_schema::SemanticContext,
    registry: &'a kernel_semantics::SemanticRegistry,
}

fn build_semantic_quotient_constraints(
    build: &SemanticQuotientBuildContext<'_>,
    prepared_specs: Option<&[(SemanticId, Vec<MultiwayJoinColumnRef>)]>,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<SemanticQuotientConstraint>>, PhysicalExecutionError> {
    let owned_specs;
    let specs = if let Some(prepared) = prepared_specs {
        prepared
    } else {
        owned_specs = semantic_quotient_specs(build.predicates, build.context, build.registry)?;
        &owned_specs
    };
    let Some(key_cache) = quotient_key_cache(
        specs,
        build.leaves,
        build.handles,
        build.store,
        build.context,
        build.registry,
        stats,
    )?
    else {
        return Ok(None);
    };
    let mut constraints = Vec::with_capacity(specs.len());
    for (equivalence, endpoints) in specs {
        let mut columns_by_leaf = BTreeMap::<usize, Vec<usize>>::new();
        for endpoint in endpoints {
            columns_by_leaf
                .entry(endpoint.leaf)
                .or_default()
                .push(endpoint.column);
        }
        let mut quotient_leaves = Vec::with_capacity(columns_by_leaf.len());
        for (leaf, columns) in columns_by_leaf {
            quotient_leaves.push(quotient_leaf_keys(
                leaf,
                &columns,
                *equivalence,
                build.handles[leaf].len(),
                &key_cache,
            )?);
        }
        let key_leaf_support = quotient_key_leaf_support(&quotient_leaves);
        constraints.push(SemanticQuotientConstraint {
            leaves: quotient_leaves,
            live_key_leaf_support: key_leaf_support.clone(),
            key_leaf_support,
        });
    }
    Ok(Some(constraints))
}

fn quotient_support_masks(
    handles: &[Vec<PhysicalRowId>],
    constraints: &mut [SemanticQuotientConstraint],
) -> Vec<Vec<u64>> {
    let mut offsets = Vec::with_capacity(handles.len());
    let mut atom_count = 0_usize;
    for rows in handles {
        offsets.push(atom_count);
        atom_count = atom_count.saturating_add(rows.len());
    }
    let atom = |leaf: usize, ordinal: usize| {
        kernel_grounded_closure::GroundedAtomId::new(offsets[leaf].saturating_add(ordinal))
    };
    let mut unavailable = BTreeSet::new();
    let mut requirements = Vec::new();
    for constraint in constraints.iter() {
        for quotient_leaf in &constraint.leaves {
            for (ordinal, key) in quotient_leaf.keys.iter().enumerate() {
                let dependent = atom(quotient_leaf.leaf, ordinal);
                let Some(key) = key else {
                    unavailable.insert(dependent);
                    continue;
                };
                for supporter_leaf in &constraint.leaves {
                    if supporter_leaf.leaf == quotient_leaf.leaf {
                        continue;
                    }
                    let supporters = supporter_leaf
                        .keys
                        .iter()
                        .enumerate()
                        .filter_map(|(supporter_ordinal, supporter_key)| {
                            (supporter_key.as_ref() == Some(key))
                                .then_some(atom(supporter_leaf.leaf, supporter_ordinal))
                        })
                        .collect::<Vec<_>>();
                    requirements.push(kernel_grounded_closure::BipolarSupportRequirement::new(
                        dependent, supporters,
                    ));
                }
            }
        }
    }
    let program =
        kernel_grounded_closure::BipolarSupportProgram::new(atom_count, unavailable, requirements)
            .expect("QCN row/support atoms are compiled inside the dense universe");
    let (certificate, _) = kernel_grounded_closure::solve_bipolar_support(&program)
        .expect("compiled QCN death program has a valid grounded certificate");
    let masks = handles
        .iter()
        .enumerate()
        .map(|(leaf, rows)| {
            let mut mask = vec![0_u64; rows.len().div_ceil(64)];
            for ordinal in 0..rows.len() {
                if certificate.is_supported(atom(leaf, ordinal)) {
                    mask[ordinal / 64] |= 1_u64 << (ordinal % 64);
                }
            }
            mask
        })
        .collect::<Vec<_>>();
    for constraint in constraints.iter_mut() {
        reset_constraint_live_support(constraint, &masks);
    }
    masks
}

fn semantic_quotient_initial_bfc_atoms(
    handles: &[Vec<PhysicalRowId>],
) -> (
    Vec<BTreeMap<PhysicalRowId, kernel_grounded_closure::GroundedAtomId>>,
    usize,
) {
    let mut atom_count = 0_usize;
    let atoms_by_handle = handles
        .iter()
        .map(|rows| {
            rows.iter()
                .copied()
                .map(|handle| {
                    let atom = kernel_grounded_closure::GroundedAtomId::new(atom_count);
                    atom_count = atom_count.saturating_add(1);
                    (handle, atom)
                })
                .collect::<BTreeMap<_, _>>()
        })
        .collect();
    (atoms_by_handle, atom_count)
}

fn semantic_quotient_atom_for_handle(
    atoms_by_handle: &[BTreeMap<PhysicalRowId, kernel_grounded_closure::GroundedAtomId>],
    leaf: usize,
    handle: PhysicalRowId,
) -> Result<kernel_grounded_closure::GroundedAtomId, PhysicalExecutionError> {
    atoms_by_handle
        .get(leaf)
        .and_then(|atoms| atoms.get(&handle))
        .copied()
        .ok_or(RelQueryError::InconsistentIncrementalDelta.into())
}

fn compile_semantic_quotient_bfc_program(
    handles: &[Vec<PhysicalRowId>],
    constraints: &[SemanticQuotientConstraint],
    atoms_by_handle: &[BTreeMap<PhysicalRowId, kernel_grounded_closure::GroundedAtomId>],
    atom_count: usize,
) -> Result<kernel_grounded_closure::BipolarSupportProgram, PhysicalExecutionError> {
    if handles.len() != atoms_by_handle.len() {
        return Err(RelQueryError::InconsistentIncrementalDelta.into());
    }
    let mut active = vec![false; atom_count];
    for (leaf, rows) in handles.iter().enumerate() {
        for handle in rows {
            let atom = semantic_quotient_atom_for_handle(atoms_by_handle, leaf, *handle)?;
            let Some(slot) = active.get_mut(atom.index()) else {
                return Err(RelQueryError::InconsistentIncrementalDelta.into());
            };
            *slot = true;
        }
    }
    let mut unavailable = active
        .iter()
        .enumerate()
        .filter_map(|(index, is_active)| {
            (!*is_active).then_some(kernel_grounded_closure::GroundedAtomId::new(index))
        })
        .collect::<BTreeSet<_>>();
    let mut requirements = Vec::new();
    for constraint in constraints {
        for quotient_leaf in &constraint.leaves {
            let dependent_handles = handles
                .get(quotient_leaf.leaf)
                .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
            if dependent_handles.len() != quotient_leaf.keys.len() {
                return Err(RelQueryError::InconsistentIncrementalDelta.into());
            }
            for (ordinal, key) in quotient_leaf.keys.iter().enumerate() {
                let dependent = semantic_quotient_atom_for_handle(
                    atoms_by_handle,
                    quotient_leaf.leaf,
                    dependent_handles[ordinal],
                )?;
                let Some(key) = key else {
                    unavailable.insert(dependent);
                    continue;
                };
                for supporter_leaf in &constraint.leaves {
                    if supporter_leaf.leaf == quotient_leaf.leaf {
                        continue;
                    }
                    let supporter_handles = handles
                        .get(supporter_leaf.leaf)
                        .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
                    if supporter_handles.len() != supporter_leaf.keys.len() {
                        return Err(RelQueryError::InconsistentIncrementalDelta.into());
                    }
                    let supporters = supporter_leaf
                        .keys
                        .iter()
                        .enumerate()
                        .filter_map(|(supporter_ordinal, supporter_key)| {
                            (supporter_key.as_ref() == Some(key))
                                .then_some(supporter_handles[supporter_ordinal])
                        })
                        .map(|handle| {
                            semantic_quotient_atom_for_handle(
                                atoms_by_handle,
                                supporter_leaf.leaf,
                                handle,
                            )
                        })
                        .collect::<Result<Vec<_>, _>>()?;
                    requirements.push(kernel_grounded_closure::BipolarSupportRequirement::new(
                        dependent, supporters,
                    ));
                }
            }
        }
    }
    kernel_grounded_closure::BipolarSupportProgram::new(atom_count, unavailable, requirements)
        .map_err(|_| RelQueryError::InconsistentIncrementalDelta.into())
}

fn semantic_quotient_masks_from_bfc(
    handles: &[Vec<PhysicalRowId>],
    atoms_by_handle: &[BTreeMap<PhysicalRowId, kernel_grounded_closure::GroundedAtomId>],
    certificate: &kernel_grounded_closure::BipolarSupportCertificate,
) -> Result<Vec<Vec<u64>>, PhysicalExecutionError> {
    handles
        .iter()
        .enumerate()
        .map(|(leaf, rows)| {
            let mut mask = vec![0_u64; rows.len().div_ceil(64)];
            for (ordinal, handle) in rows.iter().copied().enumerate() {
                let atom = semantic_quotient_atom_for_handle(atoms_by_handle, leaf, handle)?;
                if certificate.is_supported(atom) {
                    mask[ordinal / 64] |= 1_u64 << (ordinal % 64);
                }
            }
            Ok(mask)
        })
        .collect()
}

#[cfg(test)]
fn quotient_support_masks_legacy(
    handles: &[Vec<PhysicalRowId>],
    constraints: &mut [SemanticQuotientConstraint],
) -> Vec<Vec<u64>> {
    let mut masks = handles
        .iter()
        .map(|rows| full_ordinal_mask(rows.len()))
        .collect::<Vec<_>>();
    for constraint in constraints.iter_mut() {
        reset_constraint_live_support(constraint, &masks);
    }
    let changed_leaves = (0..handles.len()).collect::<Vec<_>>();
    propagate_quotient_support_deletions(handles, constraints, &mut masks, &changed_leaves);
    masks
}

fn semantic_quotient_support_binding(
    leaves: &[MultiwayJoinLeaf],
    program: &PreparedSemanticQuotientProgram,
) -> SemanticQuotientSupportBinding {
    SemanticQuotientSupportBinding {
        leaves: leaves
            .iter()
            .map(|leaf| (leaf.relation, leaf.layout, leaf.width))
            .collect(),
        specs: program.specs.clone(),
    }
}

fn prepared_quotient_acceleration_available(
    plan: &Plan,
    program: &PreparedSemanticQuotientProgram,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<bool, PhysicalExecutionError> {
    let mut leaves = Vec::new();
    let mut predicates = Vec::new();
    let Some(_) = flatten_multiway_join_tree(plan, store, &mut leaves, &mut predicates)? else {
        return Ok(false);
    };
    let support_binding = semantic_quotient_support_binding(&leaves, program);
    if store.semantic_quotient_support(&support_binding).is_some() {
        return Ok(true);
    }
    for (equivalence, endpoints) in &program.specs {
        for endpoint in endpoints {
            let Some(leaf) = leaves.get(endpoint.leaf) else {
                return Err(RelQueryError::InconsistentIncrementalDelta.into());
            };
            let binding = SemanticIndexBinding::single(
                leaf.relation,
                leaf.layout,
                endpoint.column,
                *equivalence,
            );
            if store.has_semantic_quotient_capability(&binding, context, registry)? {
                return Ok(true);
            }
        }
    }
    Ok(false)
}

fn semantic_quotient_support_leaves(
    binding: &SemanticQuotientSupportBinding,
    store: &PhysicalStore,
) -> Result<Vec<MultiwayJoinLeaf>, PhysicalExecutionError> {
    binding
        .leaves
        .iter()
        .map(|(relation, layout, width)| {
            let rows = store.logical_row_handles(*relation, *layout)?.len();
            Ok(MultiwayJoinLeaf {
                plan: Plan::Scan {
                    relation: *relation,
                    layout: *layout,
                    algorithm: ScanAlgorithm::FullScan,
                },
                relation: *relation,
                layout: *layout,
                width: *width,
                rows,
            })
        })
        .collect()
}

fn build_semantic_quotient_support_state(
    binding: SemanticQuotientSupportBinding,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<MaterializedSemanticQuotientSupportState>, PhysicalExecutionError> {
    let dependencies = semantic_key_dependencies_for_equivalences(
        binding.specs.iter().map(|(equivalence, _)| *equivalence),
        context,
        registry,
    )?;
    let structural_definitions = semantic_key_structural_definitions_for_equivalences(
        binding.specs.iter().map(|(equivalence, _)| *equivalence),
        context,
        registry,
    )?;
    let key_binding = kernel_semantic_index::SemanticIndexBinding::new_with_structural_definitions(
        context,
        dependencies,
        structural_definitions,
    );
    let leaves = semantic_quotient_support_leaves(&binding, store)?;
    let handles = leaves
        .iter()
        .map(|leaf| store.logical_row_handles(leaf.relation, leaf.layout))
        .collect::<Result<Vec<_>, _>>()?;
    let mut stats = ExecutionStats::default();
    let build = SemanticQuotientBuildContext {
        leaves: &leaves,
        predicates: &[],
        handles: &handles,
        store,
        context,
        registry,
    };
    let Some(mut constraints) =
        build_semantic_quotient_constraints(&build, Some(binding.specs.as_slice()), &mut stats)?
    else {
        return Ok(None);
    };
    let (atoms_by_handle, atom_count) = semantic_quotient_initial_bfc_atoms(&handles);
    let bfc_program = compile_semantic_quotient_bfc_program(
        &handles,
        &constraints,
        &atoms_by_handle,
        atom_count,
    )?;
    let (bfc_certificate, bfc_work) = kernel_grounded_closure::solve_bipolar_support(&bfc_program)
        .map_err(|_| RelQueryError::InconsistentIncrementalDelta)?;
    let base_masks =
        semantic_quotient_masks_from_bfc(&handles, &atoms_by_handle, &bfc_certificate)?;
    for constraint in &mut constraints {
        reset_constraint_live_support(constraint, &base_masks);
    }
    Ok(Some(MaterializedSemanticQuotientSupportState {
        binding,
        key_binding,
        handles,
        constraints,
        base_masks,
        bfc: SemanticQuotientBfcMaintenance {
            atoms_by_handle,
            program: bfc_program,
            certificate: bfc_certificate,
            last_work: bfc_work,
        },
    }))
}

fn quotient_leaf(
    constraint: &SemanticQuotientConstraint,
    leaf: usize,
) -> Option<&SemanticQuotientLeaf> {
    constraint
        .leaves
        .iter()
        .find(|candidate| candidate.leaf == leaf)
}

#[derive(Debug, Clone)]
struct CyclicPrefixCandidateIndex {
    constraint_indices: Vec<usize>,
    buckets: BTreeMap<Vec<kernel_semantics::CanonicalEqKey>, Vec<usize>>,
    max_bucket_len: usize,
}

#[derive(Debug, Clone)]
struct CyclicPrefixCandidateIndexes {
    by_leaf: Vec<Option<CyclicPrefixCandidateIndex>>,
    build_work_upper_bound: u128,
}

struct OrderPreservingJoinEnumeration<'a> {
    handles: &'a [Vec<PhysicalRowId>],
    constraints: &'a [SemanticQuotientConstraint],
    base_masks: &'a [Vec<u64>],
    search_order: &'a [usize],
    cyclic_prefix_indexes: Option<&'a CyclicPrefixCandidateIndexes>,
}

fn mask_ordinals(mask: &[u64]) -> impl Iterator<Item = usize> + '_ {
    mask.iter().enumerate().flat_map(|(word_index, word)| {
        let mut remaining = *word;
        std::iter::from_fn(move || {
            if remaining == 0 {
                return None;
            }
            let bit = remaining.trailing_zeros() as usize;
            remaining &= remaining - 1;
            Some(word_index * 64 + bit)
        })
    })
}

fn assigned_quotient_key<'a>(
    constraint: &'a SemanticQuotientConstraint,
    current_leaf: usize,
    assignment: &[Option<usize>],
) -> Option<&'a kernel_semantics::CanonicalEqKey> {
    constraint.leaves.iter().find_map(|quotient_leaf| {
        if quotient_leaf.leaf == current_leaf {
            return None;
        }
        let ordinal = assignment[quotient_leaf.leaf]?;
        quotient_leaf.keys[ordinal].as_ref()
    })
}

fn cyclic_prefix_candidate_indexes(
    constraints: &[SemanticQuotientConstraint],
    base_masks: &[Vec<u64>],
    search_order: &[usize],
) -> Option<CyclicPrefixCandidateIndexes> {
    if search_order.len() != base_masks.len() {
        return None;
    }
    let mut seen = vec![false; base_masks.len()];
    for leaf in search_order.iter().copied() {
        if leaf >= base_masks.len() || seen[leaf] {
            return None;
        }
        seen[leaf] = true;
    }

    let mut assigned = vec![false; base_masks.len()];
    let mut by_leaf = vec![None; base_masks.len()];
    let mut build_work_upper_bound = 0_u128;
    for leaf in search_order.iter().copied() {
        let constraint_indices = constraints
            .iter()
            .enumerate()
            .filter_map(|(index, constraint)| {
                quotient_leaf(constraint, leaf)?;
                constraint
                    .leaves
                    .iter()
                    .any(|other| other.leaf != leaf && assigned[other.leaf])
                    .then_some(index)
            })
            .collect::<Vec<_>>();
        if !constraint_indices.is_empty() {
            let active_rows = mask_population(&base_masks[leaf]);
            let tree_height = u128::from(
                usize::BITS
                    .saturating_sub(active_rows.max(1).leading_zeros())
                    .saturating_add(1),
            );
            build_work_upper_bound = build_work_upper_bound
                .saturating_add(base_masks[leaf].len() as u128)
                .saturating_add(
                    (active_rows as u128)
                        .saturating_mul(constraint_indices.len().saturating_add(1) as u128)
                        .saturating_mul(tree_height),
                );
            if build_work_upper_bound > MAX_BOUNDED_CYCLIC_ENUMERATION_WORK {
                return None;
            }
            let mut buckets = BTreeMap::<Vec<kernel_semantics::CanonicalEqKey>, Vec<usize>>::new();
            for ordinal in mask_ordinals(&base_masks[leaf]) {
                let mut signature = Vec::with_capacity(constraint_indices.len());
                for constraint_index in &constraint_indices {
                    let current = quotient_leaf(&constraints[*constraint_index], leaf)?;
                    signature.push(current.keys.get(ordinal)?.as_ref()?.clone());
                }
                buckets.entry(signature).or_default().push(ordinal);
            }
            let max_bucket_len = buckets.values().map(Vec::len).max().unwrap_or(0);
            by_leaf[leaf] = Some(CyclicPrefixCandidateIndex {
                constraint_indices,
                buckets,
                max_bucket_len,
            });
        }
        assigned[leaf] = true;
    }
    Some(CyclicPrefixCandidateIndexes {
        by_leaf,
        build_work_upper_bound,
    })
}

fn cyclic_prefix_signature(
    index: &CyclicPrefixCandidateIndex,
    constraints: &[SemanticQuotientConstraint],
    leaf: usize,
    assignment: &[Option<usize>],
) -> Option<Vec<kernel_semantics::CanonicalEqKey>> {
    index
        .constraint_indices
        .iter()
        .map(|constraint_index| {
            assigned_quotient_key(&constraints[*constraint_index], leaf, assignment).cloned()
        })
        .collect()
}

impl OrderPreservingJoinEnumeration<'_> {
    fn enumerate_candidate(
        &self,
        depth: usize,
        leaf_index: usize,
        ordinal: usize,
        assignment: &mut [Option<usize>],
        output: &mut Vec<Vec<usize>>,
        stats: &mut ExecutionStats,
    ) -> Result<(), PhysicalExecutionError> {
        if ordinal >= self.handles[leaf_index].len() {
            return Err(RelQueryError::InconsistentIncrementalDelta.into());
        }
        stats.multiway_join_semantic_quotient_candidate_visits = stats
            .multiway_join_semantic_quotient_candidate_visits
            .saturating_add(1);
        let mut viable = true;
        for constraint in self.constraints {
            let Some(current_leaf) = quotient_leaf(constraint, leaf_index) else {
                continue;
            };
            let Some(key) = current_leaf.keys[ordinal].as_ref() else {
                viable = false;
                break;
            };
            if let Some(expected) = assigned_quotient_key(constraint, leaf_index, assignment)
                && expected != key
            {
                viable = false;
                break;
            }
            for later in constraint
                .leaves
                .iter()
                .filter(|later| later.leaf != leaf_index && assignment[later.leaf].is_none())
            {
                let Some(mask) = later.buckets.get(key) else {
                    viable = false;
                    break;
                };
                if !masks_intersect(mask, &self.base_masks[later.leaf]) {
                    viable = false;
                    break;
                }
            }
            if !viable {
                break;
            }
        }
        if !viable {
            return Ok(());
        }
        assignment[leaf_index] = Some(ordinal);
        self.enumerate(depth + 1, assignment, output, stats)?;
        assignment[leaf_index] = None;
        Ok(())
    }

    fn enumerate(
        &self,
        depth: usize,
        assignment: &mut [Option<usize>],
        output: &mut Vec<Vec<usize>>,
        stats: &mut ExecutionStats,
    ) -> Result<(), PhysicalExecutionError> {
        if depth == self.search_order.len() {
            output.push(
                assignment
                    .iter()
                    .map(|ordinal| {
                        ordinal.ok_or(RelQueryError::InconsistentIncrementalDelta.into())
                    })
                    .collect::<Result<Vec<_>, PhysicalExecutionError>>()?,
            );
            return Ok(());
        }
        let leaf_index = *self
            .search_order
            .get(depth)
            .ok_or(RelQueryError::InconsistentIncrementalDelta)?;

        if let Some(index) = self
            .cyclic_prefix_indexes
            .and_then(|indexes| indexes.by_leaf.get(leaf_index))
            .and_then(Option::as_ref)
        {
            let signature =
                cyclic_prefix_signature(index, self.constraints, leaf_index, assignment)
                    .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
            stats.multiway_join_cyclic_prefix_index_lookups = stats
                .multiway_join_cyclic_prefix_index_lookups
                .saturating_add(1);
            if let Some(ordinals) = index.buckets.get(&signature) {
                for ordinal in ordinals.iter().copied() {
                    self.enumerate_candidate(
                        depth, leaf_index, ordinal, assignment, output, stats,
                    )?;
                }
            }
            return Ok(());
        }

        let mut candidates = self.base_masks[leaf_index].clone();
        for constraint in self.constraints {
            let Some(current_leaf) = quotient_leaf(constraint, leaf_index) else {
                continue;
            };
            let Some(expected) = assigned_quotient_key(constraint, leaf_index, assignment) else {
                continue;
            };
            let Some(mask) = current_leaf.buckets.get(expected) else {
                return Ok(());
            };
            mask_intersect_in_place(&mut candidates, mask);
        }

        for ordinal in mask_ordinals(&candidates) {
            self.enumerate_candidate(depth, leaf_index, ordinal, assignment, output, stats)?;
        }
        Ok(())
    }
}

fn materialize_join_assignments(
    assignments: &mut [Vec<usize>],
    leaves: &[MultiwayJoinLeaf],
    predicates: &[MultiwayJoinPredicate],
    handles: &[Vec<PhysicalRowId>],
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    assignments.sort_unstable();
    let mut output = Vec::with_capacity(assignments.len());
    for assignment in assignments {
        let mut rows = Vec::with_capacity(leaves.len());
        for (leaf, ordinal) in assignment.iter().copied().enumerate() {
            rows.push(leaf_row_by_handle(
                store,
                &leaves[leaf],
                handles[leaf][ordinal],
            )?);
        }
        for predicate in predicates {
            let left = rows[predicate.left.leaf]
                .get(predicate.left.column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            let right = rows[predicate.right.leaf]
                .get(predicate.right.column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            if !registry.equivalent(context, predicate.equivalence, left, right)? {
                return Err(RelQueryError::InconsistentIncrementalDelta.into());
            }
        }
        let width = rows.iter().map(Vec::len).sum();
        let mut materialized = Vec::with_capacity(width);
        for row in rows {
            materialized.extend(row);
        }
        output.push(materialized);
    }
    Ok(output)
}

const MAX_BOUNDED_CYCLIC_ENUMERATION_WORK: u128 = 1_000_000;

fn mask_population(mask: &[u64]) -> usize {
    mask.iter().map(|word| word.count_ones() as usize).sum()
}

fn masked_bucket_population(mask: &[u64], bucket: &[u64]) -> usize {
    mask.iter()
        .zip(bucket)
        .map(|(left, right)| (left & right).count_ones() as usize)
        .sum()
}

fn quotient_enumeration_inputs_valid(
    constraints: &[SemanticQuotientConstraint],
    base_masks: &[Vec<u64>],
    row_counts: &[usize],
    search_order: &[usize],
) -> bool {
    if search_order.len() != base_masks.len() || row_counts.len() != base_masks.len() {
        return false;
    }
    for (leaf, (mask, row_count)) in base_masks.iter().zip(row_counts).enumerate() {
        if mask.len() != row_count.div_ceil(64) {
            return false;
        }
        if let Some(last) = mask.last() {
            let used = row_count % 64;
            if used != 0 && *last >> used != 0 {
                return false;
            }
        }
        for constraint in constraints {
            let Some(current) = quotient_leaf(constraint, leaf) else {
                continue;
            };
            if current.keys.len() != *row_count
                || current
                    .buckets
                    .values()
                    .any(|bucket| bucket.len() != mask.len())
            {
                return false;
            }
        }
    }
    let mut seen = vec![false; base_masks.len()];
    for leaf in search_order.iter().copied() {
        if leaf >= base_masks.len() || seen[leaf] {
            return false;
        }
        seen[leaf] = true;
    }
    true
}

fn quotient_depth_work_upper_bound(
    constraints: &[SemanticQuotientConstraint],
    base_masks: &[Vec<u64>],
    assigned: &[bool],
    leaf: usize,
    prefix_index: Option<&CyclicPrefixCandidateIndex>,
) -> (usize, usize) {
    let mut domain = prefix_index.map_or_else(
        || mask_population(&base_masks[leaf]),
        |index| index.max_bucket_len,
    );
    let mut assigned_bucket_intersections = 0_usize;
    let mut candidate_check_units = 1_usize;
    for constraint in constraints {
        let Some(current) = quotient_leaf(constraint, leaf) else {
            continue;
        };
        candidate_check_units = candidate_check_units.saturating_add(1);
        if constraint
            .leaves
            .iter()
            .any(|other| other.leaf != leaf && assigned[other.leaf])
        {
            assigned_bucket_intersections = assigned_bucket_intersections.saturating_add(1);
            let max_bucket = current
                .buckets
                .values()
                .map(|bucket| masked_bucket_population(&base_masks[leaf], bucket))
                .max()
                .unwrap_or(0);
            domain = domain.min(max_bucket);
        }
        for later in constraint
            .leaves
            .iter()
            .filter(|later| later.leaf != leaf && !assigned[later.leaf])
        {
            candidate_check_units = candidate_check_units
                .saturating_add(1)
                .saturating_add(base_masks[later.leaf].len());
        }
    }
    let per_parent_work = if let Some(index) = prefix_index {
        let lookup_height = usize::BITS
            .saturating_sub(index.buckets.len().max(1).leading_zeros())
            .saturating_add(1) as usize;
        index
            .constraint_indices
            .len()
            .saturating_add(1)
            .saturating_mul(lookup_height)
            .saturating_add(domain.saturating_mul(candidate_check_units))
    } else {
        let mask_word_units = base_masks[leaf]
            .len()
            .saturating_mul(1_usize.saturating_add(assigned_bucket_intersections));
        mask_word_units.saturating_add(domain.saturating_mul(candidate_check_units))
    };
    (per_parent_work, domain)
}
fn quotient_enumeration_work_upper_bound(
    constraints: &[SemanticQuotientConstraint],
    base_masks: &[Vec<u64>],
    row_counts: &[usize],
    search_order: &[usize],
    cyclic_prefix_indexes: Option<&CyclicPrefixCandidateIndexes>,
) -> Option<u128> {
    if !quotient_enumeration_inputs_valid(constraints, base_masks, row_counts, search_order) {
        return None;
    }
    let mut assigned = vec![false; base_masks.len()];
    let mut parent_prefix = 1_u128;
    let mut work = cyclic_prefix_indexes.map_or(0, |indexes| indexes.build_work_upper_bound);
    if work > MAX_BOUNDED_CYCLIC_ENUMERATION_WORK {
        return Some(work);
    }
    for leaf in search_order.iter().copied() {
        let prefix_index = cyclic_prefix_indexes
            .and_then(|indexes| indexes.by_leaf.get(leaf))
            .and_then(Option::as_ref);
        let (per_parent_work, domain) =
            quotient_depth_work_upper_bound(constraints, base_masks, &assigned, leaf, prefix_index);
        work = work.saturating_add(parent_prefix.saturating_mul(per_parent_work as u128));
        if work > MAX_BOUNDED_CYCLIC_ENUMERATION_WORK {
            return Some(work);
        }
        assigned[leaf] = true;
        parent_prefix = parent_prefix.saturating_mul(domain as u128);
    }
    work = work.saturating_add(parent_prefix.saturating_mul(search_order.len() as u128));
    Some(work)
}

enum CyclicExecutionAdmission {
    NotCyclic,
    Bounded(CyclicPrefixCandidateIndexes),
}

fn bounded_cyclic_execution_certificate(
    prepared_program: Option<&PreparedSemanticQuotientProgram>,
    constraints: &[SemanticQuotientConstraint],
    base_masks: &[Vec<u64>],
    row_counts: &[usize],
    search_order: &[usize],
) -> Option<CyclicExecutionAdmission> {
    if !prepared_program.is_some_and(|program| {
        program.search_certificate == Some(SemanticQuotientSearchCertificate::BoundedCyclic)
    }) {
        return Some(CyclicExecutionAdmission::NotCyclic);
    }
    let indexes = cyclic_prefix_candidate_indexes(constraints, base_masks, search_order)?;
    let bound = quotient_enumeration_work_upper_bound(
        constraints,
        base_masks,
        row_counts,
        search_order,
        Some(&indexes),
    )?;
    (bound <= MAX_BOUNDED_CYCLIC_ENUMERATION_WORK)
        .then_some(CyclicExecutionAdmission::Bounded(indexes))
}

fn record_quotient_support_stats(
    stats: &mut ExecutionStats,
    handles: &[Vec<PhysicalRowId>],
    constraints: &[SemanticQuotientConstraint],
    base_masks: &[Vec<u64>],
) {
    stats.multiway_join_semantic_quotient_constraints = stats
        .multiway_join_semantic_quotient_constraints
        .saturating_add(constraints.len());
    let supported_rows = base_masks
        .iter()
        .map(|mask| mask_population(mask))
        .sum::<usize>();
    stats.multiway_join_semantic_quotient_pruned_rows = stats
        .multiway_join_semantic_quotient_pruned_rows
        .saturating_add(
            handles
                .iter()
                .map(Vec::len)
                .sum::<usize>()
                .saturating_sub(supported_rows),
        );
}

#[derive(Clone, Copy)]
struct QuotientJoinExecutionRequest<'a> {
    leaves: &'a [MultiwayJoinLeaf],
    predicates: &'a [MultiwayJoinPredicate],
    search_order: &'a [usize],
    prepared_program: Option<&'a PreparedSemanticQuotientProgram>,
    store: &'a PhysicalStore,
    context: &'a kernel_schema::SemanticContext,
    registry: &'a kernel_semantics::SemanticRegistry,
}

fn execute_order_preserving_quotient_join(
    request: QuotientJoinExecutionRequest<'_>,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let QuotientJoinExecutionRequest {
        leaves,
        predicates,
        search_order,
        prepared_program,
        store,
        context,
        registry,
    } = request;
    let handles = leaves
        .iter()
        .map(|leaf| store.logical_row_handles(leaf.relation, leaf.layout))
        .collect::<Result<Vec<_>, _>>()?;
    stats.scanned_rows = stats
        .scanned_rows
        .saturating_add(handles.iter().map(Vec::len).sum::<usize>());

    let support_binding =
        prepared_program.map(|program| semantic_quotient_support_binding(leaves, program));
    let maintained_support = support_binding
        .as_ref()
        .and_then(|binding| store.semantic_quotient_support(binding))
        .filter(|state| {
            state.handles == handles && matches!(state.compatible_with(context, registry), Ok(true))
        });

    let owned_constraints;
    let owned_masks;
    let (constraints, base_masks): (&[SemanticQuotientConstraint], &[Vec<u64>]) =
        if let Some(state) = maintained_support {
            stats.multiway_join_maintained_quotient_support_hits = stats
                .multiway_join_maintained_quotient_support_hits
                .saturating_add(1);
            (state.constraints.as_slice(), state.base_masks.as_slice())
        } else {
            let build = SemanticQuotientBuildContext {
                leaves,
                predicates,
                handles: &handles,
                store,
                context,
                registry,
            };
            let Some(mut constraints) = build_semantic_quotient_constraints(
                &build,
                prepared_program.map(|program| program.specs.as_slice()),
                stats,
            )?
            else {
                return Ok(None);
            };
            owned_masks = quotient_support_masks(&handles, &mut constraints);
            owned_constraints = constraints;
            (owned_constraints.as_slice(), owned_masks.as_slice())
        };

    record_quotient_support_stats(stats, &handles, constraints, base_masks);
    if base_masks
        .iter()
        .any(|mask| mask.iter().all(|word| *word == 0))
    {
        return Ok(Some(Vec::new()));
    }
    let row_counts = handles.iter().map(Vec::len).collect::<Vec<_>>();
    let Some(cyclic_admission) = bounded_cyclic_execution_certificate(
        prepared_program,
        constraints,
        base_masks,
        &row_counts,
        search_order,
    ) else {
        stats.multiway_join_cyclic_budget_rejections = stats
            .multiway_join_cyclic_budget_rejections
            .saturating_add(1);
        return Ok(None);
    };
    let execution = OrderPreservingJoinEnumeration {
        handles: &handles,
        constraints,
        base_masks,
        search_order,
        cyclic_prefix_indexes: match &cyclic_admission {
            CyclicExecutionAdmission::NotCyclic => None,
            CyclicExecutionAdmission::Bounded(indexes) => Some(indexes),
        },
    };
    let mut assignment = vec![None; leaves.len()];
    let mut assignments = Vec::new();
    execution.enumerate(0, &mut assignment, &mut assignments, stats)?;
    materialize_join_assignments(
        &mut assignments,
        leaves,
        predicates,
        &handles,
        store,
        context,
        registry,
    )
    .map(Some)
}

fn leaf_pair_distinct_estimate(
    store: &PhysicalStore,
    leaves: &[MultiwayJoinLeaf],
    predicate: MultiwayJoinPredicate,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<(usize, usize)>, PhysicalExecutionError> {
    let left_leaf = &leaves[predicate.left.leaf];
    let right_leaf = &leaves[predicate.right.leaf];
    let left_binding = SemanticIndexBinding::single(
        left_leaf.relation,
        left_leaf.layout,
        predicate.left.column,
        predicate.equivalence,
    );
    let right_binding = SemanticIndexBinding::single(
        right_leaf.relation,
        right_leaf.layout,
        predicate.right.column,
        predicate.equivalence,
    );
    let Some(left) = store.semantic_statistics(&left_binding, context, registry)? else {
        return Ok(None);
    };
    let Some(right) = store.semantic_statistics(&right_binding, context, registry)? else {
        return Ok(None);
    };
    Ok(Some((
        left.distinct_key_count.max(1),
        right.distinct_key_count.max(1),
    )))
}

fn estimated_quotient_build_work(
    store: &PhysicalStore,
    leaves: &[MultiwayJoinLeaf],
    predicates: &[MultiwayJoinPredicate],
    prepared_program: Option<&PreparedSemanticQuotientProgram>,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<u128, PhysicalExecutionError> {
    let owned_specs;
    let quotient_specs = if let Some(program) = prepared_program {
        program.specs.as_slice()
    } else {
        owned_specs = semantic_quotient_specs(predicates, context, registry)?;
        &owned_specs
    };
    let mut specs = BTreeSet::new();
    for (equivalence, endpoints) in quotient_specs {
        for endpoint in endpoints {
            specs.insert((endpoint.leaf, endpoint.column, *equivalence));
        }
    }
    let mut work = 0_u128;
    for (leaf, column, equivalence) in specs {
        let leaf = &leaves[leaf];
        let binding = SemanticIndexBinding::single(leaf.relation, leaf.layout, column, equivalence);
        let compatible = store.has_semantic_quotient_capability(&binding, context, registry)?;
        if !compatible {
            work = work.saturating_add(leaf.rows as u128);
        }
    }
    Ok(work)
}

#[derive(Debug, Clone)]
struct SubsetJoinCandidate {
    cost: u128,
    estimated_rows: usize,
}

fn predicate_crosses_subsets(predicate: MultiwayJoinPredicate, left: u64, right: u64) -> bool {
    let left_endpoint = 1_u64 << predicate.left.leaf;
    let right_endpoint = 1_u64 << predicate.right.leaf;
    (left & left_endpoint != 0 && right & right_endpoint != 0)
        || (left & right_endpoint != 0 && right & left_endpoint != 0)
}

fn subset_singleton_prefers_indexed_access(
    planner: &MultiwayPlannerContext<'_>,
    predicates: &[MultiwayJoinPredicate],
    singleton_subset: u64,
    other_subset: u64,
    other_rows: usize,
) -> Result<bool, PhysicalExecutionError> {
    if singleton_subset.count_ones() != 1 {
        return Ok(false);
    }
    let singleton = singleton_subset.trailing_zeros() as usize;
    for predicate in predicates
        .iter()
        .copied()
        .filter(|predicate| predicate_crosses_subsets(*predicate, singleton_subset, other_subset))
    {
        let oriented = if predicate.right.leaf == singleton {
            predicate
        } else if predicate.left.leaf == singleton {
            MultiwayJoinPredicate {
                left: predicate.right,
                right: predicate.left,
                equivalence: predicate.equivalence,
            }
        } else {
            continue;
        };
        let decision = multiway_right_access_estimate(
            planner.store,
            &planner.leaves[singleton],
            oriented,
            other_rows,
            planner.context,
            planner.registry,
        )?;
        if matches!(
            decision.family,
            JoinAccessFamily::PersistedI64 | JoinAccessFamily::PersistedSemantic
        ) {
            return Ok(true);
        }
    }
    Ok(false)
}

fn subset_merge_estimate(
    planner: &MultiwayPlannerContext<'_>,
    predicates: &[MultiwayJoinPredicate],
    left_subset: u64,
    right_subset: u64,
    left_rows: usize,
    right_rows: usize,
) -> Result<Option<(u128, usize)>, PhysicalExecutionError> {
    let product_rows = left_rows.saturating_mul(right_rows);
    let product_work = (left_rows as u128).saturating_mul(right_rows as u128);
    if subset_singleton_prefers_indexed_access(
        planner,
        predicates,
        right_subset,
        left_subset,
        left_rows,
    )? || subset_singleton_prefers_indexed_access(
        planner,
        predicates,
        left_subset,
        right_subset,
        right_rows,
    )? {
        return Ok(None);
    }
    let mut estimated_rows = None;
    for predicate in predicates
        .iter()
        .copied()
        .filter(|predicate| predicate_crosses_subsets(*predicate, left_subset, right_subset))
    {
        let Some((left_distinct, right_distinct)) = leaf_pair_distinct_estimate(
            planner.store,
            planner.leaves,
            predicate,
            planner.context,
            planner.registry,
        )?
        else {
            continue;
        };
        let rows = product_rows.div_ceil(left_distinct.max(right_distinct).max(1));
        estimated_rows = Some(estimated_rows.map_or(rows, |current: usize| current.min(rows)));
    }
    Ok(estimated_rows.map(|rows| (product_work, rows)))
}

fn best_subset_join_candidate(
    planner: &MultiwayPlannerContext<'_>,
    predicates: &[MultiwayJoinPredicate],
) -> Result<Option<SubsetJoinCandidate>, PhysicalExecutionError> {
    let count = planner.leaves.len();
    if !(3..=8).contains(&count) {
        return Ok(None);
    }
    let full = (1_u64 << count) - 1;
    let mut best = BTreeMap::<u64, SubsetJoinCandidate>::new();
    for (leaf, relation) in planner.leaves.iter().enumerate() {
        best.insert(
            1_u64 << leaf,
            SubsetJoinCandidate {
                cost: 0,
                estimated_rows: relation.rows,
            },
        );
    }

    for cardinality in 2..=count {
        for subset in 1_u64..=full {
            if subset.count_ones() as usize != cardinality {
                continue;
            }
            let mut candidate_best: Option<SubsetJoinCandidate> = None;
            let mut left_subset = (subset - 1) & subset;
            while left_subset != 0 {
                let right_subset = subset ^ left_subset;
                if right_subset != 0 && left_subset < right_subset {
                    let (Some(left), Some(right)) =
                        (best.get(&left_subset), best.get(&right_subset))
                    else {
                        left_subset = (left_subset - 1) & subset;
                        continue;
                    };
                    if let Some((join_work, estimated_rows)) = subset_merge_estimate(
                        planner,
                        predicates,
                        left_subset,
                        right_subset,
                        left.estimated_rows,
                        right.estimated_rows,
                    )? {
                        let candidate = SubsetJoinCandidate {
                            cost: left
                                .cost
                                .saturating_add(right.cost)
                                .saturating_add(join_work),
                            estimated_rows,
                        };
                        let replace = candidate_best.as_ref().is_none_or(|current| {
                            candidate.cost < current.cost
                                || (candidate.cost == current.cost
                                    && candidate.estimated_rows < current.estimated_rows)
                        });
                        if replace {
                            candidate_best = Some(candidate);
                        }
                    }
                }
                left_subset = (left_subset - 1) & subset;
            }
            if let Some(candidate) = candidate_best {
                best.insert(subset, candidate);
            }
        }
    }
    Ok(best.remove(&full))
}

fn bounded_cyclic_advisor_preflight(
    leaves: &[MultiwayJoinLeaf],
    predicates: &[MultiwayJoinPredicate],
    program: &PreparedSemanticQuotientProgram,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<bool, PhysicalExecutionError> {
    if program.search_certificate != Some(SemanticQuotientSearchCertificate::BoundedCyclic) {
        return Ok(true);
    }
    let handles = leaves
        .iter()
        .map(|leaf| store.logical_row_handles(leaf.relation, leaf.layout))
        .collect::<Result<Vec<_>, _>>()?;
    let build = SemanticQuotientBuildContext {
        leaves,
        predicates,
        handles: &handles,
        store,
        context,
        registry,
    };
    let mut stats = ExecutionStats::default();
    let Some(mut constraints) =
        build_semantic_quotient_constraints(&build, Some(program.specs.as_slice()), &mut stats)?
    else {
        return Ok(false);
    };
    let base_masks = quotient_support_masks(&handles, &mut constraints);
    if base_masks
        .iter()
        .any(|mask| mask.iter().all(|word| *word == 0))
    {
        return Ok(true);
    }
    let row_counts = handles.iter().map(Vec::len).collect::<Vec<_>>();
    Ok(bounded_cyclic_execution_certificate(
        Some(program),
        &constraints,
        &base_masks,
        &row_counts,
        program.hypergraph_order.as_deref().unwrap_or(&[]),
    )
    .is_some())
}

fn preferred_nway_order_preserving_join_inputs(
    plan: &Plan,
    prepared_program: Option<&PreparedSemanticQuotientProgram>,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    advisor_preflight: bool,
) -> Result<Option<PreferredNwayOrderPreservingJoin>, PhysicalExecutionError> {
    let mut leaves = Vec::new();
    let mut predicates = Vec::new();
    let Some(_) = flatten_multiway_join_tree(plan, store, &mut leaves, &mut predicates)? else {
        return Ok(None);
    };
    if leaves.len() < 3 {
        return Ok(None);
    }
    let hypergraph_order = prepared_program
        .and_then(|program| program.hypergraph_order.as_ref())
        .filter(|order| order.len() == leaves.len());
    if leaves.len() > 8 {
        let Some(search_order) = hypergraph_order else {
            return Ok(None);
        };
        if advisor_preflight
            && let Some(program) = prepared_program
            && !bounded_cyclic_advisor_preflight(
                &leaves,
                &predicates,
                program,
                store,
                context,
                registry,
            )?
        {
            return Ok(None);
        }
        return Ok(Some(PreferredNwayOrderPreservingJoin {
            leaves,
            predicates,
            search_order: search_order.clone(),
        }));
    }
    let planner = MultiwayPlannerContext {
        store,
        leaves: &leaves,
        context,
        registry,
    };
    let Some(candidate) = best_subset_join_candidate(&planner, &predicates)? else {
        return Ok(None);
    };
    let Some(contiguous) = best_contiguous_multiway_join_candidate(plan, store, context, registry)?
    else {
        return Ok(None);
    };
    let estimated_work = candidate
        .cost
        .saturating_add(estimated_quotient_build_work(
            store,
            &leaves,
            &predicates,
            prepared_program,
            context,
            registry,
        )?)
        .saturating_add(candidate.estimated_rows as u128);
    if estimated_work >= contiguous.cost {
        return Ok(None);
    }
    Ok(Some(PreferredNwayOrderPreservingJoin {
        search_order: hypergraph_order
            .cloned()
            .unwrap_or_else(|| (0..leaves.len()).collect()),
        leaves,
        predicates,
    }))
}

fn try_execute_nway_order_preserving_join(
    plan: &Plan,
    prepared_program: Option<&PreparedSemanticQuotientProgram>,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let Some(preferred) = preferred_nway_order_preserving_join_inputs(
        plan,
        prepared_program,
        store,
        context,
        registry,
        false,
    )?
    else {
        return Ok(None);
    };
    execute_order_preserving_quotient_join(
        QuotientJoinExecutionRequest {
            leaves: &preferred.leaves,
            predicates: &preferred.predicates,
            search_order: &preferred.search_order,
            prepared_program,
            store,
            context,
            registry,
        },
        stats,
    )
}

fn try_execute_multiway_join(
    plan: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    if !matches!(plan, Plan::JoinEq { .. } | Plan::FilterEqColumns { .. }) {
        return Ok(None);
    }
    if let Some(rows) =
        try_execute_nway_order_preserving_join(plan, None, store, context, registry, stats)?
    {
        stats.multiway_join_reorders = stats.multiway_join_reorders.saturating_add(1);
        stats.multiway_join_order_preserving_enumerations = stats
            .multiway_join_order_preserving_enumerations
            .saturating_add(1);
        return Ok(Some(rows));
    }
    let Some(optimized) = optimize_contiguous_multiway_join(plan, store, context, registry)? else {
        return Ok(None);
    };
    stats.multiway_join_reorders = stats.multiway_join_reorders.saturating_add(1);
    execute_multiway_join_candidate(&optimized, store, context, registry, stats).map(Some)
}

fn flatten_multiway_join_tree(
    plan: &Plan,
    store: &PhysicalStore,
    leaves: &mut Vec<MultiwayJoinLeaf>,
    predicates: &mut Vec<MultiwayJoinPredicate>,
) -> Result<Option<Vec<MultiwayJoinColumnRef>>, PhysicalExecutionError> {
    match plan {
        Plan::Scan {
            relation,
            layout,
            algorithm: ScanAlgorithm::FullScan,
        } => {
            let installed = store.installed(*relation, *layout)?;
            let width = native_column_count(&installed.data);
            let leaf = leaves.len();
            leaves.push(MultiwayJoinLeaf {
                plan: plan.clone(),
                relation: *relation,
                layout: *layout,
                width,
                rows: native_row_count(&installed.data),
            });
            Ok(Some(
                (0..width)
                    .map(|column| MultiwayJoinColumnRef { leaf, column })
                    .collect(),
            ))
        }
        Plan::JoinEq {
            left,
            right,
            left_column,
            right_column,
            equivalence,
            ..
        } => {
            let Some(mut left_columns) =
                flatten_multiway_join_tree(left, store, leaves, predicates)?
            else {
                return Ok(None);
            };
            let Some(right_columns) = flatten_multiway_join_tree(right, store, leaves, predicates)?
            else {
                return Ok(None);
            };
            let Some(left_ref) = left_columns.get(*left_column).copied() else {
                return Err(RelQueryError::ColumnOutOfBounds.into());
            };
            let Some(right_ref) = right_columns.get(*right_column).copied() else {
                return Err(RelQueryError::ColumnOutOfBounds.into());
            };
            predicates.push(MultiwayJoinPredicate {
                left: left_ref,
                right: right_ref,
                equivalence: *equivalence,
            });
            left_columns.extend(right_columns);
            Ok(Some(left_columns))
        }
        Plan::FilterEqColumns {
            input,
            left_column,
            right_column,
            equivalence,
        } => {
            let Some(columns) = flatten_multiway_join_tree(input, store, leaves, predicates)?
            else {
                return Ok(None);
            };
            let Some(left_ref) = columns.get(*left_column).copied() else {
                return Err(RelQueryError::ColumnOutOfBounds.into());
            };
            let Some(right_ref) = columns.get(*right_column).copied() else {
                return Err(RelQueryError::ColumnOutOfBounds.into());
            };
            if left_ref.leaf == right_ref.leaf {
                return Ok(None);
            }
            predicates.push(MultiwayJoinPredicate {
                left: left_ref,
                right: right_ref,
                equivalence: *equivalence,
            });
            Ok(Some(columns))
        }
        _ => Ok(None),
    }
}

fn execute_multiway_join_candidate(
    plan: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    match plan {
        Plan::FilterEqColumns {
            input,
            left_column,
            right_column,
            equivalence,
        } => {
            let input_rows =
                execute_multiway_join_candidate(input, store, context, registry, stats)?;
            filter_rows_columns(
                input_rows,
                *left_column,
                *right_column,
                *equivalence,
                context,
                registry,
                stats,
            )
        }
        Plan::JoinEq {
            left,
            right,
            left_column,
            right_column,
            equivalence,
            algorithm,
        } => execute_join_plan(
            left,
            right,
            *left_column,
            *right_column,
            *equivalence,
            *algorithm,
            store,
            context,
            registry,
            stats,
        ),
        _ => plan.execute_native_rows(store, context, registry, stats),
    }
}

fn interval_width(leaves: &[MultiwayJoinLeaf], start: usize, end: usize) -> usize {
    leaves[start..=end]
        .iter()
        .fold(0_usize, |width, leaf| width.saturating_add(leaf.width))
}

fn interval_column(
    leaves: &[MultiwayJoinLeaf],
    start: usize,
    column: MultiwayJoinColumnRef,
) -> usize {
    leaves[start..column.leaf]
        .iter()
        .fold(0_usize, |offset, leaf| offset.saturating_add(leaf.width))
        .saturating_add(column.column)
}

fn crossing_join_predicates(
    predicates: &[MultiwayJoinPredicate],
    start: usize,
    split: usize,
    end: usize,
) -> Vec<MultiwayJoinPredicate> {
    predicates
        .iter()
        .filter_map(|predicate| {
            let left_in_left = (start..=split).contains(&predicate.left.leaf);
            let right_in_right = ((split + 1)..=end).contains(&predicate.right.leaf);
            if left_in_left && right_in_right {
                Some(*predicate)
            } else {
                let right_in_left = (start..=split).contains(&predicate.right.leaf);
                let left_in_right = ((split + 1)..=end).contains(&predicate.left.leaf);
                (right_in_left && left_in_right).then_some(MultiwayJoinPredicate {
                    left: predicate.right,
                    right: predicate.left,
                    equivalence: predicate.equivalence,
                })
            }
        })
        .collect()
}

fn multiway_right_access_estimate(
    store: &PhysicalStore,
    leaf: &MultiwayJoinLeaf,
    predicate: MultiwayJoinPredicate,
    left_rows: usize,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<JoinAccessDecision, PhysicalExecutionError> {
    let binding = SemanticIndexBinding::single(
        leaf.relation,
        leaf.layout,
        predicate.right.column,
        predicate.equivalence,
    );
    let allow_ephemeral = store
        .semantic_statistics(&binding, context, registry)?
        .is_some();
    right_scan_join_access_decision(
        RightJoinAccessRequest {
            left_rows,
            right_relation: leaf.relation,
            right_layout: leaf.layout,
            right_column: predicate.right.column,
            equivalence: predicate.equivalence,
            allow_ephemeral,
        },
        store,
        context,
        registry,
    )
}

fn multiway_join_merge_estimate(
    planner: &MultiwayPlannerContext<'_>,
    crossing: &[MultiwayJoinPredicate],
    interval: MultiwayJoinInterval,
    left_rows: usize,
    right_rows: usize,
) -> Result<(u128, usize, usize), PhysicalExecutionError> {
    let nested_work = (left_rows as u128).saturating_mul(right_rows as u128);
    let mut best = (nested_work, left_rows.saturating_mul(right_rows), 0_usize);
    if interval.split + 1 != interval.end {
        return Ok(best);
    }
    let right_leaf = &planner.leaves[interval.end];
    for (index, predicate) in crossing.iter().copied().enumerate() {
        let decision = multiway_right_access_estimate(
            planner.store,
            right_leaf,
            predicate,
            left_rows,
            planner.context,
            planner.registry,
        )?;
        if decision.family != JoinAccessFamily::FullScan && (decision.work as u128) < best.0 {
            best = (decision.work as u128, decision.estimated_output_rows, index);
        }
    }
    Ok(best)
}

fn build_multiway_join_merge(
    planner: &MultiwayPlannerContext<'_>,
    interval: MultiwayJoinInterval,
    left: Plan,
    right: Plan,
    crossing: &[MultiwayJoinPredicate],
    primary_index: usize,
) -> Plan {
    let leaves = planner.leaves;
    let primary = crossing[primary_index];
    let left_column = interval_column(leaves, interval.start, primary.left);
    let right_column = interval_column(leaves, interval.split + 1, primary.right);
    let mut plan = Plan::JoinEq {
        left: Box::new(left),
        right: Box::new(right),
        left_column,
        right_column,
        equivalence: primary.equivalence,
        algorithm: JoinAlgorithm::IndexedPrimitiveIfAvailable,
    };
    let left_width = interval_width(leaves, interval.start, interval.split);
    for (index, predicate) in crossing.iter().copied().enumerate() {
        if index == primary_index {
            continue;
        }
        plan = Plan::FilterEqColumns {
            input: Box::new(plan),
            left_column: interval_column(leaves, interval.start, predicate.left),
            right_column: left_width.saturating_add(interval_column(
                leaves,
                interval.split + 1,
                predicate.right,
            )),
            equivalence: predicate.equivalence,
        };
    }
    debug_assert_eq!(
        interval_width(leaves, interval.start, interval.end),
        left_width + interval_width(leaves, interval.split + 1, interval.end)
    );
    plan
}

fn best_contiguous_multiway_join_candidate(
    plan: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<MultiwayJoinCandidate>, PhysicalExecutionError> {
    let mut leaves = Vec::new();
    let mut predicates = Vec::new();
    let Some(_) = flatten_multiway_join_tree(plan, store, &mut leaves, &mut predicates)? else {
        return Ok(None);
    };
    if leaves.len() < 3 || leaves.len() > 32 {
        return Ok(None);
    }

    let planner = MultiwayPlannerContext {
        store,
        leaves: &leaves,
        context,
        registry,
    };
    let count = leaves.len();
    let mut best = BTreeMap::<(usize, usize), MultiwayJoinCandidate>::new();
    for (index, leaf) in leaves.iter().enumerate() {
        best.insert(
            (index, index),
            MultiwayJoinCandidate {
                plan: leaf.plan.clone(),
                cost: 0,
                estimated_rows: leaf.rows,
            },
        );
    }

    for len in 2..=count {
        for start in 0..=(count - len) {
            let end = start + len - 1;
            let mut interval_best: Option<MultiwayJoinCandidate> = None;
            for split in start..end {
                let crossing = crossing_join_predicates(&predicates, start, split, end);
                if crossing.is_empty() {
                    continue;
                }
                let Some(left) = best.get(&(start, split)) else {
                    continue;
                };
                let Some(right) = best.get(&(split + 1, end)) else {
                    continue;
                };
                let interval = MultiwayJoinInterval { start, split, end };
                let (join_work, estimated_rows, primary_index) = multiway_join_merge_estimate(
                    &planner,
                    &crossing,
                    interval,
                    left.estimated_rows,
                    right.estimated_rows,
                )?;
                let candidate = MultiwayJoinCandidate {
                    plan: build_multiway_join_merge(
                        &planner,
                        interval,
                        left.plan.clone(),
                        right.plan.clone(),
                        &crossing,
                        primary_index,
                    ),
                    cost: left
                        .cost
                        .saturating_add(right.cost)
                        .saturating_add(join_work),
                    estimated_rows,
                };
                let replace = interval_best.as_ref().is_none_or(|current| {
                    candidate.cost < current.cost
                        || (candidate.cost == current.cost
                            && candidate.estimated_rows < current.estimated_rows)
                });
                if replace {
                    interval_best = Some(candidate);
                }
            }
            if let Some(candidate) = interval_best {
                best.insert((start, end), candidate);
            }
        }
    }

    Ok(best.remove(&(0, count - 1)))
}

fn optimize_contiguous_multiway_join(
    plan: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<Plan>, PhysicalExecutionError> {
    let Some(candidate) = best_contiguous_multiway_join_candidate(plan, store, context, registry)?
    else {
        return Ok(None);
    };
    if candidate.plan == *plan {
        Ok(None)
    } else {
        Ok(Some(candidate.plan))
    }
}

#[allow(clippy::too_many_arguments)]
fn execute_join_plan(
    left: &Plan,
    right: &Plan,
    left_column: usize,
    right_column: usize,
    equivalence: SemanticId,
    algorithm: JoinAlgorithm,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let key = JoinKeySpec {
        left_column,
        right_column,
        equivalence,
    };
    if algorithm == JoinAlgorithm::IndexedPrimitiveIfAvailable {
        if direct_scan_relation(left).is_none() && direct_scan_relation(right).is_some() {
            let left_rows = left.execute_native_rows(store, context, registry, stats)?;
            if let Some(rows) = try_execute_indexed_right_scan_join_from_rows(
                &left_rows, right, key, store, context, registry, stats,
            )? {
                return Ok(rows);
            }
            let right_rows = right.execute_native_rows(store, context, registry, stats)?;
            return join_rows(
                &left_rows,
                &right_rows,
                left_column,
                right_column,
                equivalence,
                context,
                registry,
            );
        }
        if let Some(decision) =
            direct_join_access_decision(left, right, key, store, context, registry)?
        {
            if decision.persisted_rejected {
                stats.persisted_index_cost_rejections =
                    stats.persisted_index_cost_rejections.saturating_add(1);
            }
            let rows = match decision.family {
                JoinAccessFamily::FullScan => None,
                JoinAccessFamily::PersistedI64 => try_execute_indexed_i64_join(
                    left,
                    right,
                    left_column,
                    right_column,
                    equivalence,
                    store,
                    context,
                    registry,
                    stats,
                    false,
                )?,
                JoinAccessFamily::PersistedSemantic => try_execute_persisted_semantic_join(
                    left,
                    right,
                    left_column,
                    right_column,
                    equivalence,
                    store,
                    context,
                    registry,
                    stats,
                )?,
                JoinAccessFamily::EphemeralI64 => try_execute_indexed_i64_join(
                    left,
                    right,
                    left_column,
                    right_column,
                    equivalence,
                    store,
                    context,
                    registry,
                    stats,
                    true,
                )?,
                JoinAccessFamily::EphemeralSemantic => try_execute_ephemeral_semantic_join(
                    left, right, key, store, context, registry, stats,
                )?,
            };
            if let Some(rows) = rows {
                return Ok(rows);
            }
        }
    }
    let left_rows = left.execute_native_rows(store, context, registry, stats)?;
    let right_rows = right.execute_native_rows(store, context, registry, stats)?;
    join_rows(
        &left_rows,
        &right_rows,
        left_column,
        right_column,
        equivalence,
        context,
        registry,
    )
}

#[derive(Debug, Clone, Copy)]
struct JoinKeySpec {
    left_column: usize,
    right_column: usize,
    equivalence: SemanticId,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum JoinAccessFamily {
    FullScan,
    PersistedI64,
    PersistedSemantic,
    EphemeralI64,
    EphemeralSemantic,
}

impl JoinAccessFamily {
    const fn tie_priority(self) -> u8 {
        match self {
            Self::FullScan => 0,
            Self::PersistedI64 => 1,
            Self::PersistedSemantic => 2,
            Self::EphemeralI64 => 3,
            Self::EphemeralSemantic => 4,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct JoinAccessDecision {
    family: JoinAccessFamily,
    work: usize,
    estimated_output_rows: usize,
    persisted_rejected: bool,
}

#[derive(Debug, Clone, Copy)]
struct RightJoinAccessRequest {
    left_rows: usize,
    right_relation: SemanticId,
    right_layout: LayoutBinding,
    right_column: usize,
    equivalence: SemanticId,
    allow_ephemeral: bool,
}

fn consider_join_access_candidate(best: &mut JoinAccessDecision, candidate: JoinAccessDecision) {
    if candidate.work < best.work
        || (candidate.work == best.work
            && candidate.family.tie_priority() < best.family.tie_priority())
    {
        *best = candidate;
    }
}

#[derive(Debug, Clone, Copy)]
struct TransientJoinEstimate {
    left_rows: usize,
    right_rows: usize,
    distinct_keys: usize,
    key_parts: usize,
    is_i64: bool,
    semantic_supported: bool,
}

fn consider_ephemeral_join_candidates(
    best: &mut JoinAccessDecision,
    estimate: TransientJoinEstimate,
) {
    let TransientJoinEstimate {
        left_rows,
        right_rows,
        distinct_keys,
        key_parts,
        is_i64,
        semantic_supported,
    } = estimate;
    let average_bucket = right_rows.div_ceil(distinct_keys.max(1));
    let candidate = |family| JoinAccessDecision {
        family,
        work: SemanticAccessCostModel::ephemeral_join_work(
            left_rows,
            right_rows,
            distinct_keys,
            key_parts,
        ),
        estimated_output_rows: left_rows.saturating_mul(average_bucket),
        persisted_rejected: false,
    };
    if is_i64 {
        consider_join_access_candidate(best, candidate(JoinAccessFamily::EphemeralI64));
    }
    if semantic_supported {
        consider_join_access_candidate(best, candidate(JoinAccessFamily::EphemeralSemantic));
    }
}

fn right_scan_join_access_decision(
    request: RightJoinAccessRequest,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<JoinAccessDecision, PhysicalExecutionError> {
    let RightJoinAccessRequest {
        left_rows,
        right_relation,
        right_layout,
        right_column,
        equivalence,
        allow_ephemeral,
    } = request;
    let right = store.installed(right_relation, right_layout)?;
    let right_rows = native_row_count(&right.data);
    let mut best = JoinAccessDecision {
        family: JoinAccessFamily::FullScan,
        work: SemanticAccessCostModel::join_scan_work(left_rows, right_rows),
        estimated_output_rows: left_rows.saturating_mul(right_rows),
        persisted_rejected: false,
    };
    if left_rows == 0 || right_rows == 0 {
        return Ok(best);
    }

    let resolved = registry.resolve_primitive_equivalence(context, equivalence)?;
    let is_i64 = resolved.as_ref().is_some_and(|resolved| {
        matches!(
            resolved.bind_right(&Value::I64(0)),
            Ok(kernel_semantics::BoundPrimitivePredicate::I64(_))
        )
    });

    let mut saw_persisted = false;
    if is_i64
        && let Some(index) = store.i64_index(I64IndexBinding {
            relation: right_relation,
            layout: right_layout,
            key_column: right_column,
            equivalence,
        })
    {
        saw_persisted = true;
        let distinct = index.distinct_key_count();
        let average_bucket = right_rows.div_ceil(distinct.max(1));
        consider_join_access_candidate(
            &mut best,
            JoinAccessDecision {
                family: JoinAccessFamily::PersistedI64,
                work: SemanticAccessCostModel::persisted_join_work(left_rows, right_rows, distinct),
                estimated_output_rows: left_rows.saturating_mul(average_bucket),
                persisted_rejected: false,
            },
        );
    }

    let binding =
        SemanticIndexBinding::single(right_relation, right_layout, right_column, equivalence);
    let semantic_supported = primitive_binding_supported(&binding, context, registry)?;
    let retained_statistics = store.semantic_statistics(&binding, context, registry)?;
    let transient_distinct = retained_statistics.map_or(right_rows, |statistics| {
        statistics.distinct_key_count.max(1)
    });
    if let Some(capability) = store.semantic_fiber_capability(&binding, context, registry)? {
        saw_persisted = true;
        let distinct = capability.distinct_key_count();
        let average_bucket = right_rows.div_ceil(distinct.max(1));
        consider_join_access_candidate(
            &mut best,
            JoinAccessDecision {
                family: JoinAccessFamily::PersistedSemantic,
                work: SemanticAccessCostModel::persisted_join_work(left_rows, right_rows, distinct),
                estimated_output_rows: left_rows.saturating_mul(average_bucket),
                persisted_rejected: false,
            },
        );
    }

    if allow_ephemeral {
        consider_ephemeral_join_candidates(
            &mut best,
            TransientJoinEstimate {
                left_rows,
                right_rows,
                distinct_keys: transient_distinct,
                key_parts: binding.key_parts.len(),
                is_i64,
                semantic_supported,
            },
        );
    }
    best.persisted_rejected = saw_persisted
        && !matches!(
            best.family,
            JoinAccessFamily::PersistedI64 | JoinAccessFamily::PersistedSemantic
        );
    Ok(best)
}

fn direct_join_access_decision(
    left: &Plan,
    right: &Plan,
    key: JoinKeySpec,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<JoinAccessDecision>, PhysicalExecutionError> {
    let Some((left_relation, left_layout)) = direct_scan_relation(left) else {
        return Ok(None);
    };
    let Some((right_relation, right_layout)) = direct_scan_relation(right) else {
        return Ok(None);
    };
    let left_rows = native_row_count(&store.installed(left_relation, left_layout)?.data);
    right_scan_join_access_decision(
        RightJoinAccessRequest {
            left_rows,
            right_relation,
            right_layout,
            right_column: key.right_column,
            equivalence: key.equivalence,
            allow_ephemeral: true,
        },
        store,
        context,
        registry,
    )
    .map(Some)
}

struct RightScanJoinInputs<'a> {
    left_rows: &'a [kernel_query::Row],
    right: &'a InstalledRelation,
    right_relation: SemanticId,
    right_layout: LayoutBinding,
    key: JoinKeySpec,
}

fn try_join_rows_with_persisted_i64(
    inputs: &RightScanJoinInputs<'_>,
    resolved: Option<&kernel_semantics::ResolvedPrimitiveEquivalence>,
    store: &PhysicalStore,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let Some(resolved) = resolved else {
        return Ok(None);
    };
    if !matches!(
        resolved.bind_right(&Value::I64(0)),
        Ok(kernel_semantics::BoundPrimitivePredicate::I64(_))
    ) {
        return Ok(None);
    }
    let Some(index) = store.i64_index(I64IndexBinding {
        relation: inputs.right_relation,
        layout: inputs.right_layout,
        key_column: inputs.key.right_column,
        equivalence: inputs.key.equivalence,
    }) else {
        return Ok(None);
    };
    if SemanticAccessCostModel::choose_join(
        inputs.left_rows.len(),
        native_row_count(&inputs.right.data),
        index.distinct_key_count(),
    ) == SemanticAccessPath::FullScan
    {
        stats.persisted_index_cost_rejections =
            stats.persisted_index_cost_rejections.saturating_add(1);
        return Ok(None);
    }

    let mut out = Vec::new();
    for left_row in inputs.left_rows {
        let Some(Value::I64(key)) = left_row.get(inputs.key.left_column) else {
            return Err(RelQueryError::ColumnOutOfBounds.into());
        };
        stats.scanned_rows = stats.scanned_rows.saturating_add(1);
        stats.values_read = stats.values_read.saturating_add(1);
        if let Some(right_ids) = index.probe(*key) {
            for right_id in right_ids {
                let position = inputs
                    .right
                    .position(*right_id)
                    .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
                let right_row = materialize_native_row(&inputs.right.data, position)?;
                let mut row = left_row.clone();
                row.extend(right_row);
                stats.values_read = stats.values_read.saturating_add(row.len());
                out.push(row);
            }
        }
    }
    stats.persisted_index_hits = stats.persisted_index_hits.saturating_add(1);
    Ok(Some(out))
}

fn try_join_rows_with_persisted_semantic(
    inputs: &RightScanJoinInputs<'_>,
    resolved: Option<&kernel_semantics::ResolvedPrimitiveEquivalence>,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let binding = SemanticIndexBinding::single(
        inputs.right_relation,
        inputs.right_layout,
        inputs.key.right_column,
        inputs.key.equivalence,
    );
    let Some(index) = store.semantic_fiber_capability(&binding, context, registry)? else {
        return Ok(None);
    };
    let Some(resolved) = resolved else {
        return Ok(None);
    };
    if SemanticAccessCostModel::choose_join(
        inputs.left_rows.len(),
        native_row_count(&inputs.right.data),
        index.distinct_key_count(),
    ) == SemanticAccessPath::FullScan
    {
        stats.persisted_index_cost_rejections =
            stats.persisted_index_cost_rejections.saturating_add(1);
        return Ok(None);
    }

    let mut out = Vec::new();
    for left_row in inputs.left_rows {
        let left_key = left_row
            .get(inputs.key.left_column)
            .ok_or(RelQueryError::ColumnOutOfBounds)?;
        stats.scanned_rows = stats.scanned_rows.saturating_add(1);
        stats.values_read = stats.values_read.saturating_add(1);
        if let Some(right_ids) = index.probe_values(&[left_key], context, registry)? {
            for right_id in right_ids {
                let position = inputs
                    .right
                    .position(right_id)
                    .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
                let right_row = materialize_native_row(&inputs.right.data, position)?;
                let right_key = right_row
                    .get(inputs.key.right_column)
                    .ok_or(RelQueryError::ColumnOutOfBounds)?;
                if !resolved.equivalent(left_key, right_key)? {
                    return Err(RelQueryError::InconsistentIncrementalDelta.into());
                }
                let mut row = left_row.clone();
                row.extend(right_row);
                stats.values_read = stats
                    .values_read
                    .saturating_add(row.len().saturating_add(1));
                out.push(row);
            }
        }
    }
    stats.persisted_index_hits = stats.persisted_index_hits.saturating_add(1);
    Ok(Some(out))
}

fn join_rows_with_ephemeral_i64(
    inputs: &RightScanJoinInputs<'_>,
    resolved: Option<&kernel_semantics::ResolvedPrimitiveEquivalence>,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let Some(resolved) = resolved else {
        return Ok(None);
    };
    if !matches!(
        resolved.bind_right(&Value::I64(0)),
        Ok(kernel_semantics::BoundPrimitivePredicate::I64(_))
    ) {
        return Ok(None);
    }
    let Some(right_keys) = native_i64_column(&inputs.right.data, inputs.key.right_column) else {
        return Ok(None);
    };
    let mut index = BTreeMap::<i64, Vec<usize>>::new();
    for position in inputs.right.scan_positions() {
        index
            .entry(right_keys[position])
            .or_default()
            .push(position);
    }
    stats.ephemeral_index_builds = stats.ephemeral_index_builds.saturating_add(1);
    if SemanticAccessCostModel::choose_ephemeral_join(
        inputs.left_rows.len(),
        right_keys.len(),
        index.len(),
        1,
    ) == SemanticAccessPath::FullScan
    {
        return Ok(None);
    }
    let mut out = Vec::new();
    for left_row in inputs.left_rows {
        let Some(Value::I64(key)) = left_row.get(inputs.key.left_column) else {
            return Err(RelQueryError::ColumnOutOfBounds.into());
        };
        stats.scanned_rows = stats.scanned_rows.saturating_add(1);
        stats.values_read = stats.values_read.saturating_add(1);
        if let Some(right_positions) = index.get(key) {
            for &position in right_positions {
                let right_row = materialize_native_row(&inputs.right.data, position)?;
                let mut row = left_row.clone();
                row.extend(right_row);
                stats.values_read = stats.values_read.saturating_add(row.len());
                out.push(row);
            }
        }
    }
    Ok(Some(out))
}

fn join_rows_with_ephemeral_semantic(
    inputs: &RightScanJoinInputs<'_>,
    resolved: Option<&kernel_semantics::ResolvedPrimitiveEquivalence>,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let Some(resolved) = resolved else {
        return Ok(None);
    };
    let binding = SemanticIndexBinding::single(
        inputs.right_relation,
        inputs.right_layout,
        inputs.key.right_column,
        inputs.key.equivalence,
    );
    if !primitive_binding_supported(&binding, context, registry)? {
        return Ok(None);
    }
    let index = MaterializedSemanticIndexState::build(binding, inputs.right, context, registry)?;
    stats.ephemeral_index_builds = stats.ephemeral_index_builds.saturating_add(1);
    if SemanticAccessCostModel::choose_ephemeral_join(
        inputs.left_rows.len(),
        native_row_count(&inputs.right.data),
        index.distinct_key_count(),
        1,
    ) == SemanticAccessPath::FullScan
    {
        return Ok(None);
    }
    let mut out = Vec::new();
    for left_row in inputs.left_rows {
        let left_key = left_row
            .get(inputs.key.left_column)
            .ok_or(RelQueryError::ColumnOutOfBounds)?;
        stats.scanned_rows = stats.scanned_rows.saturating_add(1);
        stats.values_read = stats.values_read.saturating_add(1);
        if let Some(right_ids) = index.probe_value(left_key, context, registry)? {
            for right_id in right_ids {
                let position = inputs
                    .right
                    .position(*right_id)
                    .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
                let right_row = materialize_native_row(&inputs.right.data, position)?;
                let right_key = right_row
                    .get(inputs.key.right_column)
                    .ok_or(RelQueryError::ColumnOutOfBounds)?;
                if !resolved.equivalent(left_key, right_key)? {
                    return Err(RelQueryError::InconsistentIncrementalDelta.into());
                }
                let mut row = left_row.clone();
                row.extend(right_row);
                stats.values_read = stats
                    .values_read
                    .saturating_add(row.len().saturating_add(1));
                out.push(row);
            }
        }
    }
    Ok(Some(out))
}

fn try_execute_indexed_right_scan_join_from_rows(
    left_rows: &[kernel_query::Row],
    right: &Plan,
    key: JoinKeySpec,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let Some((right_relation, right_layout)) = direct_scan_relation(right) else {
        return Ok(None);
    };
    let right_installed = store.installed(right_relation, right_layout)?;
    let resolved = registry.resolve_primitive_equivalence(context, key.equivalence)?;
    let inputs = RightScanJoinInputs {
        left_rows,
        right: right_installed,
        right_relation,
        right_layout,
        key,
    };
    let decision = right_scan_join_access_decision(
        RightJoinAccessRequest {
            left_rows: left_rows.len(),
            right_relation,
            right_layout,
            right_column: key.right_column,
            equivalence: key.equivalence,
            allow_ephemeral: true,
        },
        store,
        context,
        registry,
    )?;
    if decision.persisted_rejected {
        stats.persisted_index_cost_rejections =
            stats.persisted_index_cost_rejections.saturating_add(1);
    }
    match decision.family {
        JoinAccessFamily::FullScan => Ok(None),
        JoinAccessFamily::PersistedI64 => {
            try_join_rows_with_persisted_i64(&inputs, resolved.as_ref(), store, stats)
        }
        JoinAccessFamily::PersistedSemantic => try_join_rows_with_persisted_semantic(
            &inputs,
            resolved.as_ref(),
            store,
            context,
            registry,
            stats,
        ),
        JoinAccessFamily::EphemeralI64 => {
            join_rows_with_ephemeral_i64(&inputs, resolved.as_ref(), stats)
        }
        JoinAccessFamily::EphemeralSemantic => {
            join_rows_with_ephemeral_semantic(&inputs, resolved.as_ref(), context, registry, stats)
        }
    }
}

fn direct_columnar_scan(plan: &Plan) -> bool {
    matches!(
        plan,
        Plan::Scan {
            layout: LayoutBinding {
                family: LayoutFamily::Columnar,
                ..
            },
            ..
        }
    )
}

fn execute_project_plan(
    input: &Plan,
    columns: &[usize],
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    if let Some(rows) =
        try_execute_persisted_semantic_multi_key_join_plan(input, store, context, registry, stats)?
    {
        return project_rows(rows, columns, stats);
    }
    if let Plan::JoinEq {
        left,
        right,
        left_column,
        right_column,
        equivalence,
        algorithm: JoinAlgorithm::IndexedPrimitiveIfAvailable,
    } = input
    {
        let key = JoinKeySpec {
            left_column: *left_column,
            right_column: *right_column,
            equivalence: *equivalence,
        };
        if let Some(decision) =
            direct_join_access_decision(left, right, key, store, context, registry)?
        {
            match decision.family {
                JoinAccessFamily::PersistedSemantic => {
                    if let Some(rows) = try_execute_persisted_semantic_join(
                        left,
                        right,
                        *left_column,
                        *right_column,
                        *equivalence,
                        store,
                        context,
                        registry,
                        stats,
                    )? {
                        return project_rows(rows, columns, stats);
                    }
                }
                JoinAccessFamily::PersistedI64 | JoinAccessFamily::EphemeralI64 => {
                    if let Some(rows) = try_execute_indexed_i64_join_project(
                        left,
                        right,
                        *left_column,
                        *right_column,
                        *equivalence,
                        columns,
                        store,
                        context,
                        registry,
                        stats,
                    )? {
                        return Ok(rows);
                    }
                }
                JoinAccessFamily::FullScan | JoinAccessFamily::EphemeralSemantic => {}
            }
        }
    }
    if let Some(rows) =
        try_execute_persisted_semantic_filter_plan(input, store, context, registry, stats)?
    {
        return project_rows(rows, columns, stats);
    }
    if let Plan::FilterEqConst {
        input: filter_input,
        column,
        value,
        equivalence,
    } = input
        && let Plan::Scan {
            relation,
            layout,
            algorithm: ScanAlgorithm::FullScan,
        } = filter_input.as_ref()
    {
        return execute_fused_filter_project_scan(
            store,
            *relation,
            *layout,
            *column,
            value,
            *equivalence,
            columns,
            context,
            registry,
            stats,
        );
    }
    let input_rows = input.execute_native_rows(store, context, registry, stats)?;
    project_rows(input_rows, columns, stats)
}

#[allow(clippy::too_many_arguments, clippy::too_many_lines)]
fn try_execute_indexed_i64_join_project(
    left: &Plan,
    right: &Plan,
    left_column: usize,
    right_column: usize,
    equivalence: SemanticId,
    projection: &[usize],
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let Some((left_relation, left_layout)) = direct_scan_relation(left) else {
        return Ok(None);
    };
    let Some((right_relation, right_layout)) = direct_scan_relation(right) else {
        return Ok(None);
    };
    let Some(resolved) = registry.resolve_primitive_equivalence(context, equivalence)? else {
        return Ok(None);
    };
    if !matches!(
        resolved.bind_right(&Value::I64(0)),
        Ok(kernel_semantics::BoundPrimitivePredicate::I64(_))
    ) {
        return Ok(None);
    }

    let left_installed = store.installed(left_relation, left_layout)?;
    let right_installed = store.installed(right_relation, right_layout)?;
    let left_data = &left_installed.data;
    let right_data = &right_installed.data;
    validate_indexable_i64_relation(context, left_relation, left_data)?;
    validate_indexable_i64_relation(context, right_relation, right_data)?;
    let Some(left_columns) = native_all_i64_columns(left_data) else {
        return Ok(None);
    };
    let Some(right_columns) = native_all_i64_columns(right_data) else {
        return Ok(None);
    };
    let Some(left_keys) = left_columns.get(left_column).copied() else {
        return Ok(None);
    };
    let Some(right_keys) = right_columns.get(right_column).copied() else {
        return Ok(None);
    };
    let joined_width = left_columns.len().saturating_add(right_columns.len());
    if projection.iter().any(|column| *column >= joined_width) {
        return Err(RelQueryError::ColumnOutOfBounds.into());
    }

    let mut out = Vec::new();
    let mut push_projected = |left_index: usize, right_index: usize| {
        let mut row = Vec::with_capacity(projection.len());
        for &column in projection {
            let value = if column < left_columns.len() {
                left_columns[column][left_index]
            } else {
                right_columns[column - left_columns.len()][right_index]
            };
            row.push(Value::I64(value));
        }
        out.push(row);
    };

    if let Some(index) = store.i64_index(I64IndexBinding {
        relation: right_relation,
        layout: right_layout,
        key_column: right_column,
        equivalence,
    }) {
        if SemanticAccessCostModel::choose_join(
            left_keys.len(),
            right_keys.len(),
            index.distinct_key_count(),
        ) == SemanticAccessPath::FullScan
        {
            return Ok(None);
        }
        for left_index in left_installed.scan_positions() {
            if let Some(right_rows) = index.probe(left_keys[left_index]) {
                for right_row_id in right_rows {
                    let right_index = right_installed
                        .position(*right_row_id)
                        .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
                    push_projected(left_index, right_index);
                }
            }
        }
        stats.scanned_rows = stats.scanned_rows.saturating_add(left_keys.len());
        stats.values_read = stats.values_read.saturating_add(
            left_keys
                .len()
                .saturating_add(out.len().saturating_mul(projection.len())),
        );
        stats.persisted_index_hits = stats.persisted_index_hits.saturating_add(1);
        stats.fused_join_project_hits = stats.fused_join_project_hits.saturating_add(1);
        return Ok(Some(out));
    }

    if SemanticAccessCostModel::choose_ephemeral_join(
        left_keys.len(),
        right_keys.len(),
        right_keys.len(),
        1,
    ) == SemanticAccessPath::FullScan
    {
        return Ok(None);
    }
    let mut right_index: BTreeMap<i64, Vec<usize>> = BTreeMap::new();
    for row_index in right_installed.scan_positions() {
        right_index
            .entry(right_keys[row_index])
            .or_default()
            .push(row_index);
    }
    if SemanticAccessCostModel::choose_ephemeral_join(
        left_keys.len(),
        right_keys.len(),
        right_index.len(),
        1,
    ) == SemanticAccessPath::FullScan
    {
        return Ok(None);
    }
    for left_index in left_installed.scan_positions() {
        if let Some(right_rows) = right_index.get(&left_keys[left_index]) {
            for &right_index in right_rows {
                push_projected(left_index, right_index);
            }
        }
    }
    stats.scanned_rows = stats
        .scanned_rows
        .saturating_add(left_keys.len().saturating_add(right_keys.len()));
    stats.values_read = stats.values_read.saturating_add(
        left_keys
            .len()
            .saturating_add(right_keys.len())
            .saturating_add(out.len().saturating_mul(projection.len())),
    );
    stats.ephemeral_index_builds = stats.ephemeral_index_builds.saturating_add(1);
    stats.fused_join_project_hits = stats.fused_join_project_hits.saturating_add(1);
    Ok(Some(out))
}

fn scan_rows(
    store: &PhysicalStore,
    relation: SemanticId,
    layout: LayoutBinding,
    context: &kernel_schema::SemanticContext,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let installed = store.installed(relation, layout)?;
    if !installed.scan_order_is_physical {
        let row_count = installed.scan_positions().count();
        stats.scanned_rows = stats.scanned_rows.saturating_add(row_count);
        stats.values_read = stats
            .values_read
            .saturating_add(native_column_count(&installed.data).saturating_mul(row_count));
        let mut rows = Vec::with_capacity(row_count);
        for position in installed.scan_positions() {
            rows.push(materialize_native_row(&installed.data, position)?);
        }
        return Ok(rows);
    }
    match &installed.data {
        NativeRelation::RowStore(rows) => {
            stats.scanned_rows = stats.scanned_rows.saturating_add(rows.len());
            stats.values_read = stats
                .values_read
                .saturating_add(rows.iter().map(Vec::len).sum::<usize>());
            Ok(rows.clone())
        }
        NativeRelation::Columnar { columns, row_count } => {
            stats.scanned_rows = stats.scanned_rows.saturating_add(*row_count);
            stats.values_read = stats
                .values_read
                .saturating_add(columns.len().saturating_mul(*row_count));
            let mut rows = Vec::with_capacity(*row_count);
            for row_index in 0..*row_count {
                rows.push(
                    columns
                        .iter()
                        .map(|column| column[row_index].clone())
                        .collect(),
                );
            }
            Ok(rows)
        }
        NativeRelation::I64Columnar { columns, row_count } => {
            validate_i64_columnar_schema(context, relation, columns.len())?;
            stats.scanned_rows = stats.scanned_rows.saturating_add(*row_count);
            stats.values_read = stats
                .values_read
                .saturating_add(columns.len().saturating_mul(*row_count));
            let mut rows = Vec::with_capacity(*row_count);
            for row_index in 0..*row_count {
                rows.push(
                    columns
                        .iter()
                        .map(|column| Value::I64(column[row_index]))
                        .collect(),
                );
            }
            Ok(rows)
        }
        NativeRelation::TypedColumnar { columns, row_count } => {
            validate_typed_columnar_schema(context, relation, columns)?;
            stats.scanned_rows = stats.scanned_rows.saturating_add(*row_count);
            stats.values_read = stats
                .values_read
                .saturating_add(columns.len().saturating_mul(*row_count));
            let mut rows = Vec::with_capacity(*row_count);
            for row_index in 0..*row_count {
                rows.push(
                    columns
                        .iter()
                        .map(|column| column.value_at(row_index))
                        .collect(),
                );
            }
            Ok(rows)
        }
    }
}

fn validate_i64_columnar_schema(
    context: &kernel_schema::SemanticContext,
    relation: SemanticId,
    column_count: usize,
) -> Result<(), PhysicalExecutionError> {
    let definition = context
        .schema
        .relation(relation)
        .ok_or(RelQueryError::UnknownRelation(relation))?;
    if definition.columns.len() != column_count
        || definition.columns.iter().any(|column| {
            !matches!(
                column,
                kernel_schema::TypeExpr::Scalar(kernel_schema::ScalarType::I64)
            )
        })
    {
        return Err(PhysicalExecutionError::PhysicalTypeMismatch);
    }
    Ok(())
}

fn validate_typed_columnar_schema(
    context: &kernel_schema::SemanticContext,
    relation: SemanticId,
    columns: &[NativeColumn],
) -> Result<(), PhysicalExecutionError> {
    let definition = context
        .schema
        .relation(relation)
        .ok_or(RelQueryError::UnknownRelation(relation))?;
    if definition.columns.len() != columns.len() {
        return Err(PhysicalExecutionError::PhysicalTypeMismatch);
    }
    for (logical, physical) in definition.columns.iter().zip(columns) {
        if !native_column_matches_type(logical, physical) {
            return Err(PhysicalExecutionError::PhysicalTypeMismatch);
        }
    }
    Ok(())
}

fn native_column_matches_type(logical: &kernel_schema::TypeExpr, physical: &NativeColumn) -> bool {
    match (logical, physical) {
        (
            kernel_schema::TypeExpr::Scalar(kernel_schema::ScalarType::Unit),
            NativeColumn::Unit(_),
        )
        | (
            kernel_schema::TypeExpr::Scalar(kernel_schema::ScalarType::Bool),
            NativeColumn::Bool(_),
        )
        | (kernel_schema::TypeExpr::Scalar(kernel_schema::ScalarType::I64), NativeColumn::I64(_))
        | (
            kernel_schema::TypeExpr::Scalar(kernel_schema::ScalarType::F64),
            NativeColumn::F64Bits(_),
        )
        | (
            kernel_schema::TypeExpr::Scalar(kernel_schema::ScalarType::Text),
            NativeColumn::Text(_),
        ) => true,
        (logical, NativeColumn::Algebraic(column)) => logical == column.ty(),
        (
            kernel_schema::TypeExpr::Scalar(kernel_schema::ScalarType::LiveEntityRef(logical_type)),
            NativeColumn::LiveEntityIds {
                entity_type: physical_type,
                ..
            }
            | NativeColumn::DenseLiveEntityIds {
                entity_type: physical_type,
                ..
            },
        )
        | (
            kernel_schema::TypeExpr::Scalar(kernel_schema::ScalarType::HistoricalEntityId(
                logical_type,
            )),
            NativeColumn::HistoricalEntityIds {
                entity_type: physical_type,
                ..
            },
        ) => logical_type == physical_type,
        _ => false,
    }
}

#[allow(clippy::too_many_arguments)]
fn execute_fused_filter_project_scan(
    store: &PhysicalStore,
    relation: SemanticId,
    layout: LayoutBinding,
    predicate_column: usize,
    predicate_value: &Value,
    equivalence: SemanticId,
    projection: &[usize],
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let installed = store.installed(relation, layout)?;
    if !installed.scan_order_is_physical {
        let rows = scan_rows(store, relation, layout, context, stats)?;
        let filtered = filter_rows(
            rows,
            predicate_column,
            predicate_value,
            equivalence,
            context,
            registry,
            stats,
        )?;
        return project_rows(filtered, projection, stats);
    }
    let resolved = registry.resolve_primitive_equivalence(context, equivalence)?;
    let bound = resolved
        .as_ref()
        .map(|resolved| resolved.bind_right(predicate_value))
        .transpose()?;
    match &installed.data {
        NativeRelation::I64Columnar { columns, row_count }
            if matches!(
                bound,
                Some(kernel_semantics::BoundPrimitivePredicate::I64(_))
            ) =>
        {
            execute_i64_fused(
                columns,
                *row_count,
                relation,
                predicate_column,
                projection,
                bound.as_ref(),
                context,
                stats,
            )
        }
        NativeRelation::Columnar { columns, row_count } => execute_value_columnar_fused(
            columns,
            *row_count,
            predicate_column,
            predicate_value,
            equivalence,
            projection,
            bound.as_ref(),
            resolved.as_ref(),
            context,
            registry,
            stats,
        ),
        NativeRelation::I64Columnar { columns, row_count } => execute_i64_generic_fused(
            columns,
            *row_count,
            relation,
            predicate_column,
            predicate_value,
            equivalence,
            projection,
            bound.as_ref(),
            resolved.as_ref(),
            context,
            registry,
            stats,
        ),
        NativeRelation::TypedColumnar { columns, row_count } => execute_typed_columnar_fused(
            columns,
            *row_count,
            relation,
            predicate_column,
            predicate_value,
            equivalence,
            projection,
            bound.as_ref(),
            context,
            registry,
            stats,
        ),
        NativeRelation::RowStore(rows) => execute_row_store_fused(
            rows,
            predicate_column,
            predicate_value,
            equivalence,
            projection,
            bound.as_ref(),
            resolved.as_ref(),
            context,
            registry,
            stats,
        ),
    }
}

#[allow(clippy::too_many_arguments)]
fn execute_typed_columnar_fused(
    columns: &[NativeColumn],
    row_count: usize,
    relation: SemanticId,
    predicate_column: usize,
    predicate_value: &Value,
    equivalence: SemanticId,
    projection: &[usize],
    bound: Option<&kernel_semantics::BoundPrimitivePredicate>,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    validate_typed_columnar_schema(context, relation, columns)?;
    let predicate = columns
        .get(predicate_column)
        .ok_or(RelQueryError::ColumnOutOfBounds)?;
    validate_projection(projection, columns.len())?;
    stats.scanned_rows = stats.scanned_rows.saturating_add(row_count);
    let rows = if let Some(bound) = bound {
        execute_bound_typed_filter(columns, predicate, bound, projection, row_count)?
    } else if let NativeColumn::Algebraic(column) = predicate {
        let request = AlgebraicFilterRequest {
            predicate_value,
            equivalence,
            projection,
            context,
            registry,
        };
        execute_algebraic_equivalence_filter(columns, column, row_count, &request)?
    } else {
        return Err(PhysicalExecutionError::PhysicalTypeMismatch);
    };
    account_fused_reads(stats, row_count, rows.len(), projection.len());
    Ok(rows)
}

struct AlgebraicFilterRequest<'a> {
    predicate_value: &'a Value,
    equivalence: SemanticId,
    projection: &'a [usize],
    context: &'a kernel_schema::SemanticContext,
    registry: &'a kernel_semantics::SemanticRegistry,
}

fn execute_algebraic_equivalence_filter(
    columns: &[NativeColumn],
    predicate: &algebraic_native::AlgebraicNativeColumn,
    row_count: usize,
    request: &AlgebraicFilterRequest<'_>,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let compiled = request
        .registry
        .compile_equivalence(request.context, request.equivalence)?;
    let expected = compiled.canonical_key(request.predicate_value)?;
    let mut matching = Vec::new();
    for row_index in 0..row_count {
        if predicate.canonical_key_at_compiled(row_index, &compiled)? == expected {
            matching.push(row_index);
        }
    }
    let mut rows = Vec::with_capacity(matching.len());
    push_typed_matches(&mut rows, columns, request.projection, matching);
    Ok(rows)
}

fn execute_bound_typed_filter(
    columns: &[NativeColumn],
    predicate: &NativeColumn,
    bound: &kernel_semantics::BoundPrimitivePredicate,
    projection: &[usize],
    row_count: usize,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let mut rows = Vec::new();
    match (predicate, bound) {
        (NativeColumn::Unit(_), kernel_semantics::BoundPrimitivePredicate::Unit) => {
            push_typed_matches(&mut rows, columns, projection, 0..row_count);
        }
        (NativeColumn::Bool(values), kernel_semantics::BoundPrimitivePredicate::Bool(expected)) => {
            push_typed_matches(
                &mut rows,
                columns,
                projection,
                matching_indices(values, |candidate| candidate == expected),
            );
        }
        (NativeColumn::I64(values), kernel_semantics::BoundPrimitivePredicate::I64(expected)) => {
            return Ok(execute_bound_i64_filter(
                columns, values, *expected, projection,
            ));
        }
        (
            NativeColumn::F64Bits(values),
            kernel_semantics::BoundPrimitivePredicate::F64Bits(expected),
        ) => push_typed_matches(
            &mut rows,
            columns,
            projection,
            matching_indices(values, |candidate| candidate == expected),
        ),
        (
            NativeColumn::Text(values),
            kernel_semantics::BoundPrimitivePredicate::TextExact(expected),
        ) => push_typed_matches(
            &mut rows,
            columns,
            projection,
            matching_indices(values, |candidate| candidate == expected),
        ),
        (
            NativeColumn::Text(values),
            kernel_semantics::BoundPrimitivePredicate::TextAsciiCaseInsensitive(expected),
        ) => push_typed_matches(
            &mut rows,
            columns,
            projection,
            matching_indices(values, |candidate| candidate.eq_ignore_ascii_case(expected)),
        ),
        (
            NativeColumn::LiveEntityIds {
                entity_type,
                values,
            },
            kernel_semantics::BoundPrimitivePredicate::LiveEntityId {
                entity_type: expected_type,
                id: expected,
            },
        ) if entity_type == expected_type => push_typed_matches(
            &mut rows,
            columns,
            projection,
            matching_indices(values, |candidate| candidate == expected),
        ),
        (
            NativeColumn::DenseLiveEntityIds {
                entity_type,
                ids,
                values,
            },
            kernel_semantics::BoundPrimitivePredicate::LiveEntityId {
                entity_type: expected_type,
                id: expected,
            },
        ) if entity_type == expected_type => {
            if let Some(expected) = ids.local(*expected) {
                push_typed_matches(
                    &mut rows,
                    columns,
                    projection,
                    matching_indices(values, |candidate| *candidate == expected),
                );
            }
        }
        (
            NativeColumn::HistoricalEntityIds {
                entity_type,
                values,
            },
            kernel_semantics::BoundPrimitivePredicate::HistoricalEntityId {
                entity_type: expected_type,
                id: expected,
            },
        ) if entity_type == expected_type => push_typed_matches(
            &mut rows,
            columns,
            projection,
            matching_indices(values, |candidate| candidate == expected),
        ),
        _ => return Err(PhysicalExecutionError::PhysicalTypeMismatch),
    }
    Ok(rows)
}

fn matching_indices<'a, T: 'a>(
    values: &'a [T],
    predicate: impl Fn(&T) -> bool + 'a,
) -> impl Iterator<Item = usize> + 'a {
    values
        .iter()
        .enumerate()
        .filter_map(move |(index, value)| predicate(value).then_some(index))
}

fn execute_bound_i64_filter(
    columns: &[NativeColumn],
    predicate: &[i64],
    expected: i64,
    projection: &[usize],
) -> Vec<kernel_query::Row> {
    let mut rows = Vec::new();
    if let [projected_column] = projection
        && let NativeColumn::I64(projected) = &columns[*projected_column]
    {
        for (row_index, candidate) in predicate.iter().enumerate() {
            if *candidate == expected {
                rows.push(vec![Value::I64(projected[row_index])]);
            }
        }
    } else {
        push_typed_matches(
            &mut rows,
            columns,
            projection,
            matching_indices(predicate, |candidate| *candidate == expected),
        );
    }
    rows
}

fn push_typed_matches(
    rows: &mut Vec<kernel_query::Row>,
    columns: &[NativeColumn],
    projection: &[usize],
    indices: impl IntoIterator<Item = usize>,
) {
    for row_index in indices {
        push_typed_projection(rows, columns, projection, row_index);
    }
}

fn push_typed_projection(
    rows: &mut Vec<kernel_query::Row>,
    columns: &[NativeColumn],
    projection: &[usize],
    row_index: usize,
) {
    rows.push(
        projection
            .iter()
            .map(|column| columns[*column].value_at(row_index))
            .collect(),
    );
}

#[allow(clippy::too_many_arguments)]
fn execute_i64_fused(
    columns: &[Vec<i64>],
    row_count: usize,
    relation: SemanticId,
    predicate_column: usize,
    projection: &[usize],
    bound: Option<&kernel_semantics::BoundPrimitivePredicate>,
    context: &kernel_schema::SemanticContext,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    validate_i64_columnar_schema(context, relation, columns.len())?;
    let Some(kernel_semantics::BoundPrimitivePredicate::I64(expected)) = bound else {
        return Err(PhysicalExecutionError::PhysicalTypeMismatch);
    };
    let predicate_values = columns
        .get(predicate_column)
        .ok_or(RelQueryError::ColumnOutOfBounds)?;
    validate_projection(projection, columns.len())?;
    stats.scanned_rows = stats.scanned_rows.saturating_add(row_count);
    let mut rows = Vec::new();
    if let [projected_column] = projection {
        let projected_values = &columns[*projected_column];
        for row_index in 0..row_count {
            if predicate_values[row_index] == *expected {
                rows.push(vec![Value::I64(projected_values[row_index])]);
            }
        }
    } else {
        for row_index in 0..row_count {
            if predicate_values[row_index] == *expected {
                rows.push(
                    projection
                        .iter()
                        .map(|column| Value::I64(columns[*column][row_index]))
                        .collect(),
                );
            }
        }
    }
    account_fused_reads(stats, row_count, rows.len(), projection.len());
    Ok(rows)
}

#[allow(clippy::too_many_arguments)]
fn execute_value_columnar_fused(
    columns: &[Vec<Value>],
    row_count: usize,
    predicate_column: usize,
    predicate_value: &Value,
    equivalence: SemanticId,
    projection: &[usize],
    bound: Option<&kernel_semantics::BoundPrimitivePredicate>,
    resolved: Option<&kernel_semantics::ResolvedPrimitiveEquivalence>,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let predicate_values = columns
        .get(predicate_column)
        .ok_or(RelQueryError::ColumnOutOfBounds)?;
    validate_projection(projection, columns.len())?;
    stats.scanned_rows = stats.scanned_rows.saturating_add(row_count);
    let mut rows = Vec::new();
    for row_index in 0..row_count {
        if matches_bound_or_resolved(
            bound,
            resolved,
            registry,
            context,
            equivalence,
            &predicate_values[row_index],
            predicate_value,
        )? {
            rows.push(
                projection
                    .iter()
                    .map(|column| columns[*column][row_index].clone())
                    .collect(),
            );
        }
    }
    account_fused_reads(stats, row_count, rows.len(), projection.len());
    Ok(rows)
}

#[allow(clippy::too_many_arguments)]
fn execute_i64_generic_fused(
    columns: &[Vec<i64>],
    row_count: usize,
    relation: SemanticId,
    predicate_column: usize,
    predicate_value: &Value,
    equivalence: SemanticId,
    projection: &[usize],
    bound: Option<&kernel_semantics::BoundPrimitivePredicate>,
    resolved: Option<&kernel_semantics::ResolvedPrimitiveEquivalence>,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    validate_i64_columnar_schema(context, relation, columns.len())?;
    let predicate_values = columns
        .get(predicate_column)
        .ok_or(RelQueryError::ColumnOutOfBounds)?;
    validate_projection(projection, columns.len())?;
    stats.scanned_rows = stats.scanned_rows.saturating_add(row_count);
    let mut rows = Vec::new();
    for row_index in 0..row_count {
        let candidate = Value::I64(predicate_values[row_index]);
        if matches_bound_or_resolved(
            bound,
            resolved,
            registry,
            context,
            equivalence,
            &candidate,
            predicate_value,
        )? {
            rows.push(
                projection
                    .iter()
                    .map(|column| Value::I64(columns[*column][row_index]))
                    .collect(),
            );
        }
    }
    account_fused_reads(stats, row_count, rows.len(), projection.len());
    Ok(rows)
}

#[allow(clippy::too_many_arguments)]
fn execute_row_store_fused(
    rows: &[kernel_query::Row],
    predicate_column: usize,
    predicate_value: &Value,
    equivalence: SemanticId,
    projection: &[usize],
    bound: Option<&kernel_semantics::BoundPrimitivePredicate>,
    resolved: Option<&kernel_semantics::ResolvedPrimitiveEquivalence>,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    stats.scanned_rows = stats.scanned_rows.saturating_add(rows.len());
    let mut out = Vec::new();
    for source in rows {
        let candidate = source
            .get(predicate_column)
            .ok_or(RelQueryError::ColumnOutOfBounds)?;
        if matches_bound_or_resolved(
            bound,
            resolved,
            registry,
            context,
            equivalence,
            candidate,
            predicate_value,
        )? {
            out.push(
                projection
                    .iter()
                    .map(|column| {
                        source
                            .get(*column)
                            .cloned()
                            .ok_or(RelQueryError::ColumnOutOfBounds)
                    })
                    .collect::<Result<Vec<_>, _>>()?,
            );
        }
    }
    account_fused_reads(stats, rows.len(), out.len(), projection.len());
    Ok(out)
}

fn validate_projection(
    projection: &[usize],
    column_count: usize,
) -> Result<(), PhysicalExecutionError> {
    if projection.iter().any(|column| *column >= column_count) {
        return Err(RelQueryError::ColumnOutOfBounds.into());
    }
    Ok(())
}

fn account_fused_reads(
    stats: &mut ExecutionStats,
    row_count: usize,
    output_rows: usize,
    projection_width: usize,
) {
    stats.values_read = stats
        .values_read
        .saturating_add(row_count.saturating_add(output_rows.saturating_mul(projection_width)));
}

fn matches_bound_or_resolved(
    bound: Option<&kernel_semantics::BoundPrimitivePredicate>,
    resolved: Option<&kernel_semantics::ResolvedPrimitiveEquivalence>,
    registry: &kernel_semantics::SemanticRegistry,
    context: &kernel_schema::SemanticContext,
    equivalence: SemanticId,
    left: &Value,
    right: &Value,
) -> Result<bool, PhysicalExecutionError> {
    if let Some(bound) = bound {
        return Ok(bound.matches(left));
    }
    match resolved {
        Some(resolved) => Ok(resolved.equivalent(left, right)?),
        None => Ok(registry.equivalent(context, equivalence, left, right)?),
    }
}

fn filter_rows(
    rows: Vec<kernel_query::Row>,
    column: usize,
    value: &Value,
    equivalence: SemanticId,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let resolved = registry.resolve_primitive_equivalence(context, equivalence)?;
    let bound = resolved
        .as_ref()
        .map(|resolved| resolved.bind_right(value))
        .transpose()?;
    let mut out = Vec::new();
    for row in rows {
        let candidate = row.get(column).ok_or(RelQueryError::ColumnOutOfBounds)?;
        stats.values_read = stats.values_read.saturating_add(1);
        if matches_bound_or_resolved(
            bound.as_ref(),
            resolved.as_ref(),
            registry,
            context,
            equivalence,
            candidate,
            value,
        )? {
            out.push(row);
        }
    }
    Ok(out)
}

fn filter_rows_columns(
    rows: Vec<kernel_query::Row>,
    left_column: usize,
    right_column: usize,
    equivalence: SemanticId,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let resolved = registry.resolve_primitive_equivalence(context, equivalence)?;
    let mut out = Vec::new();
    for row in rows {
        let left = row
            .get(left_column)
            .ok_or(RelQueryError::ColumnOutOfBounds)?;
        let right = row
            .get(right_column)
            .ok_or(RelQueryError::ColumnOutOfBounds)?;
        stats.values_read = stats.values_read.saturating_add(2);
        let matched = if let Some(resolved) = &resolved {
            resolved.equivalent(left, right)?
        } else {
            registry.equivalent(context, equivalence, left, right)?
        };
        if matched {
            out.push(row);
        }
    }
    Ok(out)
}

fn project_rows(
    rows: Vec<kernel_query::Row>,
    columns: &[usize],
    stats: &mut ExecutionStats,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let mut out = Vec::with_capacity(rows.len());
    for row in rows {
        let mut projected = Vec::with_capacity(columns.len());
        for &column in columns {
            projected.push(
                row.get(column)
                    .ok_or(RelQueryError::ColumnOutOfBounds)?
                    .clone(),
            );
            stats.values_read = stats.values_read.saturating_add(1);
        }
        out.push(projected);
    }
    Ok(out)
}

fn distinct_rows(
    rows: Vec<kernel_query::Row>,
    equivalences: &[SemanticId],
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let mut unique: Vec<kernel_query::Row> = Vec::new();
    'candidate: for row in rows {
        for existing in &unique {
            if semantic_rows_equal(&row, existing, equivalences, context, registry)? {
                continue 'candidate;
            }
        }
        unique.push(row);
    }
    Ok(unique)
}

fn join_rows(
    left_rows: &[kernel_query::Row],
    right_rows: &[kernel_query::Row],
    left_column: usize,
    right_column: usize,
    equivalence: SemanticId,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Vec<kernel_query::Row>, PhysicalExecutionError> {
    let resolved = registry.resolve_primitive_equivalence(context, equivalence)?;
    let mut out = Vec::new();
    for left in left_rows {
        let left_key = left
            .get(left_column)
            .ok_or(RelQueryError::ColumnOutOfBounds)?;
        for right in right_rows {
            let right_key = right
                .get(right_column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            if matches_bound_or_resolved(
                None,
                resolved.as_ref(),
                registry,
                context,
                equivalence,
                left_key,
                right_key,
            )? {
                let mut row = Vec::with_capacity(left.len() + right.len());
                row.extend(left.iter().cloned());
                row.extend(right.iter().cloned());
                out.push(row);
            }
        }
    }
    Ok(out)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct CompositeJoinKey {
    left_column: usize,
    right_column: usize,
    equivalence: SemanticId,
}

#[derive(Debug, Clone, Copy)]
struct JoinedColumnPredicate {
    first_column: usize,
    second_column: usize,
    equivalence: SemanticId,
}

struct DirectMultiKeyJoin<'a> {
    left: &'a Plan,
    right: &'a Plan,
    base_key: CompositeJoinKey,
    extra_predicates: Vec<JoinedColumnPredicate>,
}

fn collect_direct_multi_key_join(plan: &Plan) -> Option<DirectMultiKeyJoin<'_>> {
    let mut cursor = plan;
    let mut extra_predicates = Vec::new();
    while let Plan::FilterEqColumns {
        input,
        left_column,
        right_column,
        equivalence,
    } = cursor
    {
        extra_predicates.push(JoinedColumnPredicate {
            first_column: *left_column,
            second_column: *right_column,
            equivalence: *equivalence,
        });
        cursor = input;
    }
    let Plan::JoinEq {
        left,
        right,
        left_column,
        right_column,
        equivalence,
        algorithm: JoinAlgorithm::IndexedPrimitiveIfAvailable,
    } = cursor
    else {
        return None;
    };
    if extra_predicates.is_empty() {
        return None;
    }
    Some(DirectMultiKeyJoin {
        left,
        right,
        base_key: CompositeJoinKey {
            left_column: *left_column,
            right_column: *right_column,
            equivalence: *equivalence,
        },
        extra_predicates,
    })
}

fn normalize_join_column_predicates(
    join: &DirectMultiKeyJoin<'_>,
    left_width: usize,
    right_width: usize,
) -> Option<Vec<CompositeJoinKey>> {
    let total_width = left_width.checked_add(right_width)?;
    let mut keys = Vec::with_capacity(join.extra_predicates.len().saturating_add(1));
    keys.push(join.base_key);
    for predicate in &join.extra_predicates {
        if predicate.first_column >= total_width || predicate.second_column >= total_width {
            return None;
        }
        let key = match (
            predicate.first_column < left_width,
            predicate.second_column < left_width,
        ) {
            (true, false) => CompositeJoinKey {
                left_column: predicate.first_column,
                right_column: predicate.second_column - left_width,
                equivalence: predicate.equivalence,
            },
            (false, true) => CompositeJoinKey {
                left_column: predicate.second_column,
                right_column: predicate.first_column - left_width,
                equivalence: predicate.equivalence,
            },
            (true, true) | (false, false) => return None,
        };
        if key.right_column >= right_width {
            return None;
        }
        keys.push(key);
    }
    Some(keys)
}

fn binding_join_key_order(
    binding: &SemanticIndexBinding,
    keys: &[CompositeJoinKey],
) -> Option<Vec<usize>> {
    if binding.key_parts.len() != keys.len() {
        return None;
    }
    let mut used = vec![false; keys.len()];
    let mut order = Vec::with_capacity(keys.len());
    for part in &binding.key_parts {
        let (index, _) = keys.iter().enumerate().find(|(index, key)| {
            !used[*index] && key.right_column == part.column && key.equivalence == part.equivalence
        })?;
        used[index] = true;
        order.push(index);
    }
    Some(order)
}

fn try_execute_persisted_semantic_multi_key_join_plan(
    plan: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let Some(join) = collect_direct_multi_key_join(plan) else {
        return Ok(None);
    };
    let Some((left_relation, left_layout)) = direct_scan_relation(join.left) else {
        return Ok(None);
    };
    let Some((right_relation, right_layout)) = direct_scan_relation(join.right) else {
        return Ok(None);
    };
    let left_installed = store.installed(left_relation, left_layout)?;
    let right_installed = store.installed(right_relation, right_layout)?;
    let left_width = native_column_count(&left_installed.data);
    let right_width = native_column_count(&right_installed.data);
    let Some(keys) = normalize_join_column_predicates(&join, left_width, right_width) else {
        return Ok(None);
    };
    if keys.len() < 2 {
        return Ok(None);
    }

    let mut candidate = None;
    for (binding, index) in store.semantic_indexes.iter() {
        if binding.relation != right_relation || binding.layout != right_layout {
            continue;
        }
        let Some(order) = binding_join_key_order(binding, &keys) else {
            continue;
        };
        if !index.compatible_with(context, registry)? {
            continue;
        }
        candidate = Some((index, order));
        break;
    }
    let Some((index, key_order)) = candidate else {
        return Ok(None);
    };

    if SemanticAccessCostModel::choose_join(
        native_row_count(&left_installed.data),
        native_row_count(&right_installed.data),
        index.distinct_key_count(),
    ) == SemanticAccessPath::FullScan
    {
        stats.persisted_index_cost_rejections =
            stats.persisted_index_cost_rejections.saturating_add(1);
        return Ok(None);
    }

    let mut out = Vec::new();
    for left_position in left_installed.scan_positions() {
        let left_row = materialize_native_row(&left_installed.data, left_position)?;
        let mut values = Vec::with_capacity(key_order.len());
        for &key_index in &key_order {
            let key = keys[key_index];
            values.push(
                left_row
                    .get(key.left_column)
                    .ok_or(RelQueryError::ColumnOutOfBounds)?,
            );
        }
        stats.scanned_rows = stats.scanned_rows.saturating_add(1);
        stats.values_read = stats.values_read.saturating_add(values.len());
        if let Some(right_ids) = index.probe_values(&values, context, registry)? {
            for right_id in right_ids {
                let right_position = right_installed
                    .position(*right_id)
                    .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
                let right_row = materialize_native_row(&right_installed.data, right_position)?;
                for key in &keys {
                    let left_value = left_row
                        .get(key.left_column)
                        .ok_or(RelQueryError::ColumnOutOfBounds)?;
                    let right_value = right_row
                        .get(key.right_column)
                        .ok_or(RelQueryError::ColumnOutOfBounds)?;
                    stats.values_read = stats.values_read.saturating_add(2);
                    if !registry.equivalent(context, key.equivalence, left_value, right_value)? {
                        return Err(RelQueryError::InconsistentIncrementalDelta.into());
                    }
                }
                let mut row = left_row.clone();
                row.extend(right_row);
                stats.values_read = stats.values_read.saturating_add(row.len());
                out.push(row);
            }
        }
    }
    stats.persisted_index_hits = stats.persisted_index_hits.saturating_add(1);
    Ok(Some(out))
}

#[allow(clippy::too_many_arguments)]
fn try_execute_persisted_semantic_join(
    left: &Plan,
    right: &Plan,
    left_column: usize,
    right_column: usize,
    equivalence: SemanticId,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let Some((left_relation, left_layout)) = direct_scan_relation(left) else {
        return Ok(None);
    };
    let Some((right_relation, right_layout)) = direct_scan_relation(right) else {
        return Ok(None);
    };
    let Some(resolved) = registry.resolve_primitive_equivalence(context, equivalence)? else {
        return Ok(None);
    };
    let binding =
        SemanticIndexBinding::single(right_relation, right_layout, right_column, equivalence);
    let Some(index) = store.semantic_fiber_capability(&binding, context, registry)? else {
        return Ok(None);
    };
    let left_installed = store.installed(left_relation, left_layout)?;
    let right_installed = store.installed(right_relation, right_layout)?;
    if SemanticAccessCostModel::choose_join(
        native_row_count(&left_installed.data),
        native_row_count(&right_installed.data),
        index.distinct_key_count(),
    ) == SemanticAccessPath::FullScan
    {
        stats.persisted_index_cost_rejections =
            stats.persisted_index_cost_rejections.saturating_add(1);
        return Ok(None);
    }
    let mut out = Vec::new();
    for left_position in left_installed.scan_positions() {
        let left_row = materialize_native_row(&left_installed.data, left_position)?;
        let left_key = left_row
            .get(left_column)
            .ok_or(RelQueryError::ColumnOutOfBounds)?;
        stats.scanned_rows = stats.scanned_rows.saturating_add(1);
        stats.values_read = stats.values_read.saturating_add(1);
        if let Some(right_ids) = index.probe_values(&[left_key], context, registry)? {
            for right_id in right_ids {
                let right_position = right_installed
                    .position(right_id)
                    .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
                let right_row = materialize_native_row(&right_installed.data, right_position)?;
                let right_key = right_row
                    .get(right_column)
                    .ok_or(RelQueryError::ColumnOutOfBounds)?;
                if !resolved.equivalent(left_key, right_key)? {
                    return Err(RelQueryError::InconsistentIncrementalDelta.into());
                }
                let mut row = left_row.clone();
                row.extend(right_row);
                stats.values_read = stats
                    .values_read
                    .saturating_add(row.len().saturating_add(1));
                out.push(row);
            }
        }
    }
    stats.persisted_index_hits = stats.persisted_index_hits.saturating_add(1);
    Ok(Some(out))
}

fn try_execute_ephemeral_semantic_join(
    left: &Plan,
    right: &Plan,
    key: JoinKeySpec,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let Some((left_relation, left_layout)) = direct_scan_relation(left) else {
        return Ok(None);
    };
    let Some((right_relation, right_layout)) = direct_scan_relation(right) else {
        return Ok(None);
    };
    let binding = SemanticIndexBinding::single(
        right_relation,
        right_layout,
        key.right_column,
        key.equivalence,
    );
    if !primitive_binding_supported(&binding, context, registry)? {
        return Ok(None);
    }
    if store
        .semantic_fiber_capability(&binding, context, registry)?
        .is_some()
    {
        return Ok(None);
    }
    let resolved = registry
        .resolve_primitive_equivalence(context, key.equivalence)?
        .ok_or(PhysicalExecutionError::PhysicalTypeMismatch)?;
    if matches!(
        resolved.bind_right(&Value::I64(0)),
        Ok(kernel_semantics::BoundPrimitivePredicate::I64(_))
    ) && store
        .i64_index(I64IndexBinding {
            relation: right_relation,
            layout: right_layout,
            key_column: key.right_column,
            equivalence: key.equivalence,
        })
        .is_some()
    {
        return Ok(None);
    }
    let left_installed = store.installed(left_relation, left_layout)?;
    let right_installed = store.installed(right_relation, right_layout)?;
    let left_rows = native_row_count(&left_installed.data);
    let right_rows = native_row_count(&right_installed.data);
    if SemanticAccessCostModel::choose_ephemeral_join(left_rows, right_rows, right_rows, 1)
        == SemanticAccessPath::FullScan
    {
        return Ok(None);
    }
    let transient_index =
        MaterializedSemanticIndexState::build(binding, right_installed, context, registry)?;
    stats.ephemeral_index_builds = stats.ephemeral_index_builds.saturating_add(1);
    if SemanticAccessCostModel::choose_ephemeral_join(
        left_rows,
        right_rows,
        transient_index.distinct_key_count(),
        1,
    ) == SemanticAccessPath::FullScan
    {
        stats.persisted_index_cost_rejections =
            stats.persisted_index_cost_rejections.saturating_add(1);
        return Ok(None);
    }
    let mut out = Vec::new();
    for left_position in left_installed.scan_positions() {
        let left_row = materialize_native_row(&left_installed.data, left_position)?;
        let left_key = left_row
            .get(key.left_column)
            .ok_or(RelQueryError::ColumnOutOfBounds)?;
        stats.scanned_rows = stats.scanned_rows.saturating_add(1);
        stats.values_read = stats.values_read.saturating_add(1);
        if let Some(right_ids) = transient_index.probe_value(left_key, context, registry)? {
            for right_id in right_ids {
                let right_position = right_installed
                    .position(*right_id)
                    .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
                let right_row = materialize_native_row(&right_installed.data, right_position)?;
                let right_key = right_row
                    .get(key.right_column)
                    .ok_or(RelQueryError::ColumnOutOfBounds)?;
                if !resolved.equivalent(left_key, right_key)? {
                    return Err(RelQueryError::InconsistentIncrementalDelta.into());
                }
                let mut row = left_row.clone();
                row.extend(right_row);
                stats.values_read = stats
                    .values_read
                    .saturating_add(row.len().saturating_add(1));
                out.push(row);
            }
        }
    }
    Ok(Some(out))
}

struct DirectI64JoinInputs<'a> {
    left: &'a InstalledRelation,
    right: &'a InstalledRelation,
    left_keys: &'a [i64],
    right_column: usize,
}

fn execute_persisted_i64_join(
    inputs: &DirectI64JoinInputs<'_>,
    index: &MaterializedI64IndexState,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let left_data = &inputs.left.data;
    let right_data = &inputs.right.data;
    if SemanticAccessCostModel::choose_join(
        inputs.left_keys.len(),
        native_row_count(right_data),
        index.distinct_key_count(),
    ) == SemanticAccessPath::FullScan
    {
        stats.persisted_index_cost_rejections =
            stats.persisted_index_cost_rejections.saturating_add(1);
        return Ok(None);
    }
    let left_i64_columns = native_all_i64_columns(left_data);
    let right_i64_columns = native_all_i64_columns(right_data);
    let mut out = Vec::with_capacity(inputs.left_keys.len());
    for left_index in inputs.left.scan_positions() {
        let key = inputs.left_keys[left_index];
        if let Some(right_rows) = index.probe(key) {
            for right_row_id in right_rows {
                let right_index = inputs
                    .right
                    .position(*right_row_id)
                    .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
                let mut row = Vec::with_capacity(
                    native_column_count(left_data).saturating_add(native_column_count(right_data)),
                );
                if let (Some(left_columns), Some(right_columns)) =
                    (&left_i64_columns, &right_i64_columns)
                {
                    append_i64_row_values(&mut row, left_columns, left_index);
                    append_i64_row_values(&mut row, right_columns, right_index);
                } else {
                    append_native_row_values(&mut row, left_data, left_index)?;
                    append_native_row_values(&mut row, right_data, right_index)?;
                }
                out.push(row);
            }
        }
    }
    stats.scanned_rows = stats.scanned_rows.saturating_add(inputs.left_keys.len());
    account_join_reads(
        stats,
        inputs.left_keys.len(),
        0,
        out.len(),
        left_data,
        right_data,
    );
    stats.persisted_index_hits = stats.persisted_index_hits.saturating_add(1);
    Ok(Some(out))
}

fn execute_ephemeral_i64_join(
    inputs: &DirectI64JoinInputs<'_>,
    stats: &mut ExecutionStats,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let left_data = &inputs.left.data;
    let right_data = &inputs.right.data;
    let Some(right_keys) = native_i64_column(right_data, inputs.right_column) else {
        return Ok(None);
    };
    if SemanticAccessCostModel::choose_ephemeral_join(
        inputs.left_keys.len(),
        right_keys.len(),
        right_keys.len(),
        1,
    ) == SemanticAccessPath::FullScan
    {
        return Ok(None);
    }

    stats.ephemeral_index_builds = stats.ephemeral_index_builds.saturating_add(1);
    let mut right_index: BTreeMap<i64, Vec<usize>> = BTreeMap::new();
    for row_index in inputs.right.scan_positions() {
        let key = right_keys[row_index];
        right_index.entry(key).or_default().push(row_index);
    }
    if SemanticAccessCostModel::choose_ephemeral_join(
        inputs.left_keys.len(),
        right_keys.len(),
        right_index.len(),
        1,
    ) == SemanticAccessPath::FullScan
    {
        stats.persisted_index_cost_rejections =
            stats.persisted_index_cost_rejections.saturating_add(1);
        return Ok(None);
    }
    let mut out = Vec::with_capacity(inputs.left_keys.len());
    for left_index in inputs.left.scan_positions() {
        let key = inputs.left_keys[left_index];
        if let Some(right_rows) = right_index.get(&key) {
            for right_index in right_rows {
                let mut row = Vec::with_capacity(
                    native_column_count(left_data).saturating_add(native_column_count(right_data)),
                );
                append_native_row_values(&mut row, left_data, left_index)?;
                append_native_row_values(&mut row, right_data, *right_index)?;
                out.push(row);
            }
        }
    }
    stats.scanned_rows = stats
        .scanned_rows
        .saturating_add(inputs.left_keys.len().saturating_add(right_keys.len()));
    account_join_reads(
        stats,
        inputs.left_keys.len(),
        right_keys.len(),
        out.len(),
        left_data,
        right_data,
    );
    Ok(Some(out))
}

#[allow(clippy::too_many_arguments)]
fn try_execute_indexed_i64_join(
    left: &Plan,
    right: &Plan,
    left_column: usize,
    right_column: usize,
    equivalence: SemanticId,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    stats: &mut ExecutionStats,
    allow_ephemeral: bool,
) -> Result<Option<Vec<kernel_query::Row>>, PhysicalExecutionError> {
    let Some((left_relation, left_layout)) = direct_scan_relation(left) else {
        return Ok(None);
    };
    let Some((right_relation, right_layout)) = direct_scan_relation(right) else {
        return Ok(None);
    };
    let Some(resolved) = registry.resolve_primitive_equivalence(context, equivalence)? else {
        return Ok(None);
    };
    if !matches!(
        resolved.bind_right(&Value::I64(0)),
        Ok(kernel_semantics::BoundPrimitivePredicate::I64(_))
    ) {
        return Ok(None);
    }

    let left_installed = store.installed(left_relation, left_layout)?;
    let right_installed = store.installed(right_relation, right_layout)?;
    validate_indexable_i64_relation(context, left_relation, &left_installed.data)?;
    validate_indexable_i64_relation(context, right_relation, &right_installed.data)?;
    let Some(left_keys) = native_i64_column(&left_installed.data, left_column) else {
        return Ok(None);
    };
    let inputs = DirectI64JoinInputs {
        left: left_installed,
        right: right_installed,
        left_keys,
        right_column,
    };
    let binding = I64IndexBinding {
        relation: right_relation,
        layout: right_layout,
        key_column: right_column,
        equivalence,
    };
    if let Some(index) = store.i64_index(binding) {
        if allow_ephemeral {
            return Ok(None);
        }
        return execute_persisted_i64_join(&inputs, index, stats);
    }
    if !allow_ephemeral {
        return Ok(None);
    }
    execute_ephemeral_i64_join(&inputs, stats)
}

fn account_join_reads(
    stats: &mut ExecutionStats,
    left_keys: usize,
    right_keys: usize,
    output_rows: usize,
    left: &NativeRelation,
    right: &NativeRelation,
) {
    let output_width = native_column_count(left).saturating_add(native_column_count(right));
    stats.values_read = stats.values_read.saturating_add(
        left_keys
            .saturating_add(right_keys)
            .saturating_add(output_rows.saturating_mul(output_width)),
    );
}

fn direct_scan_relation(plan: &Plan) -> Option<(SemanticId, LayoutBinding)> {
    match plan {
        Plan::Scan {
            relation,
            layout,
            algorithm: ScanAlgorithm::FullScan,
        } => Some((*relation, *layout)),
        _ => None,
    }
}

