fn canonical_eq_key_heap_bytes(key: &kernel_semantics::CanonicalEqKey) -> usize {
    use kernel_semantics::CanonicalEqKey;
    match key {
        CanonicalEqKey::Unit
        | CanonicalEqKey::Bool(_)
        | CanonicalEqKey::I64(_)
        | CanonicalEqKey::F64Bits(_)
        | CanonicalEqKey::OptionNone
        | CanonicalEqKey::LiveEntityId { .. }
        | CanonicalEqKey::HistoricalEntityId { .. } => 0,
        CanonicalEqKey::TextExact(value) | CanonicalEqKey::TextAsciiCaseInsensitive(value) => {
            value.capacity()
        }
        CanonicalEqKey::Product(fields) => fields
            .capacity()
            .saturating_mul(std::mem::size_of::<(SemanticId, CanonicalEqKey)>())
            .saturating_add(saturating_usize_sum(
                fields
                    .iter()
                    .map(|(_, value)| canonical_eq_key_heap_bytes(value)),
            )),
        CanonicalEqKey::OptionSome(value) | CanonicalEqKey::Variant { value, .. } => {
            std::mem::size_of::<CanonicalEqKey>().saturating_add(canonical_eq_key_heap_bytes(value))
        }
        CanonicalEqKey::Seq(values) => values
            .capacity()
            .saturating_mul(std::mem::size_of::<CanonicalEqKey>())
            .saturating_add(saturating_usize_sum(
                values.iter().map(canonical_eq_key_heap_bytes),
            )),
        CanonicalEqKey::Set(values) => values
            .capacity()
            .saturating_mul(std::mem::size_of::<
                kernel_semantics::FiniteMeasureEntry<CanonicalEqKey>,
            >())
            .saturating_add(saturating_usize_sum(
                values
                    .iter()
                    .map(|entry| canonical_eq_key_heap_bytes(&entry.atom)),
            )),
        CanonicalEqKey::Bag(values) => values
            .capacity()
            .saturating_mul(std::mem::size_of::<
                kernel_semantics::FiniteMeasureEntry<kernel_semantics::CanonicalBagAtom>,
            >())
            .saturating_add(saturating_usize_sum(
                values
                    .iter()
                    .map(|entry| canonical_eq_key_heap_bytes(&entry.atom.value)),
            )),
        CanonicalEqKey::Map(values) => values
            .capacity()
            .saturating_mul(std::mem::size_of::<
                kernel_semantics::FiniteMeasureEntry<kernel_semantics::CanonicalMapAtom>,
            >())
            .saturating_add(saturating_usize_sum(values.iter().map(|entry| {
                canonical_eq_key_heap_bytes(&entry.atom.key)
                    .saturating_add(canonical_eq_key_heap_bytes(&entry.atom.value))
            }))),
    }
}

fn semantic_key_retained_bytes(key: &Vec<kernel_semantics::CanonicalEqKey>) -> usize {
    std::mem::size_of::<Vec<kernel_semantics::CanonicalEqKey>>()
        .saturating_add(
            key.capacity()
                .saturating_mul(std::mem::size_of::<kernel_semantics::CanonicalEqKey>()),
        )
        .saturating_add(saturating_usize_sum(
            key.iter().map(canonical_eq_key_heap_bytes),
        ))
}

fn semantic_key_heap_bytes(key: &Vec<kernel_semantics::CanonicalEqKey>) -> usize {
    key.capacity()
        .saturating_mul(std::mem::size_of::<kernel_semantics::CanonicalEqKey>())
        .saturating_add(saturating_usize_sum(
            key.iter().map(canonical_eq_key_heap_bytes),
        ))
}

fn semantic_index_binding_heap_bytes(binding: &SemanticIndexBinding) -> usize {
    binding
        .key_parts
        .capacity()
        .saturating_mul(std::mem::size_of::<SemanticIndexKeyPart>())
}

fn semantic_index_estimated_retained_bytes(state: &MaterializedSemanticIndexState) -> usize {
    std::mem::size_of::<SemanticIndexBinding>()
        .saturating_add(semantic_index_binding_heap_bytes(&state.binding))
        .saturating_add(
            state
                .resolved
                .capacity()
                .saturating_mul(std::mem::size_of::<
                    kernel_semantics::ResolvedPrimitiveEquivalence,
                >()),
        )
        .saturating_add(
            state
                .index
                .estimated_retained_bytes(semantic_key_heap_bytes),
        )
}

fn observable_atom_estimated_retained_bytes(state: &MaterializedObservableAtomState) -> usize {
    let class_bytes = std::mem::size_of::<kernel_types::EqClassId>();
    let row_bytes = std::mem::size_of::<PhysicalRowId>();
    let atom_rows = state.fabric.row_count();
    let atoms = state.fabric.atom_count();
    let coordinates = state.observables.len();
    let projection_refs = state.fabric.projection_atom_reference_count();
    let projected_classes = state.fabric.projected_class_count();
    let projection_mapping_bytes =
        state
            .projection
            .materialized_mapping()
            .iter()
            .fold(0_usize, |bytes, (source, target)| {
                bytes
                    .saturating_add(std::mem::size_of::<Vec<kernel_types::EqClassId>>() * 2)
                    .saturating_add(source.capacity().saturating_mul(class_bytes))
                    .saturating_add(target.capacity().saturating_mul(class_bytes))
            });

    std::mem::size_of::<MaterializedObservableAtomState>()
        .saturating_add(semantic_index_binding_heap_bytes(&state.binding))
        .saturating_add(
            state
                .observables
                .capacity()
                .saturating_mul(std::mem::size_of::<kernel_types::RevisionObservableId>()),
        )
        .saturating_add(atom_rows.saturating_mul(row_bytes.saturating_mul(2)))
        .saturating_add(atom_rows.saturating_mul(class_bytes))
        .saturating_add(
            atoms
                .saturating_mul(coordinates)
                .saturating_mul(class_bytes),
        )
        .saturating_add(projection_refs.saturating_mul(class_bytes))
        .saturating_add(projected_classes.saturating_mul(class_bytes))
        .saturating_add(projection_mapping_bytes)
}

fn i64_index_estimated_retained_bytes(state: &MaterializedI64IndexState) -> usize {
    state.buckets.iter().fold(
        std::mem::size_of::<MaterializedI64IndexState>(),
        |bytes, (_, identities)| {
            bytes
                .saturating_add(std::mem::size_of::<(i64, Vec<PhysicalRowId>)>())
                .saturating_add(
                    identities
                        .capacity()
                        .saturating_mul(std::mem::size_of::<PhysicalRowId>()),
                )
        },
    )
}

fn quotient_factor_estimated_retained_bytes(
    state: &MaterializedSemanticQuotientFactorState,
) -> usize {
    let mut bytes = std::mem::size_of::<MaterializedSemanticQuotientFactorState>()
        .saturating_add(semantic_index_binding_heap_bytes(&state.binding));
    for (key, identities) in &state.buckets {
        bytes = bytes
            .saturating_add(semantic_key_retained_bytes(key))
            .saturating_add(std::mem::size_of::<Vec<PhysicalRowId>>())
            .saturating_add(
                identities
                    .capacity()
                    .saturating_mul(std::mem::size_of::<PhysicalRowId>()),
            );
    }
    for key in state.reverse.values() {
        bytes = bytes
            .saturating_add(std::mem::size_of::<PhysicalRowId>())
            .saturating_add(semantic_key_retained_bytes(key));
    }
    bytes
}

fn semantic_statistics_estimated_retained_bytes(
    state: &MaterializedSemanticStatisticsState,
) -> usize {
    state.counts.iter().fold(
        std::mem::size_of::<MaterializedSemanticStatisticsState>()
            .saturating_add(semantic_index_binding_heap_bytes(&state.binding))
            .saturating_add(
                state
                    .resolved
                    .capacity()
                    .saturating_mul(std::mem::size_of::<
                        kernel_semantics::ResolvedPrimitiveEquivalence,
                    >()),
            ),
        |bytes, (key, _)| {
            bytes
                .saturating_add(semantic_key_retained_bytes(key))
                .saturating_add(std::mem::size_of::<usize>())
        },
    )
}

fn quotient_support_estimated_retained_bytes(
    state: &MaterializedSemanticQuotientSupportState,
) -> usize {
    let mut bytes = std::mem::size_of::<MaterializedSemanticQuotientSupportState>()
        .saturating_add(
            state
                .binding
                .leaves
                .capacity()
                .saturating_mul(std::mem::size_of::<(SemanticId, LayoutBinding, usize)>()),
        )
        .saturating_add(
            state
                .binding
                .specs
                .capacity()
                .saturating_mul(std::mem::size_of::<(SemanticId, Vec<MultiwayJoinColumnRef>)>()),
        );
    for (_, refs) in &state.binding.specs {
        bytes = bytes.saturating_add(
            refs.capacity()
                .saturating_mul(std::mem::size_of::<MultiwayJoinColumnRef>()),
        );
    }
    for handles in &state.handles {
        bytes = bytes
            .saturating_add(std::mem::size_of::<Vec<PhysicalRowId>>())
            .saturating_add(
                handles
                    .capacity()
                    .saturating_mul(std::mem::size_of::<PhysicalRowId>()),
            );
    }
    for mask in &state.base_masks {
        bytes = bytes
            .saturating_add(std::mem::size_of::<Vec<u64>>())
            .saturating_add(mask.capacity().saturating_mul(std::mem::size_of::<u64>()));
    }
    for constraint in &state.constraints {
        bytes = bytes.saturating_add(
            constraint
                .leaves
                .capacity()
                .saturating_mul(std::mem::size_of::<SemanticQuotientLeaf>()),
        );
        for leaf in &constraint.leaves {
            bytes =
                bytes.saturating_add(leaf.keys.capacity().saturating_mul(std::mem::size_of::<
                    Option<kernel_semantics::CanonicalEqKey>,
                >()));
            for key in leaf.keys.iter().flatten() {
                bytes = bytes.saturating_add(canonical_eq_key_heap_bytes(key));
            }
            for (key, ordinals) in &leaf.buckets {
                bytes = bytes
                    .saturating_add(std::mem::size_of::<kernel_semantics::CanonicalEqKey>())
                    .saturating_add(canonical_eq_key_heap_bytes(key))
                    .saturating_add(std::mem::size_of::<Vec<u64>>())
                    .saturating_add(
                        ordinals
                            .capacity()
                            .saturating_mul(std::mem::size_of::<u64>()),
                    );
            }
            for key in leaf.live_rows_by_key.keys() {
                bytes = bytes
                    .saturating_add(std::mem::size_of::<kernel_semantics::CanonicalEqKey>())
                    .saturating_add(canonical_eq_key_heap_bytes(key))
                    .saturating_add(std::mem::size_of::<usize>());
            }
        }
        for support in [
            &constraint.key_leaf_support,
            &constraint.live_key_leaf_support,
        ] {
            for key in support.keys() {
                bytes = bytes
                    .saturating_add(std::mem::size_of::<kernel_semantics::CanonicalEqKey>())
                    .saturating_add(canonical_eq_key_heap_bytes(key))
                    .saturating_add(std::mem::size_of::<usize>());
            }
        }
    }
    bytes = bytes
        .saturating_add(std::mem::size_of::<SemanticQuotientBfcMaintenance>())
        .saturating_add(state.bfc.program.estimated_retained_bytes())
        .saturating_add(state.bfc.certificate.estimated_retained_bytes());
    for atoms in &state.bfc.atoms_by_handle {
        bytes = bytes
            .saturating_add(std::mem::size_of::<
                BTreeMap<PhysicalRowId, kernel_grounded_closure::GroundedAtomId>,
            >())
            .saturating_add(atoms.len().saturating_mul(std::mem::size_of::<(
                PhysicalRowId,
                kernel_grounded_closure::GroundedAtomId,
            )>()));
    }
    bytes
}

#[derive(Clone, Copy)]
struct UnifiedObservableAdvisorInputs<'a> {
    telemetry: &'a UnifiedAdvisorTelemetry,
    policy: UnifiedAdvisorPolicy,
    pressure_policy: PhysicalPressurePolicy,
    pressure_sample: PhysicalPressureSample,
}

struct UnifiedObservableAdvisorSelection {
    selection: advisor::AdmissionSelection<UnifiedArtifactId>,
    prepared: BTreeMap<SemanticIndexBinding, MaterializedObservableAtomState>,
}

fn unified_observable_advisor_selection(
    store: &PhysicalStore,
    workload: &[SemanticIndexWorkloadSample],
    inputs: UnifiedObservableAdvisorInputs<'_>,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<UnifiedObservableAdvisorSelection, PhysicalExecutionError> {
    let scores = semantic_index_advice_scores(store, workload, context, registry)?;
    let mut demanded = scores.keys().cloned().collect::<BTreeSet<_>>();
    demanded.extend(
        store
            .advisor_managed_artifacts
            .iter()
            .filter_map(|artifact| match artifact {
                UnifiedArtifactId::ObservableAtom(binding) => Some(binding.clone()),
                _ => None,
            }),
    );

    let current_memory = store
        .artifact_memory_report()
        .total_estimated_retained_bytes;
    let replaceable_observable_bytes = saturating_usize_sum(
        store
            .observable_atom_states
            .iter()
            .filter(|(binding, _)| {
                store
                    .advisor_managed_artifacts
                    .contains(&UnifiedArtifactId::ObservableAtom((*binding).clone()))
            })
            .map(|(_, state)| observable_atom_estimated_retained_bytes(state)),
    );
    let fixed_estimated_bytes = current_memory.saturating_sub(replaceable_observable_bytes);
    let mut prepared = BTreeMap::<SemanticIndexBinding, MaterializedObservableAtomState>::new();
    let mut candidates = Vec::new();

    for binding in demanded {
        let id = UnifiedArtifactId::ObservableAtom(binding.clone());
        let advisor_managed = store.advisor_managed_artifacts.contains(&id);
        let existing = store.observable_atom_states.get(&binding);
        if existing.is_some() && !advisor_managed {
            continue;
        }
        let compatible_existing = match existing {
            Some(state) => state.compatible_with(context, registry)?,
            None => false,
        };
        let advice = scores.get(&binding);
        let baseline_read = advice.map_or(0, |entry| entry.gross_savings);
        let baseline_build = if compatible_existing {
            0
        } else {
            advice.map_or(0, |entry| entry.key_cells as u128)
        };
        let estimated_bytes = if compatible_existing {
            existing.map_or(0, |state| observable_atom_estimated_retained_bytes(state))
        } else {
            let relation = store.installed(binding.relation, binding.layout)?;
            let state = MaterializedObservableAtomState::build(
                binding.clone(),
                relation,
                context,
                registry,
            )?;
            let bytes = observable_atom_estimated_retained_bytes(&state);
            prepared.insert(binding.clone(), state);
            bytes
        };
        let work = inputs.telemetry.get(&id).apply_to(
            PhysicalWorkEstimate {
                read_work_saved: baseline_read,
                maintenance_work: 0,
                build_work: baseline_build,
            },
            compatible_existing,
        );
        candidates.push(advisor::AdmissionCandidate {
            key: id.clone(),
            capabilities: id.capabilities(),
            work,
            managed_units: 1,
            footprint: ResourceFootprint::from_atom(id, estimated_bytes),
            replaced_fixed_bytes: 0,
            existing_manual: false,
            existing_advisor_managed: advisor_managed,
            tie_break_work: advice.map_or(0, |entry| entry.key_cells),
        });
    }

    let selection = advisor::select_candidates_with_pressure(
        candidates,
        fixed_estimated_bytes,
        inputs.policy,
        inputs.pressure_policy,
        inputs.pressure_sample,
    );
    Ok(UnifiedObservableAdvisorSelection {
        selection,
        prepared,
    })
}

fn observable_binding_ids(ids: Vec<UnifiedArtifactId>) -> Vec<SemanticIndexBinding> {
    ids.into_iter()
        .filter_map(|id| match id {
            UnifiedArtifactId::ObservableAtom(binding) => Some(binding),
            _ => None,
        })
        .collect()
}

fn retire_advisor_legacy_for_observable(
    store: &mut PhysicalStore,
    binding: &SemanticIndexBinding,
    report: &mut UnifiedObservableAdvisorReport,
) -> bool {
    let mut changed = false;
    let index = UnifiedArtifactId::SemanticIndex(binding.clone());
    if store.advisor_managed_artifacts.contains(&index) {
        store.semantic_indexes_mut().remove(binding);
        store.advisor_managed_artifacts_mut().remove(&index);
        report.retired_legacy_indexes.push(binding.clone());
        changed = true;
    }
    let statistics = UnifiedArtifactId::SemanticStatistics(binding.clone());
    if store.advisor_managed_artifacts.contains(&statistics) {
        store.semantic_statistics_mut().remove(binding);
        store.advisor_managed_artifacts_mut().remove(&statistics);
        report.retired_legacy_statistics.push(binding.clone());
        changed = true;
    }
    let quotient = UnifiedArtifactId::SemanticQuotientFactor(binding.clone());
    if store.advisor_managed_artifacts.contains(&quotient) {
        store.semantic_quotient_factors_mut().remove(binding);
        store.advisor_managed_artifacts_mut().remove(&quotient);
        report.retired_legacy_quotient_factors.push(binding.clone());
        changed = true;
    }
    changed
}

fn apply_unified_observable_selection(
    store: &mut PhysicalStore,
    mut selected: UnifiedObservableAdvisorSelection,
) -> Result<UnifiedObservableAdvisorReport, PhysicalExecutionError> {
    let selected_bindings = selected
        .selection
        .selected
        .iter()
        .filter_map(|id| match id {
            UnifiedArtifactId::ObservableAtom(binding) => Some(binding.clone()),
            _ => None,
        })
        .collect::<BTreeSet<_>>();
    let evicted = store
        .advisor_managed_artifacts
        .iter()
        .filter_map(|artifact| match artifact {
            UnifiedArtifactId::ObservableAtom(binding) if !selected_bindings.contains(binding) => {
                Some(binding.clone())
            }
            _ => None,
        })
        .collect::<Vec<_>>();
    let mut report = UnifiedObservableAdvisorReport {
        rejected_unprofitable: observable_binding_ids(selected.selection.rejected_unprofitable),
        rejected_budget: observable_binding_ids(selected.selection.rejected_budget),
        rejected_pressure: observable_binding_ids(selected.selection.rejected_pressure),
        rejected_resource_conflict: observable_binding_ids(
            selected.selection.rejected_resource_conflict,
        ),
        managed_estimated_bytes: selected.selection.managed_estimated_bytes,
        fixed_estimated_bytes: selected.selection.fixed_estimated_bytes,
        total_estimated_bytes_after: selected.selection.total_estimated_bytes_after,
        ..UnifiedObservableAdvisorReport::default()
    };
    let mut changed = false;

    for binding in evicted {
        store.observable_atom_states_mut().remove(&binding);
        store
            .advisor_managed_artifacts_mut()
            .remove(&UnifiedArtifactId::ObservableAtom(binding.clone()));
        report.evicted.push(binding);
        changed = true;
    }
    for binding in selected_bindings {
        if let Some(state) = selected.prepared.remove(&binding) {
            let existed = store.observable_atom_states.contains_key(&binding);
            store
                .observable_atom_states_mut()
                .insert(binding.clone(), Arc::new(state));
            store
                .advisor_managed_artifacts_mut()
                .insert(UnifiedArtifactId::ObservableAtom(binding.clone()));
            if existed {
                report.rebuilt.push(binding.clone());
            } else {
                report.created.push(binding.clone());
            }
            changed = true;
        } else {
            report.retained.push(binding.clone());
        }
        changed |= retire_advisor_legacy_for_observable(store, &binding, &mut report);
    }
    if changed {
        store.transition_epoch = store
            .transition_epoch
            .checked_add(1)
            .ok_or(PhysicalExecutionError::TransitionEpochExhausted)?;
        store.state_identity = Arc::new(());
    }
    report.total_estimated_bytes_after = store
        .artifact_memory_report()
        .total_estimated_retained_bytes;
    Ok(report)
}

fn semantic_index_advice_scores(
    store: &PhysicalStore,
    workload: &[SemanticIndexWorkloadSample],
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<BTreeMap<SemanticIndexBinding, SemanticIndexAdviceScore>, PhysicalExecutionError> {
    let mut scores = BTreeMap::<SemanticIndexBinding, SemanticIndexAdviceScore>::new();
    for sample in workload {
        if sample.expected_executions == 0 {
            continue;
        }
        for observation in
            semantic_index_advice_observations(&sample.plan, store, context, registry)?
        {
            let entry = scores
                .entry(observation.binding.clone())
                .or_insert_with(|| SemanticIndexAdviceScore {
                    binding: observation.binding.clone(),
                    gross_savings: 0,
                    key_cells: observation.key_cells,
                    estimated_bytes: observation.estimated_bytes,
                });
            entry.gross_savings = entry.gross_savings.saturating_add(
                observation
                    .savings_per_execution
                    .saturating_mul(sample.expected_executions as u128),
            );
            entry.key_cells = entry.key_cells.max(observation.key_cells);
            entry.estimated_bytes = entry.estimated_bytes.max(observation.estimated_bytes);
        }
    }
    Ok(scores)
}

fn semantic_index_advice_choices(
    store: &PhysicalStore,
    scores: BTreeMap<SemanticIndexBinding, SemanticIndexAdviceScore>,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    report: &mut SemanticIndexAdvisorReport,
) -> Result<Vec<SemanticIndexAdviceChoice>, PhysicalExecutionError> {
    let mut choices = Vec::new();
    for score in scores.into_values() {
        let existing = store.semantic_indexes.get(&score.binding);
        let compatible_existing = match existing {
            Some(state) => state.compatible_with(context, registry)?,
            None => false,
        };
        let build_work = if compatible_existing {
            0
        } else {
            score.key_cells as u128
        };
        if score.gross_savings <= build_work {
            report.rejected_unprofitable.push(score.binding);
            continue;
        }
        let advisor_managed = store
            .advisor_managed_artifacts
            .contains(&UnifiedArtifactId::SemanticIndex(score.binding.clone()));
        let replaced_fixed_bytes = if !compatible_existing && !advisor_managed {
            existing.map_or(0, |state| semantic_index_estimated_retained_bytes(state))
        } else {
            0
        };
        choices.push(SemanticIndexAdviceChoice {
            binding: score.binding,
            work: PhysicalWorkEstimate {
                read_work_saved: score.gross_savings,
                maintenance_work: 0,
                build_work,
            },
            key_cells: score.key_cells,
            estimated_bytes: score.estimated_bytes,
            compatible_existing,
            advisor_managed,
            replaced_fixed_bytes,
        });
    }
    Ok(choices)
}

const fn semantic_index_managed_cost(choice: &SemanticIndexAdviceChoice) -> usize {
    if choice.compatible_existing && !choice.advisor_managed {
        0
    } else {
        choice.key_cells
    }
}

const fn semantic_index_managed_estimated_bytes(choice: &SemanticIndexAdviceChoice) -> usize {
    if choice.compatible_existing && !choice.advisor_managed {
        0
    } else {
        choice.estimated_bytes
    }
}

fn semantic_index_advisor_selection(
    store: &PhysicalStore,
    workload: &[SemanticIndexWorkloadSample],
    policy: SemanticIndexAdvisorPolicy,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<
    (
        BTreeSet<SemanticIndexBinding>,
        usize,
        usize,
        SemanticIndexAdvisorReport,
    ),
    PhysicalExecutionError,
> {
    let scores = semantic_index_advice_scores(store, workload, context, registry)?;
    let mut report = SemanticIndexAdvisorReport::default();
    let choices = semantic_index_advice_choices(store, scores, context, registry, &mut report)?;

    let current_memory = store
        .artifact_memory_report()
        .total_estimated_retained_bytes;
    let replaceable_managed_bytes = saturating_usize_sum(
        store
            .semantic_indexes
            .iter()
            .filter(|(binding, _)| {
                store
                    .advisor_managed_artifacts
                    .contains(&UnifiedArtifactId::SemanticIndex((*binding).clone()))
            })
            .map(|(_, state)| semantic_index_estimated_retained_bytes(state)),
    );
    let fixed_estimated_bytes = current_memory.saturating_sub(replaceable_managed_bytes);
    let candidates = choices
        .into_iter()
        .map(|choice| {
            let managed_units = semantic_index_managed_cost(&choice);
            let managed_bytes = semantic_index_managed_estimated_bytes(&choice);
            advisor::AdmissionCandidate {
                key: choice.binding.clone(),
                capabilities: BTreeSet::from([PhysicalCapability::PointLookup]),
                work: choice.work,
                managed_units,
                footprint: ResourceFootprint::from_atom(choice.binding, managed_bytes),
                replaced_fixed_bytes: choice.replaced_fixed_bytes,
                existing_manual: choice.compatible_existing && !choice.advisor_managed,
                existing_advisor_managed: choice.advisor_managed,
                tie_break_work: 0,
            }
        })
        .collect();
    let selection = advisor::select_candidates(
        candidates,
        fixed_estimated_bytes,
        UnifiedAdvisorPolicy {
            max_managed_units: policy.max_managed_key_cells,
            max_managed_estimated_bytes: policy.max_managed_estimated_bytes,
            max_total_estimated_bytes: policy.max_total_estimated_bytes,
            build_threshold: 0,
            retain_threshold: 0,
        },
    );
    report.rejected_budget.extend(selection.rejected_budget);
    report
        .rejected_unprofitable
        .extend(selection.rejected_unprofitable);
    report.fixed_estimated_bytes = selection.fixed_estimated_bytes;
    report.total_estimated_bytes_after = selection.total_estimated_bytes_after;
    Ok((
        selection.selected,
        selection.managed_units,
        selection.managed_estimated_bytes,
        report,
    ))
}

fn semantic_binding_as_i64(
    binding: &SemanticIndexBinding,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<Option<I64IndexBinding>, PhysicalExecutionError> {
    let [part] = binding.key_parts.as_slice() else {
        return Ok(None);
    };
    let Some(resolved) = registry.resolve_primitive_equivalence(context, part.equivalence)? else {
        return Ok(None);
    };
    if !matches!(
        resolved.bind_right(&Value::I64(0)),
        Ok(kernel_semantics::BoundPrimitivePredicate::I64(_))
    ) {
        return Ok(None);
    }
    Ok(Some(I64IndexBinding {
        relation: binding.relation,
        layout: binding.layout,
        key_column: part.column,
        equivalence: part.equivalence,
    }))
}

fn i64_index_advice_scores(
    store: &PhysicalStore,
    workload: &[SemanticIndexWorkloadSample],
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<BTreeMap<I64IndexBinding, u128>, PhysicalExecutionError> {
    let mut gross_savings = BTreeMap::<I64IndexBinding, u128>::new();
    for sample in workload {
        if sample.expected_executions == 0 {
            continue;
        }
        let mut observations = Vec::new();
        collect_i64_join_advice_observations(
            &sample.plan,
            store,
            context,
            registry,
            &mut observations,
        )?;
        for observation in observations {
            let Some(binding) = semantic_binding_as_i64(&observation.binding, context, registry)?
            else {
                continue;
            };
            let contribution = observation
                .savings_per_execution
                .saturating_mul(sample.expected_executions as u128);
            let accumulated = gross_savings.entry(binding).or_default();
            *accumulated = accumulated.saturating_add(contribution);
        }
    }
    Ok(gross_savings)
}

fn i64_index_advice_choices(
    store: &PhysicalStore,
    scores: BTreeMap<I64IndexBinding, u128>,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    report: &mut I64IndexAdvisorReport,
) -> Result<Vec<I64IndexAdviceChoice>, PhysicalExecutionError> {
    let mut choices = Vec::new();
    for (binding, gross_savings) in scores {
        let existing = store.i64_indexes.get(&binding);
        let advisor_managed = store
            .advisor_managed_artifacts
            .contains(&UnifiedArtifactId::I64Index(binding));
        let relation = store.installed(binding.relation, binding.layout)?;
        let row_count = native_row_count(&relation.data);
        let build_work = if existing.is_some() {
            0
        } else {
            row_count as u128
        };
        if gross_savings <= build_work {
            report.rejected_unprofitable.push(binding);
            continue;
        }
        let (estimated_bytes, prepared_state) = if let Some(existing) = existing {
            (i64_index_estimated_retained_bytes(existing), None)
        } else {
            let candidate = MaterializedI64IndexState::build(binding, relation, context, registry)?;
            (
                i64_index_estimated_retained_bytes(&candidate),
                Some(candidate),
            )
        };
        choices.push(I64IndexAdviceChoice {
            binding,
            work: PhysicalWorkEstimate {
                read_work_saved: gross_savings,
                maintenance_work: 0,
                build_work,
            },
            row_count,
            estimated_bytes,
            existing_manual: existing.is_some() && !advisor_managed,
            advisor_managed,
            prepared_state,
        });
    }
    Ok(choices)
}

fn i64_index_advisor_selection(
    store: &PhysicalStore,
    workload: &[SemanticIndexWorkloadSample],
    policy: PhysicalArtifactAdvisorPolicy,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<I64IndexAdvisorSelection, PhysicalExecutionError> {
    let scores = i64_index_advice_scores(store, workload, context, registry)?;
    let mut report = I64IndexAdvisorReport::default();
    let mut choices = i64_index_advice_choices(store, scores, context, registry, &mut report)?;
    let current_memory = store
        .artifact_memory_report()
        .total_estimated_retained_bytes;
    let replaceable_managed_bytes = saturating_usize_sum(
        store
            .i64_indexes
            .iter()
            .filter(|(binding, _)| {
                store
                    .advisor_managed_artifacts
                    .contains(&UnifiedArtifactId::I64Index(**binding))
            })
            .map(|(_, state)| i64_index_estimated_retained_bytes(state)),
    );
    let fixed_estimated_bytes = current_memory.saturating_sub(replaceable_managed_bytes);
    let candidates = choices
        .iter()
        .map(|choice| advisor::AdmissionCandidate {
            key: choice.binding,
            capabilities: BTreeSet::from([PhysicalCapability::PointLookup]),
            work: choice.work,
            managed_units: 0,
            footprint: ResourceFootprint::from_atom(choice.binding, choice.estimated_bytes),
            replaced_fixed_bytes: 0,
            existing_manual: choice.existing_manual,
            existing_advisor_managed: choice.advisor_managed,
            tie_break_work: choice.row_count,
        })
        .collect();
    let selection = advisor::select_candidates(
        candidates,
        fixed_estimated_bytes,
        UnifiedAdvisorPolicy {
            max_managed_units: usize::MAX,
            max_managed_estimated_bytes: policy.max_managed_estimated_bytes,
            max_total_estimated_bytes: policy.max_total_estimated_bytes,
            build_threshold: 0,
            retain_threshold: 0,
        },
    );
    let mut prepared_states = Vec::new();
    for choice in &mut choices {
        if selection.selected.contains(&choice.binding)
            && let Some(state) = choice.prepared_state.take()
        {
            prepared_states.push((choice.binding, state));
        }
    }
    report.rejected_budget.extend(selection.rejected_budget);
    report
        .rejected_unprofitable
        .extend(selection.rejected_unprofitable);
    report.fixed_estimated_bytes = selection.fixed_estimated_bytes;
    report.total_estimated_bytes_after = selection.total_estimated_bytes_after;
    Ok(I64IndexAdvisorSelection {
        selected: selection.selected,
        prepared_states,
        managed_estimated_bytes: selection.managed_estimated_bytes,
        report,
    })
}

fn collect_i64_join_advice_observations(
    plan: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    observations: &mut Vec<SemanticIndexAdviceObservation>,
) -> Result<(), PhysicalExecutionError> {
    if let Some(observation) =
        semantic_index_join_advice_observation(plan, store, context, registry)?
    {
        observations.push(observation);
        return Ok(());
    }
    match plan {
        Plan::FilterEqConst { input, .. }
        | Plan::FilterEqColumns { input, .. }
        | Plan::Project { input, .. }
        | Plan::Distinct { input, .. }
        | Plan::Group { input, .. }
        | Plan::TopKWithTies { input, .. }
        | Plan::PromoteToBag(input) => {
            collect_i64_join_advice_observations(input, store, context, registry, observations)
        }
        Plan::JoinEq { left, right, .. }
        | Plan::Difference { left, right }
        | Plan::AntiJoin { left, right, .. } => {
            collect_i64_join_advice_observations(left, store, context, registry, observations)?;
            collect_i64_join_advice_observations(right, store, context, registry, observations)
        }
        Plan::Scan { .. } => Ok(()),
    }
}

fn collect_semantic_statistics_advice_uses(
    plan: &Plan,
    store: &PhysicalStore,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    expected_executions: usize,
    uses: &mut BTreeMap<SemanticIndexBinding, Vec<SemanticStatisticsAdviceUse>>,
) -> Result<(), PhysicalExecutionError> {
    if expected_executions == 0 {
        return Ok(());
    }
    if let Plan::JoinEq {
        left,
        right,
        right_column,
        equivalence,
        algorithm: JoinAlgorithm::IndexedPrimitiveIfAvailable,
        ..
    } = plan
        && let (Some((left_relation, left_layout)), Some((right_relation, right_layout))) =
            (direct_scan_relation(left), direct_scan_relation(right))
    {
        let binding =
            SemanticIndexBinding::single(right_relation, right_layout, *right_column, *equivalence);
        if primitive_binding_supported(&binding, context, registry)? {
            let i64_binding = semantic_binding_as_i64(&binding, context, registry)?;
            let has_i64 = i64_binding.is_some_and(|binding| store.i64_index(binding).is_some());
            let has_semantic = match store.semantic_indexes.get(&binding) {
                Some(state) => state.compatible_with(context, registry)?,
                None => false,
            };
            if !has_i64 && !has_semantic {
                let left_rows =
                    native_row_count(&store.installed(left_relation, left_layout)?.data);
                let right_rows =
                    native_row_count(&store.installed(right_relation, right_layout)?.data);
                if left_rows != 0 && right_rows != 0 {
                    let scan_work = SemanticAccessCostModel::join_scan_work(left_rows, right_rows);
                    let optimistic_ephemeral = SemanticAccessCostModel::ephemeral_join_work(
                        left_rows,
                        right_rows,
                        right_rows,
                        binding.key_parts.len(),
                    );
                    if optimistic_ephemeral < scan_work {
                        uses.entry(binding)
                            .or_default()
                            .push(SemanticStatisticsAdviceUse {
                                left_rows,
                                right_rows,
                                expected_executions,
                            });
                    }
                }
            }
        }
        return Ok(());
    }
    match plan {
        Plan::FilterEqConst { input, .. }
        | Plan::FilterEqColumns { input, .. }
        | Plan::Project { input, .. }
        | Plan::Distinct { input, .. }
        | Plan::Group { input, .. }
        | Plan::TopKWithTies { input, .. }
        | Plan::PromoteToBag(input) => collect_semantic_statistics_advice_uses(
            input,
            store,
            context,
            registry,
            expected_executions,
            uses,
        ),
        Plan::JoinEq { left, right, .. }
        | Plan::Difference { left, right }
        | Plan::AntiJoin { left, right, .. } => {
            collect_semantic_statistics_advice_uses(
                left,
                store,
                context,
                registry,
                expected_executions,
                uses,
            )?;
            collect_semantic_statistics_advice_uses(
                right,
                store,
                context,
                registry,
                expected_executions,
                uses,
            )
        }
        Plan::Scan { .. } => Ok(()),
    }
}

fn semantic_statistics_savings(
    uses: &[SemanticStatisticsAdviceUse],
    distinct_key_count: usize,
    key_parts: usize,
) -> u128 {
    uses.iter().fold(0_u128, |total, use_| {
        let scan_work = SemanticAccessCostModel::join_scan_work(use_.left_rows, use_.right_rows);
        let actual_ephemeral = SemanticAccessCostModel::ephemeral_join_work(
            use_.left_rows,
            use_.right_rows,
            distinct_key_count.max(1),
            key_parts,
        );
        let savings = actual_ephemeral.saturating_sub(scan_work) as u128;
        total.saturating_add(savings.saturating_mul(use_.expected_executions as u128))
    })
}

fn semantic_statistics_advice_choice(
    store: &PhysicalStore,
    binding: SemanticIndexBinding,
    uses: &[SemanticStatisticsAdviceUse],
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    report: &mut SemanticStatisticsAdvisorReport,
) -> Result<Option<SemanticStatisticsAdviceChoice>, PhysicalExecutionError> {
    let relation = store.installed(binding.relation, binding.layout)?;
    let row_count = native_row_count(&relation.data);
    let existing = store.semantic_statistics.get(&binding);
    let compatible_existing = match existing {
        Some(state) => state.compatible_with(context, registry)? && state.row_count == row_count,
        None => false,
    };
    let build_work = if compatible_existing {
        0
    } else {
        row_count.saturating_mul(binding.key_parts.len().max(1)) as u128
    };
    if !compatible_existing {
        let upper_bound = semantic_statistics_savings(uses, 1, binding.key_parts.len());
        if upper_bound <= build_work {
            report.rejected_unprofitable.push(binding);
            return Ok(None);
        }
    }
    let (distinct_key_count, estimated_bytes, prepared_state) = if compatible_existing {
        let state = existing.expect("compatible statistics must exist");
        (
            state.counts.len(),
            semantic_statistics_estimated_retained_bytes(state),
            None,
        )
    } else {
        let candidate = MaterializedSemanticStatisticsState::build(
            binding.clone(),
            relation,
            context,
            registry,
        )?;
        let estimated_bytes = semantic_statistics_estimated_retained_bytes(&candidate);
        (candidate.counts.len(), estimated_bytes, Some(candidate))
    };
    let gross_savings =
        semantic_statistics_savings(uses, distinct_key_count, binding.key_parts.len());
    if gross_savings <= build_work {
        report.rejected_unprofitable.push(binding);
        return Ok(None);
    }
    let advisor_managed = store
        .advisor_managed_artifacts
        .contains(&UnifiedArtifactId::SemanticStatistics(binding.clone()));
    let replaced_fixed_bytes = if !compatible_existing && !advisor_managed {
        existing.map_or(0, |state| {
            semantic_statistics_estimated_retained_bytes(state)
        })
    } else {
        0
    };
    Ok(Some(SemanticStatisticsAdviceChoice {
        binding,
        work: PhysicalWorkEstimate {
            read_work_saved: gross_savings,
            maintenance_work: 0,
            build_work,
        },
        row_count,
        estimated_bytes,
        compatible_existing,
        advisor_managed,
        replaced_fixed_bytes,
        prepared_state,
    }))
}

fn semantic_statistics_advice_choices(
    store: &PhysicalStore,
    workload: &[SemanticIndexWorkloadSample],
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    report: &mut SemanticStatisticsAdvisorReport,
) -> Result<Vec<SemanticStatisticsAdviceChoice>, PhysicalExecutionError> {
    let mut uses = BTreeMap::<SemanticIndexBinding, Vec<SemanticStatisticsAdviceUse>>::new();
    for sample in workload {
        collect_semantic_statistics_advice_uses(
            &sample.plan,
            store,
            context,
            registry,
            sample.expected_executions,
            &mut uses,
        )?;
    }
    let mut choices = Vec::new();
    for (binding, uses) in uses {
        if let Some(choice) =
            semantic_statistics_advice_choice(store, binding, &uses, context, registry, report)?
        {
            choices.push(choice);
        }
    }
    Ok(choices)
}

