pub struct PreparedOrderedView<'a> {
    plan: &'a PreparedPlan,
    spec: OrderedViewSpec,
    equivalences: Vec<SemanticId>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct OrderedViewEntry {
    order_class: kernel_semantics::CanonicalOrderClassKey,
    row_key: Vec<kernel_semantics::CanonicalEqKey>,
    occurrence: u64,
    row: kernel_query::Row,
}

impl OrderedViewEntry {
    fn cursor(
        &self,
        revision: RevisionId,
        semantic_revision: kernel_types::SemanticRevision,
        semantic_context: &kernel_schema::SemanticContext,
        logical: &RelExpr,
        spec: &OrderedViewSpec,
    ) -> OrderedViewCursor {
        OrderedViewCursor {
            revision,
            semantic_revision,
            semantic_context: semantic_context.clone(),
            logical: logical.clone(),
            column: spec.column,
            ordering: spec.ordering,
            direction: spec.direction,
            order_class: self.order_class.clone(),
            row_key: self.row_key.clone(),
            occurrence: self.occurrence,
        }
    }
}

impl PreparedOrderedView<'_> {
    fn validate_cursor(
        &self,
        cursor: &OrderedViewCursor,
        revision: RevisionId,
        semantic_revision: kernel_types::SemanticRevision,
    ) -> Result<(), OrderedViewError> {
        if cursor.revision != revision
            || cursor.semantic_revision != semantic_revision
            || cursor.semantic_context != self.plan.semantic_context
            || cursor.logical != *self.plan.logical()
            || cursor.column != self.spec.column
            || cursor.ordering != self.spec.ordering
            || cursor.direction != self.spec.direction
        {
            return Err(OrderedViewError::CursorBindingMismatch);
        }
        Ok(())
    }

    fn ordered_entries(
        &self,
        store: &PhysicalStore,
        registry: &kernel_semantics::SemanticRegistry,
    ) -> Result<Vec<OrderedViewEntry>, OrderedViewError> {
        let (value, _) = self.plan.execute_native_pinned(store, registry)?;
        let mut multiplicities = BTreeMap::<
            (
                kernel_semantics::CanonicalOrderClassKey,
                Vec<kernel_semantics::CanonicalEqKey>,
            ),
            (kernel_query::Row, u64),
        >::new();
        for row in value.into_rows() {
            let order_value = row
                .get(self.spec.column)
                .ok_or(RelQueryError::ColumnOutOfBounds)?;
            let order_class = registry.canonical_order_key(
                &self.plan.semantic_context,
                self.spec.ordering,
                order_value,
            )?;
            let row_key = row
                .iter()
                .zip(&self.equivalences)
                .map(|(value, equivalence)| {
                    registry.canonical_equivalence_key(
                        &self.plan.semantic_context,
                        *equivalence,
                        value,
                    )
                })
                .collect::<Result<Vec<_>, _>>()?;
            let entry = multiplicities
                .entry((order_class, row_key))
                .or_insert_with(|| (row.clone(), 0));
            entry.1 = entry
                .1
                .checked_add(1)
                .ok_or(RelQueryError::DerivedIdentityExhausted)?;
        }

        let mut entries = Vec::new();
        for ((order_class, row_key), (row, count)) in multiplicities {
            for occurrence in 0..count {
                entries.push(OrderedViewEntry {
                    order_class: order_class.clone(),
                    row_key: row_key.clone(),
                    occurrence,
                    row: row.clone(),
                });
            }
        }
        entries.sort_by(|left, right| self.compare_entries(left, right));
        Ok(entries)
    }

    fn compare_entries(
        &self,
        left: &OrderedViewEntry,
        right: &OrderedViewEntry,
    ) -> std::cmp::Ordering {
        let semantic = match self.spec.direction {
            OrderDirection::Ascending => left.order_class.cmp(&right.order_class),
            OrderDirection::Descending => right.order_class.cmp(&left.order_class),
        };
        semantic
            .then_with(|| left.row_key.cmp(&right.row_key))
            .then_with(|| left.occurrence.cmp(&right.occurrence))
    }

    fn compare_entry_cursor(
        &self,
        entry: &OrderedViewEntry,
        cursor: &OrderedViewCursor,
    ) -> std::cmp::Ordering {
        let semantic = match self.spec.direction {
            OrderDirection::Ascending => entry.order_class.cmp(&cursor.order_class),
            OrderDirection::Descending => cursor.order_class.cmp(&entry.order_class),
        };
        semantic
            .then_with(|| entry.row_key.cmp(&cursor.row_key))
            .then_with(|| entry.occurrence.cmp(&cursor.occurrence))
    }

    pub fn page_native_pinned(
        &self,
        store: &PhysicalStore,
        registry: &kernel_semantics::SemanticRegistry,
        after: Option<&OrderedViewCursor>,
        limit: usize,
    ) -> Result<OrderedViewPage, OrderedViewError> {
        if limit == 0 {
            return Err(OrderedViewError::ZeroPageSize);
        }
        let revision = store
            .revision()
            .ok_or(OrderedViewError::UnboundPhysicalRevision)?;
        let semantic_revision = self.plan.semantic_context.revision();
        if let Some(cursor) = after {
            self.validate_cursor(cursor, revision, semantic_revision)?;
        }

        let entries = self.ordered_entries(store, registry)?;
        let mut selected = entries
            .iter()
            .filter(|entry| {
                after.is_none_or(|cursor| self.compare_entry_cursor(entry, cursor).is_gt())
            })
            .take(limit.saturating_add(1))
            .cloned()
            .collect::<Vec<_>>();
        let has_more = selected.len() > limit;
        selected.truncate(limit);
        let next_cursor = if has_more {
            selected.last().map(|entry| {
                entry.cursor(
                    revision,
                    semantic_revision,
                    &self.plan.semantic_context,
                    self.plan.logical(),
                    &self.spec,
                )
            })
        } else {
            None
        };
        Ok(OrderedViewPage {
            rows: selected.into_iter().map(|entry| entry.row).collect(),
            next_cursor,
        })
    }
}
impl PreparedPlan {
    #[must_use]
    pub fn physical(&self) -> &Plan {
        &self.lowering.spec().physical
    }

    #[must_use]
    pub fn logical(&self) -> &RelExpr {
        &self.lowering.spec().logical
    }

    #[must_use]
    pub fn result_type(&self) -> &RelType {
        &self.result_type
    }

    #[must_use]
    pub fn semantic_context(&self) -> &kernel_schema::SemanticContext {
        &self.semantic_context
    }

    pub fn ordered_view(
        &self,
        spec: OrderedViewSpec,
        registry: &kernel_semantics::SemanticRegistry,
    ) -> Result<PreparedOrderedView<'_>, OrderedViewError> {
        let equivalences = match &self.result_type.semantics {
            kernel_schema::RelationSemantics::Set {
                column_equivalences,
            }
            | kernel_schema::RelationSemantics::Bag {
                column_equivalences,
            } => column_equivalences,
        };
        let equivalence = equivalences
            .get(spec.column)
            .copied()
            .ok_or(RelQueryError::ColumnOutOfBounds)?;
        if !registry.ordering_congruent_with_equivalence(
            &self.semantic_context,
            spec.ordering,
            equivalence,
        )? {
            return Err(RelQueryError::OrderingNotCongruentWithEquality.into());
        }
        Ok(PreparedOrderedView {
            plan: self,
            spec,
            equivalences: equivalences.clone(),
        })
    }

    /// Builds the revision-local relation-column coordinate catalog used by
    /// writable-view compilation from this already typechecked prepared plan.
    /// Coordinates are planner-owned and distinct even when several columns
    /// share the same pinned Γ-equivalence.
    pub fn writable_coordinates(
        &self,
        registry: &kernel_semantics::SemanticRegistry,
    ) -> Result<PreparedRelWritableCoordinates, WritableCoordinatePrepareError> {
        let mut catalog =
            kernel_semantics::observable::RevisionObservableCatalog::new(&self.semantic_context)?;
        let mut relation_columns = BTreeMap::new();
        let mut coordinate = 1_u64;
        for relation in self.logical().scan_relations() {
            let definition = self
                .semantic_context
                .schema
                .relation(relation)
                .ok_or(RelQueryError::UnknownRelation(relation))?;
            let equivalences = match &definition.semantics {
                kernel_schema::RelationSemantics::Set {
                    column_equivalences,
                }
                | kernel_schema::RelationSemantics::Bag {
                    column_equivalences,
                } => column_equivalences,
            };
            let mut columns = Vec::with_capacity(equivalences.len());
            for &equivalence in equivalences {
                columns.push(catalog.register_equivalence_coordinate(
                    registry,
                    &self.semantic_context,
                    equivalence,
                    coordinate,
                )?);
                coordinate = coordinate
                    .checked_add(1)
                    .ok_or(WritableCoordinatePrepareError::CoordinateOverflow)?;
            }
            relation_columns.insert(relation, columns);
        }
        Ok(PreparedRelWritableCoordinates {
            catalog,
            relation_columns,
        })
    }

    pub fn reference_execute(
        &self,
        model: &kernel_model::FiniteModel,
        context: &kernel_schema::SemanticContext,
        registry: &kernel_semantics::SemanticRegistry,
    ) -> Result<RelationValue, RelQueryError> {
        if context != &self.semantic_context {
            return Err(RelQueryError::SemanticRevisionMismatch);
        }
        self.physical().reference_execute(model, context, registry)
    }

    pub fn execute_native_pinned(
        &self,
        store: &PhysicalStore,
        registry: &kernel_semantics::SemanticRegistry,
    ) -> Result<(RelationValue, ExecutionStats), PhysicalExecutionError> {
        self.physical().execute_native_with_prepared_programs(
            store,
            &self.result_type,
            &self.semantic_context,
            registry,
            self.anchor_pullback_program.as_ref(),
            self.semantic_quotient_program.as_ref(),
        )
    }

    pub fn execute_native(
        &self,
        store: &PhysicalStore,
        context: &kernel_schema::SemanticContext,
        registry: &kernel_semantics::SemanticRegistry,
    ) -> Result<(RelationValue, ExecutionStats), PhysicalExecutionError> {
        if context != &self.semantic_context {
            return Err(RelQueryError::SemanticRevisionMismatch.into());
        }
        self.execute_native_pinned(store, registry)
    }

    fn semantic_quotient_factor_bindings(
        &self,
        store: &PhysicalStore,
    ) -> Result<BTreeSet<SemanticIndexBinding>, PhysicalExecutionError> {
        let Some(program) = &self.semantic_quotient_program else {
            return Ok(BTreeSet::new());
        };
        let mut leaves = Vec::new();
        let mut predicates = Vec::new();
        let Some(_) =
            flatten_multiway_join_tree(self.physical(), store, &mut leaves, &mut predicates)?
        else {
            return Ok(BTreeSet::new());
        };
        let mut bindings = BTreeSet::new();
        for (equivalence, endpoints) in &program.specs {
            for endpoint in endpoints {
                let leaf = leaves
                    .get(endpoint.leaf)
                    .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
                bindings.insert(SemanticIndexBinding::single(
                    leaf.relation,
                    leaf.layout,
                    endpoint.column,
                    *equivalence,
                ));
            }
        }
        Ok(bindings)
    }

    /// Materializes the exact canonical-key factors used by this prepared Γ-quotient
    /// program as dedicated reconstructible physical state. Factor states reuse the same
    /// canonical index implementation and atomic relation-delta maintenance law as ordinary
    /// semantic indexes, but do not participate in ordinary Join access-path selection. An
    /// explicit call transfers the requested factors out of advisor ownership, pinning them as
    /// manually managed reconstructible state until their relation/layout is invalidated.
    pub fn materialize_semantic_quotient_factors(
        &self,
        store: &mut PhysicalStore,
        registry: &kernel_semantics::SemanticRegistry,
    ) -> Result<usize, PhysicalExecutionError> {
        let bindings = self.semantic_quotient_factor_bindings(store)?;
        let mut prepared = Vec::new();
        for binding in &bindings {
            let compatible = match store.semantic_quotient_factors.get(binding) {
                Some(state) => state.compatible_with(&self.semantic_context, registry)?,
                None => false,
            };
            if compatible {
                continue;
            }
            let relation = store.installed(binding.relation, binding.layout)?;
            prepared.push((
                binding.clone(),
                MaterializedSemanticQuotientFactorState::build(
                    binding.clone(),
                    relation,
                    &self.semantic_context,
                    registry,
                )?,
            ));
        }
        let releases_advisor_ownership = bindings.iter().any(|binding| {
            store
                .advisor_managed_artifacts
                .contains(&UnifiedArtifactId::SemanticQuotientFactor(binding.clone()))
        });
        if prepared.is_empty() && !releases_advisor_ownership {
            return Ok(0);
        }
        let next_epoch = store
            .transition_epoch
            .checked_add(1)
            .ok_or(PhysicalExecutionError::TransitionEpochExhausted)?;
        let count = prepared.len();
        for (binding, state) in prepared {
            store
                .semantic_quotient_factors_mut()
                .insert(binding, Arc::new(state));
        }
        for binding in bindings {
            store
                .advisor_managed_artifacts_mut()
                .remove(&UnifiedArtifactId::SemanticQuotientFactor(binding));
        }
        store.transition_epoch = next_epoch;
        store.state_identity = Arc::new(());
        Ok(count)
    }

    /// Materializes the exact Γ-QCN common-domain/support fixed point as reconstructible
    /// physical state. This is a `Change<state>` Replace fallback: subsequent relation deltas
    /// rebuild the derived fixed point atomically from already-maintained canonical factors,
    /// so execution no longer recomputes the fixed point. Fine-grained support propagation is
    /// a separate optimization and is not required for correctness.
    pub fn materialize_semantic_quotient_support(
        &self,
        store: &mut PhysicalStore,
        registry: &kernel_semantics::SemanticRegistry,
    ) -> Result<bool, PhysicalExecutionError> {
        let Some(program) = &self.semantic_quotient_program else {
            return Ok(false);
        };
        let _ = self.materialize_semantic_quotient_factors(store, registry)?;
        let mut leaves = Vec::new();
        let mut predicates = Vec::new();
        let Some(_) =
            flatten_multiway_join_tree(self.physical(), store, &mut leaves, &mut predicates)?
        else {
            return Ok(false);
        };
        let binding = semantic_quotient_support_binding(&leaves, program);
        let state = build_semantic_quotient_support_state(
            binding.clone(),
            store,
            &self.semantic_context,
            registry,
        )?
        .ok_or(RelQueryError::InconsistentIncrementalDelta)?;
        if store
            .semantic_quotient_supports
            .get(&binding)
            .is_some_and(|existing| existing.as_ref() == &state)
        {
            return Ok(false);
        }
        let next_epoch = store
            .transition_epoch
            .checked_add(1)
            .ok_or(PhysicalExecutionError::TransitionEpochExhausted)?;
        store
            .semantic_quotient_supports_mut()
            .insert(binding, Arc::new(state));
        store.transition_epoch = next_epoch;
        store.state_identity = Arc::new(());
        Ok(true)
    }
}

pub fn prepare_baseline(
    logical: RelExpr,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
) -> Result<PreparedPlan, PlanPrepareError> {
    let prepared = logical.prepare(context, registry)?;
    let result_type = prepared.result_type().clone();
    let lowering = certify_baseline_lowering(logical)?;
    let anchor_pullback_program =
        prepare_anchor_pullback_program(&lowering.spec().physical, context)?;
    let semantic_quotient_program =
        prepare_semantic_quotient_program(&lowering.spec().physical, context, registry)?;
    Ok(PreparedPlan {
        lowering,
        result_type,
        semantic_context: context.clone(),
        anchor_pullback_program,
        semantic_quotient_program,
    })
}

pub fn certify_baseline_lowering(
    logical: RelExpr,
) -> Result<kernel_proof::CheckedCertificate<LoweringChecker>, LoweringError> {
    let physical = Plan::lower_baseline(&logical);
    let spec = LoweringSpec { logical, physical };
    kernel_proof::verify_certificate::<LoweringChecker>(
        &spec,
        LoweringCertificate::ExactLogicalRoundTrip,
    )
}

pub fn certify_lowering_with_catalog(
    logical: RelExpr,
    catalog: &PhysicalCatalog,
) -> Result<kernel_proof::CheckedCertificate<LoweringChecker>, LoweringError> {
    let physical = Plan::lower_with_catalog(&logical, catalog);
    let spec = LoweringSpec { logical, physical };
    kernel_proof::verify_certificate::<LoweringChecker>(
        &spec,
        LoweringCertificate::ExactLogicalRoundTrip,
    )
}

pub fn prepare_with_catalog(
    logical: RelExpr,
    context: &kernel_schema::SemanticContext,
    registry: &kernel_semantics::SemanticRegistry,
    catalog: &PhysicalCatalog,
) -> Result<PreparedPlan, PlanPrepareError> {
    let prepared = logical.prepare(context, registry)?;
    let result_type = prepared.result_type().clone();
    let lowering = certify_lowering_with_catalog(logical, catalog)?;
    let anchor_pullback_program =
        prepare_anchor_pullback_program(&lowering.spec().physical, context)?;
    let semantic_quotient_program =
        prepare_semantic_quotient_program(&lowering.spec().physical, context, registry)?;
    Ok(PreparedPlan {
        lowering,
        result_type,
        semantic_context: context.clone(),
        anchor_pullback_program,
        semantic_quotient_program,
    })
}

