    #[test]
    fn gamma_quotient_support_fixpoint_propagates_across_coordinates() {
        let q1 = sid(740);
        let q2 = sid(741);
        let a = kernel_semantics::CanonicalEqKey::TextExact("a".into());
        let b = kernel_semantics::CanonicalEqKey::TextExact("b".into());
        let x = kernel_semantics::CanonicalEqKey::TextExact("x".into());
        let y = kernel_semantics::CanonicalEqKey::TextExact("y".into());
        let mut cache = SemanticQuotientKeyCache::new();
        cache.insert((0, 0, q1), vec![a.clone()]);
        cache.insert((1, 0, q1), vec![a, b]);
        cache.insert((1, 1, q2), vec![x.clone(), y]);
        cache.insert((2, 0, q2), vec![x]);
        let q1_leaves = vec![
            quotient_leaf_keys(0, &[0], q1, 1, &cache).unwrap(),
            quotient_leaf_keys(1, &[0], q1, 2, &cache).unwrap(),
        ];
        let q2_leaves = vec![
            quotient_leaf_keys(1, &[1], q2, 2, &cache).unwrap(),
            quotient_leaf_keys(2, &[0], q2, 1, &cache).unwrap(),
        ];
        let q1_support = quotient_key_leaf_support(&q1_leaves);
        let q2_support = quotient_key_leaf_support(&q2_leaves);
        let mut constraints = vec![
            SemanticQuotientConstraint {
                live_key_leaf_support: q1_support.clone(),
                key_leaf_support: q1_support,
                leaves: q1_leaves,
            },
            SemanticQuotientConstraint {
                live_key_leaf_support: q2_support.clone(),
                key_leaf_support: q2_support,
                leaves: q2_leaves,
            },
        ];
        let handles = vec![
            vec![PhysicalRowId {
                slot: 0,
                generation: 0,
            }],
            vec![
                PhysicalRowId {
                    slot: 1,
                    generation: 0,
                },
                PhysicalRowId {
                    slot: 2,
                    generation: 0,
                },
            ],
            vec![PhysicalRowId {
                slot: 3,
                generation: 0,
            }],
        ];
        let mut legacy_constraints = constraints.clone();
        let legacy_masks = quotient_support_masks_legacy(&handles, &mut legacy_constraints);
        let mut masks = quotient_support_masks(&handles, &mut constraints);
        assert_eq!(masks, legacy_masks);
        assert!(mask_contains(&masks[0], 0));
        assert!(mask_contains(&masks[1], 0));
        assert!(!mask_contains(&masks[1], 1));
        assert!(mask_contains(&masks[2], 0));

        for constraint in &mut constraints {
            remove_live_ordinal_from_constraint(constraint, 0, 0);
        }
        assert!(mask_clear(&mut masks[0], 0));
        propagate_quotient_support_deletions(&handles, &mut constraints, &mut masks, &[0]);
        assert!(masks.iter().all(|mask| mask.iter().all(|word| *word == 0)));
    }

    #[test]
    fn quotient_key_support_counts_leaves_not_duplicate_rows() {
        let equivalence = sid(749);
        let a = kernel_semantics::CanonicalEqKey::TextExact("a".into());
        let b = kernel_semantics::CanonicalEqKey::TextExact("b".into());
        let c = kernel_semantics::CanonicalEqKey::TextExact("c".into());
        let mut cache = SemanticQuotientKeyCache::new();
        cache.insert((0, 0, equivalence), vec![a.clone(), a.clone(), b.clone()]);
        cache.insert((1, 0, equivalence), vec![a.clone(), b.clone(), b.clone()]);
        cache.insert((2, 0, equivalence), vec![a.clone(), c.clone()]);
        let leaves = vec![
            quotient_leaf_keys(0, &[0], equivalence, 3, &cache).unwrap(),
            quotient_leaf_keys(1, &[0], equivalence, 3, &cache).unwrap(),
            quotient_leaf_keys(2, &[0], equivalence, 2, &cache).unwrap(),
        ];
        let support = quotient_key_leaf_support(&leaves);
        assert_eq!(support.get(&a), Some(&3));
        assert_eq!(support.get(&b), Some(&2));
        assert_eq!(support.get(&c), Some(&1));

        let mut constraint = SemanticQuotientConstraint {
            leaves,
            live_key_leaf_support: support.clone(),
            key_leaf_support: support,
        };
        let mut masks = [
            full_ordinal_mask(3),
            full_ordinal_mask(3),
            full_ordinal_mask(2),
        ];
        assert_eq!(
            constraint_viable_keys(&constraint),
            BTreeSet::from([a.clone()])
        );
        remove_live_ordinal_from_constraint(&mut constraint, 0, 0);
        assert!(mask_clear(&mut masks[0], 0));
        assert_eq!(constraint.leaves[0].live_rows_by_key.get(&a), Some(&1));
        assert_eq!(constraint.live_key_leaf_support.get(&a), Some(&3));
        assert_eq!(
            constraint_viable_keys(&constraint),
            BTreeSet::from([a.clone()])
        );
        remove_live_ordinal_from_constraint(&mut constraint, 0, 1);
        assert!(mask_clear(&mut masks[0], 1));
        assert_eq!(constraint.leaves[0].live_rows_by_key.get(&a), None);
        assert_eq!(constraint.live_key_leaf_support.get(&a), Some(&2));
        assert!(constraint_viable_keys(&constraint).is_empty());
    }

    #[test]
    fn gamma_quotient_specs_collapse_redundant_equality_clique() {
        let equivalence = sid(722);
        let mut registry = SemanticRegistry::default();
        let digest = registry.install_equivalence(EquivalenceModule::I64Exact);
        let mut environment = SemanticEnvironment::new(SemanticEnvId::new(73));
        environment.pin_module(equivalence, digest);
        let context = SemanticContext {
            schema: Schema::new(SchemaRevisionId::new(73)),
            environment,
        };
        let vertices = (0..4)
            .map(|leaf| MultiwayJoinColumnRef { leaf, column: 0 })
            .collect::<Vec<_>>();
        let mut predicates = Vec::new();
        for left in 0..vertices.len() {
            for right in (left + 1)..vertices.len() {
                predicates.push(MultiwayJoinPredicate {
                    left: vertices[left],
                    right: vertices[right],
                    equivalence,
                });
            }
        }
        assert_eq!(predicates.len(), 6);
        let specs = semantic_quotient_specs(&predicates, &context, &registry).unwrap();
        assert_eq!(specs, vec![(equivalence, vertices)]);
    }

    #[test]
    fn quotient_hypergraph_gyo_accepts_chain_and_rejects_cycle() {
        let endpoint = |leaf| MultiwayJoinColumnRef { leaf, column: 0 };
        let chain = vec![
            (sid(750), vec![endpoint(0), endpoint(1)]),
            (sid(751), vec![endpoint(1), endpoint(2)]),
            (sid(752), vec![endpoint(2), endpoint(3)]),
        ];
        let order = quotient_hypergraph_search_order(4, &chain).unwrap();
        assert_eq!(order.len(), 4);
        assert_eq!(
            order.iter().copied().collect::<BTreeSet<_>>(),
            BTreeSet::from([0, 1, 2, 3])
        );

        let cycle = vec![
            (sid(753), vec![endpoint(0), endpoint(1)]),
            (sid(754), vec![endpoint(1), endpoint(2)]),
            (sid(755), vec![endpoint(2), endpoint(0)]),
        ];
        assert!(quotient_hypergraph_search_order(3, &cycle).is_none());

        let nine_cycle = (0..9)
            .map(|leaf| {
                (
                    sid(1_700 + leaf as u64),
                    vec![endpoint(leaf), endpoint((leaf + 1) % 9)],
                )
            })
            .collect::<Vec<_>>();
        assert!(quotient_hypergraph_search_order(9, &nine_cycle).is_none());
        let cyclic_order = quotient_hypergraph_cyclic_search_order(9, &nine_cycle).unwrap();
        assert_eq!(cyclic_order.len(), 9);
        assert_eq!(
            cyclic_order.iter().copied().collect::<BTreeSet<_>>(),
            (0..9).collect::<BTreeSet<_>>()
        );
    }

    #[test]
    fn bounded_cyclic_work_certificate_uses_sparse_masks_and_rejects_bad_order() {
        let row_counts = vec![200_000_usize; 10];
        let masks = row_counts
            .iter()
            .map(|rows| {
                let mut mask = vec![0_u64; rows.div_ceil(64)];
                mask[0] = 1;
                mask
            })
            .collect::<Vec<_>>();
        let order = (0..10).collect::<Vec<_>>();
        let work =
            quotient_enumeration_work_upper_bound(&[], &masks, &row_counts, &order, None).unwrap();
        assert!(work < MAX_BOUNDED_CYCLIC_ENUMERATION_WORK);

        let dense_masks = (0..10).map(|_| vec![u64::MAX; 4]).collect::<Vec<_>>();
        let dense_rows = vec![256_usize; 10];
        let dense_work =
            quotient_enumeration_work_upper_bound(&[], &dense_masks, &dense_rows, &order, None)
                .unwrap();
        assert!(dense_work > MAX_BOUNDED_CYCLIC_ENUMERATION_WORK);

        let malformed_masks = (0..10).map(|_| vec![1_u64]).collect::<Vec<_>>();
        assert!(
            quotient_enumeration_work_upper_bound(&[], &malformed_masks, &row_counts, &order, None)
                .is_none()
        );

        let mut invalid = order;
        invalid[9] = 0;
        assert!(
            quotient_enumeration_work_upper_bound(&[], &masks, &row_counts, &invalid, None)
                .is_none()
        );
    }

